window.LANG_PACKS.fr = window.LANG_PACKS.fr || {};
window.LANG_PACKS.fr.builder = [{"id":1,"vi":"không","note":"Phủ định bằng ne ... pas kẹp quanh động từ; ne thành n' trước nguyên âm.","pivot":{"t":"ne ... pas","ph":"nơ ... PA"},"branches":[{"steps":[{"t":"parle","ph":"PARL","vi":"nói","hl":[]},{"t":"ne parle pas","ph":"nơ PARL PA","vi":"không nói","hl":["ne","pas"]},{"t":"Je ne parle pas anglais.","ph":"jơ nơ PARL pa a~-GLE","vi":"Tôi không nói tiếng Anh.","hl":["ne","pas"],"tokens":["Je","ne","parle","pas","anglais"]}]},{"steps":[{"t":"comprends","ph":"ko~-PRA~","vi":"hiểu","hl":[]},{"t":"ne comprends pas","ph":"nơ ko~-PRA~ PA","vi":"không hiểu","hl":["ne","pas"]},{"t":"Je ne comprends pas.","ph":"jơ nơ ko~-PRA~ PA","vi":"Tôi không hiểu.","hl":["ne","pas"],"tokens":["Je","ne","comprends","pas"]}]},{"steps":[{"t":"aime","ph":"EM","vi":"thích","hl":[]},{"t":"n'aime pas","ph":"NEM PA","vi":"không thích","hl":["n'","pas"]},{"t":"Je n'aime pas le café.","ph":"jơ NEM pa lơ ka-FÊ","vi":"Tôi không thích cà phê.","hl":["n'","pas"],"tokens":["Je","n'aime","pas","le","café"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"P","t":"ne (n')"},{"k":"V","t":"Động từ"},{"k":"P","t":"pas"},{"k":"O","t":"(Tân ngữ)"}],"points":["Kẹp động từ đã chia vào giữa ne và pas: ne + động từ + pas (\"Je ne parle pas\").","Trước động từ bắt đầu bằng nguyên âm hoặc h câm, ne rút thành n' (\"Je n'aime pas\").","Sau phủ định, un/une/du/de la đổi thành de hoặc d' (\"Je n'ai pas de voiture\").","Trong văn nói người Pháp hay bỏ ne, chỉ giữ pas (\"Je sais pas\"), nhưng khi viết nên giữ đủ ne ... pas."],"mistakes":[{"wrong":"Je ne pas parle anglais.","right":"Je ne parle pas anglais.","why":"pas phải đứng SAU động từ, không đứng trước như chữ \"không\" tiếng Việt."},{"wrong":"Je n'ai pas une voiture.","right":"Je n'ai pas de voiture.","why":"Sau phủ định, un/une phải đổi thành de."}],"compare":"Tiếng Việt chỉ cần một chữ \"không\" đặt trước động từ; tiếng Pháp cần hai mảnh ne ... pas kẹp hai bên động từ.","tip":"Hình dung ne ... pas như ổ bánh mì kẹp: động từ là phần nhân nằm giữa!","how":["Kẹp động từ parle vào giữa ne và pas → ne parle pas, rồi thêm chủ ngữ Je ở đầu và anglais ở cuối → Je ne parle pas anglais.","Kẹp comprends vào giữa ne và pas → ne comprends pas, rồi đặt chủ ngữ Je lên đầu → Je ne comprends pas.","aime bắt đầu bằng nguyên âm nên ne rút thành n' → n'aime pas, rồi thêm Je ở đầu và le café ở cuối → Je n'aime pas le café."],"dialog":[{"who":"A","t":"Vous parlez français ?","ph":"vu par-LÊ fra~-XÊ","vi":"Anh nói được tiếng Pháp không?","hl":[]},{"who":"B","t":"Non, je ne parle pas bien français.","ph":"NO~ jơ nơ PARL pa BIE~ fra~-XÊ","vi":"Không, tôi nói tiếng Pháp không giỏi.","hl":["ne","pas"]},{"who":"A","t":"Vous n'êtes pas d'ici ?","ph":"vu NET pa đi-XI","vi":"Anh không phải người ở đây à?","hl":["n'","pas"]},{"who":"B","t":"Non, je ne suis pas d'ici.","ph":"NO~ jơ nơ XUY pa đi-XI","vi":"Không, tôi không phải người ở đây.","hl":["ne","pas"]}],"more":[{"t":"Je ne sais pas.","ph":"jơ nơ XÊ PA","vi":"Tôi không biết.","hl":["ne","pas"],"tokens":["Je","ne","sais","pas"]},{"t":"Il ne mange pas de viande.","ph":"il nơ MA~J pa đơ VIA~Đ","vi":"Anh ấy không ăn thịt.","hl":["ne","pas"],"tokens":["Il","ne","mange","pas","de","viande"]},{"t":"Je n'ai pas de monnaie.","ph":"jơ NÊ pa đơ mo-NE","vi":"Tôi không có tiền lẻ.","hl":["n'","pas"],"tokens":["Je","n'ai","pas","de","monnaie"]},{"t":"Elle n'habite pas à Paris.","ph":"el na-BIT pa a pa-RI","vi":"Cô ấy không sống ở Paris.","hl":["n'","pas"],"tokens":["Elle","n'habite","pas","à","Paris"]},{"t":"Nous ne prenons pas le bus ce soir.","ph":"nu nơ prơ-NO~ pa lơ BUYT xơ SOAR","vi":"Tối nay chúng tôi không đi xe buýt.","hl":["ne","pas"],"tokens":["Nous","ne","prenons","pas","le","bus","ce","soir"]},{"t":"Je ne trouve pas mon passeport à l'hôtel.","ph":"jơ nơ TRUV pa mo~ pas-PÔR a lô-TEL","vi":"Tôi không tìm thấy hộ chiếu ở khách sạn.","hl":["ne","pas"],"tokens":["Je","ne","trouve","pas","mon","passeport","à","l'hôtel"]}]},{"id":2,"vi":"có","note":"Avoir (có) chia theo chủ ngữ: j'ai, tu as, il/elle a, nous avons, vous avez.","pivot":{"t":"avoir","ph":"a-VOAR"},"branches":[{"steps":[{"t":"chambre","ph":"SHA~-BR","vi":"phòng","hl":[]},{"t":"avez une chambre","ph":"a-VÊ uyn SHA~-BR","vi":"có một phòng","hl":["avez"]},{"t":"Vous avez une chambre libre ?","ph":"vu-za-VÊ uyn sha~-br LI-BR","vi":"Anh chị có phòng trống không?","hl":["avez"],"tokens":["Vous","avez","une","chambre","libre"]}]},{"steps":[{"t":"billet","ph":"bi-YÊ","vi":"vé","hl":[]},{"t":"ai un billet","ph":"ê a~ bi-YÊ","vi":"có một vé","hl":["ai"]},{"t":"J'ai un billet pour Paris.","ph":"JÊ a~ bi-YÊ pur pa-RI","vi":"Tôi có một vé đi Paris.","hl":["ai"],"tokens":["J'ai","un","billet","pour","Paris"]}]},{"steps":[{"t":"enfants","ph":"a~-FA~","vi":"con cái","hl":[]},{"t":"avons deux enfants","ph":"a-VO~ đơ-za~-FA~","vi":"có hai đứa con","hl":["avons"]},{"t":"Nous avons deux enfants.","ph":"nu-za-VO~ đơ-za~-FA~","vi":"Chúng tôi có hai đứa con.","hl":["avons"],"tokens":["Nous","avons","deux","enfants"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"P","t":"avoir"},{"k":"O","t":"un/une + Danh từ"}],"points":["Avoir chia theo chủ ngữ: j'ai, tu as, il/elle a, nous avons, vous avez, ils ont.","Je đứng trước ai phải rút thành J'ai; vous avez, nous avons đọc nối âm z (vu-za-VÊ, nu-za-VO~).","Danh từ sau avoir thường có un/une hoặc số đếm đi kèm (\"J'ai un billet\", \"deux enfants\").","Tiếng Pháp dùng avoir để nói tuổi, đói, khát: \"J'ai 20 ans\", \"J'ai faim\"."],"mistakes":[{"wrong":"Je suis 25 ans.","right":"J'ai 25 ans.","why":"Nói tuổi phải dùng avoir (có 25 năm), không dùng être (là)."},{"wrong":"Je ai un billet.","right":"J'ai un billet.","why":"Je đứng trước nguyên âm phải rút thành J'."}],"compare":"Giống tiếng Việt ở trật tự Chủ ngữ + có + vật; khác ở chỗ avoir đổi dạng theo từng chủ ngữ và còn dùng cho tuổi, đói, khát.","tip":"Đọc như rap 6 nhịp: j'ai - tu as - il a - nous avons - vous avez - ils ont!","how":["Chia avoir với vous thành avez rồi thêm une chambre → avez une chambre, sau đó đặt Vous lên đầu, libre ở cuối và lên giọng hỏi → Vous avez une chambre libre ?","Chia avoir với je thành ai rồi thêm un billet → ai un billet, sau đó ghép Je + ai thành J'ai và thêm pour Paris → J'ai un billet pour Paris.","Chia avoir với nous thành avons rồi thêm deux enfants → avons deux enfants, sau đó đặt Nous lên đầu (đọc nối nu-za-VO~) → Nous avons deux enfants."],"dialog":[{"who":"A","t":"Vous avez une réservation ?","ph":"vu-za-VÊ uyn rê-zer-va-XIO~","vi":"Anh có đặt chỗ trước không?","hl":["avez"]},{"who":"B","t":"Oui, j'ai une réservation pour deux.","ph":"UY JÊ uyn rê-zer-va-XIO~ pur ĐƠ","vi":"Có, tôi đã đặt chỗ cho hai người.","hl":["ai"]},{"who":"A","t":"Vous avez des bagages ?","ph":"vu-za-VÊ đê ba-GAJ","vi":"Anh có hành lý không?","hl":["avez"]},{"who":"B","t":"Oui, j'ai une grande valise.","ph":"UY JÊ uyn gra~đ va-LIZ","vi":"Có, tôi có một va li lớn.","hl":["ai"]}],"more":[{"t":"J'ai très faim.","ph":"JÊ TRE FE~","vi":"Tôi rất đói.","hl":["ai"],"tokens":["J'ai","très","faim"]},{"t":"Tu as un stylo ?","ph":"tuy A a~ xti-LÔ","vi":"Bạn có bút không?","hl":["as"],"tokens":["Tu","as","un","stylo"]},{"t":"Elle a vingt-cinq ans.","ph":"e-LA ve~t-xe~-KA~","vi":"Cô ấy 25 tuổi.","hl":["a"],"tokens":["Elle","a","vingt-cinq","ans"]},{"t":"Nous avons une question.","ph":"nu-za-VO~ uyn kết-TIO~","vi":"Chúng tôi có một câu hỏi.","hl":["avons"],"tokens":["Nous","avons","une","question"]},{"t":"Ils ont une maison à Lyon.","ph":"il-ZO~ uyn me-ZO~ a li-O~","vi":"Họ có một ngôi nhà ở Lyon.","hl":["ont"],"tokens":["Ils","ont","une","maison","à","Lyon"]},{"t":"Vous avez une table pour quatre personnes ?","ph":"vu-za-VÊ uyn TA-BL pur KA-TR per-XÔN","vi":"Anh có bàn cho bốn người không?","hl":["avez"],"tokens":["Vous","avez","une","table","pour","quatre","personnes"]}]},{"id":3,"vi":"là","note":"Être (là) chia theo chủ ngữ: je suis, il/elle est, vous êtes; nghề nghiệp, quốc tịch không cần mạo từ.","pivot":{"t":"être","ph":"E-TR"},"branches":[{"steps":[{"t":"étudiant","ph":"ê-tuy-ĐIA~","vi":"sinh viên","hl":[]},{"t":"suis étudiant","ph":"XUY-zê-tuy-ĐIA~","vi":"là sinh viên","hl":["suis"]},{"t":"Je suis étudiant vietnamien.","ph":"jơ XUY-zê-tuy-ĐIA~ viết-na-MIE~","vi":"Tôi là sinh viên Việt Nam.","hl":["suis"],"tokens":["Je","suis","étudiant","vietnamien"]}]},{"steps":[{"t":"médecin","ph":"mết-XE~","vi":"bác sĩ","hl":[]},{"t":"est médecin","ph":"e mết-XE~","vi":"là bác sĩ","hl":["est"]},{"t":"Mon père est médecin.","ph":"mo~ PER e mết-XE~","vi":"Bố tôi là bác sĩ.","hl":["est"],"tokens":["Mon","père","est","médecin"]}]},{"steps":[{"t":"français","ph":"fra~-XÊ","vi":"người Pháp","hl":[]},{"t":"êtes français","ph":"ET fra~-XÊ","vi":"là người Pháp","hl":["êtes"]},{"t":"Vous êtes français ?","ph":"vu-ZET fra~-XÊ","vi":"Anh là người Pháp à?","hl":["êtes"],"tokens":["Vous","êtes","français"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"P","t":"être"},{"k":"O","t":"Nghề / Quốc tịch / Tính từ"}],"points":["Être chia theo chủ ngữ: je suis, tu es, il/elle est, nous sommes, vous êtes, ils sont.","Nói nghề nghiệp, quốc tịch thì KHÔNG dùng mạo từ (\"Il est médecin\", không nói \"un médecin\").","Tính từ sau être hợp giống, số với chủ ngữ (\"Il est fatigué\" / \"Elle est fatiguée\").","Vous êtes đọc nối thành vu-ZET; muốn hỏi chỉ cần lên giọng cuối câu (\"Vous êtes français ?\")."],"mistakes":[{"wrong":"Il est un médecin.","right":"Il est médecin.","why":"Nghề nghiệp đứng sau être không dùng un/une."},{"wrong":"Je suis faim.","right":"J'ai faim.","why":"Đói, khát, tuổi dùng avoir chứ không dùng être."}],"compare":"Giống tiếng Việt: Chủ ngữ + là + danh từ; nhưng tiếng Pháp còn đặt être trước tính từ (\"Elle est belle\" = cô ấy đẹp), trong khi tiếng Việt không cần chữ \"là\".","tip":"suis - es - est - sommes - êtes - sont: sáu dạng khác hẳn nhau, đọc to mỗi ngày như đếm từ 1 đến 6.","how":["Chia être với je thành suis, đặt trước étudiant (đọc nối XUY-zê) → suis étudiant, rồi thêm Je ở đầu và vietnamien ở cuối → Je suis étudiant vietnamien.","Chia être với ngôi thứ ba thành est, đặt trước médecin mà không cần mạo từ → est médecin, rồi thêm chủ ngữ Mon père → Mon père est médecin.","Chia être với vous thành êtes, đặt trước français → êtes français, rồi thêm Vous ở đầu và lên giọng cuối câu → Vous êtes français ?"],"dialog":[{"who":"A","t":"Vous êtes touriste ?","ph":"vu-ZET tu-RIST","vi":"Anh là khách du lịch à?","hl":["êtes"]},{"who":"B","t":"Non, je suis ingénieur.","ph":"NO~ jơ XUY-ze~-jê-NIƠR","vi":"Không, tôi là kỹ sư.","hl":["suis"]},{"who":"A","t":"Votre collègue est vietnamien aussi ?","ph":"vo-trơ ko-LEG e viết-na-MIE~ ô-XI","vi":"Đồng nghiệp của anh cũng là người Việt à?","hl":["est"]},{"who":"B","t":"Oui, il est de Hanoï.","ph":"UY i-LE đơ a-nô-I","vi":"Vâng, anh ấy đến từ Hà Nội.","hl":["est"]}],"more":[{"t":"Je suis fatigué.","ph":"jơ XUY fa-ti-GHÊ","vi":"Tôi mệt.","hl":["suis"],"tokens":["Je","suis","fatigué"]},{"t":"Tu es étudiante ?","ph":"tuy E-zê-tuy-ĐIA~T","vi":"Bạn là sinh viên à?","hl":["es"],"tokens":["Tu","es","étudiante"]},{"t":"La chambre est très propre.","ph":"la SHA~-BR e TRE PRO-PR","vi":"Căn phòng rất sạch.","hl":["est"],"tokens":["La","chambre","est","très","propre"]},{"t":"Nous sommes en vacances.","ph":"nu xom-za~ va-KA~X","vi":"Chúng tôi đang đi nghỉ.","hl":["sommes"],"tokens":["Nous","sommes","en","vacances"]},{"t":"Ils sont très gentils avec nous.","ph":"il XO~ TRE ja~-TI a-VEK NU","vi":"Họ rất tử tế với chúng tôi.","hl":["sont"],"tokens":["Ils","sont","très","gentils","avec","nous"]},{"t":"Mon frère est professeur dans une école.","ph":"mo~ FRER e pro-fe-XƠR đa~-zuy-nê-KOL","vi":"Anh trai tôi là giáo viên ở một trường học.","hl":["est"],"tokens":["Mon","frère","est","professeur","dans","une","école"]}]},{"id":4,"vi":"muốn","note":"Vouloir (muốn) + động từ nguyên mẫu hoặc danh từ; je voudrais là cách nói lịch sự hơn je veux.","pivot":{"t":"vouloir","ph":"vu-LOAR"},"branches":[{"steps":[{"t":"café","ph":"ka-FÊ","vi":"cà phê","hl":[]},{"t":"voudrais un café","ph":"vu-ĐRÊ a~ ka-FÊ","vi":"muốn một ly cà phê","hl":["voudrais"]},{"t":"Je voudrais un café s'il vous plaît.","ph":"jơ vu-ĐRÊ a~ ka-FÊ xin vu PLÊ","vi":"Tôi muốn một ly cà phê ạ.","hl":["voudrais"],"tokens":["Je","voudrais","un","café","s'il","vous","plaît"]}]},{"steps":[{"t":"partir","ph":"par-TIR","vi":"đi, khởi hành","hl":[]},{"t":"veux partir","ph":"VƠ par-TIR","vi":"muốn đi","hl":["veux"]},{"t":"Je veux partir demain.","ph":"jơ VƠ par-TIR đơ-ME~","vi":"Tôi muốn đi vào ngày mai.","hl":["veux"],"tokens":["Je","veux","partir","demain"]}]},{"steps":[{"t":"voir","ph":"VOAR","vi":"xem","hl":[]},{"t":"voulez voir","ph":"vu-LÊ VOAR","vi":"muốn xem","hl":["voulez"]},{"t":"Vous voulez voir le menu ?","ph":"vu vu-LÊ VOAR lơ mơ-NUY","vi":"Anh có muốn xem thực đơn không?","hl":["voulez"],"tokens":["Vous","voulez","voir","le","menu"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"P","t":"vouloir"},{"k":"O","t":"Danh từ / Động từ nguyên mẫu"}],"points":["Vouloir chia: je veux, tu veux, il veut, nous voulons, vous voulez, ils veulent.","Sau vouloir là danh từ (\"Je veux un café\") hoặc động từ nguyên mẫu (\"Je veux partir\").","Khi gọi món hay nhờ vả, dùng je voudrais (tôi muốn ạ) để lịch sự hơn je veux.","Vous voulez + động từ nguyên mẫu dùng để mời (\"Vous voulez boire quelque chose ?\")."],"mistakes":[{"wrong":"Je veux de partir.","right":"Je veux partir.","why":"Sau vouloir đặt thẳng động từ nguyên mẫu, không thêm de."},{"wrong":"Je veux un café.","right":"Je voudrais un café.","why":"Ở quán, je veux nghe hơi cộc như ra lệnh; je voudrais lịch sự hơn nhiều."}],"compare":"Giống tiếng Việt: muốn + vật/việc đặt ngay sau; khác ở chỗ tiếng Pháp có dạng lịch sự riêng je voudrais, giống như thêm chữ \"ạ\" trong tiếng Việt.","tip":"Gọi món cứ mở đầu bằng \"Je voudrais...\" là vừa lịch sự vừa an toàn.","how":["Dùng dạng lịch sự voudrais đặt trước un café → voudrais un café, rồi thêm Je ở đầu và s'il vous plaît ở cuối → Je voudrais un café s'il vous plaît.","Chia vouloir với je thành veux, đặt trước động từ nguyên mẫu partir → veux partir, rồi thêm Je ở đầu và demain ở cuối → Je veux partir demain.","Chia vouloir với vous thành voulez, đặt trước voir → voulez voir, rồi thêm Vous ở đầu, le menu ở cuối và lên giọng hỏi → Vous voulez voir le menu ?"],"dialog":[{"who":"A","t":"Bonjour, vous voulez commander ?","ph":"bo~-JUR vu vu-LÊ ko-ma~-ĐÊ","vi":"Chào anh, anh muốn gọi món chưa?","hl":["voulez"]},{"who":"B","t":"Oui, je voudrais une soupe.","ph":"UY jơ vu-ĐRÊ uyn XUP","vi":"Vâng, tôi muốn một bát súp.","hl":["voudrais"]},{"who":"A","t":"Vous voulez boire quelque chose ?","ph":"vu vu-LÊ BOAR kel-kơ SHÔZ","vi":"Anh muốn uống gì không?","hl":["voulez"]},{"who":"B","t":"Je veux juste de l'eau.","ph":"jơ VƠ JUYST đơ LÔ","vi":"Tôi chỉ muốn nước lọc thôi.","hl":["veux"]}],"more":[{"t":"Je veux dormir.","ph":"jơ VƠ đor-MIR","vi":"Tôi muốn ngủ.","hl":["veux"],"tokens":["Je","veux","dormir"]},{"t":"Tu veux venir avec moi ?","ph":"tuy VƠ vơ-NIR a-VEK MOA","vi":"Bạn muốn đi cùng tôi không?","hl":["veux"],"tokens":["Tu","veux","venir","avec","moi"]},{"t":"Je voudrais une chambre double.","ph":"jơ vu-ĐRÊ uyn SHA~-BR ĐU-BL","vi":"Tôi muốn một phòng đôi.","hl":["voudrais"],"tokens":["Je","voudrais","une","chambre","double"]},{"t":"Elle veut acheter des souvenirs.","ph":"el VƠ ash-TÊ đê xu-vơ-NIR","vi":"Cô ấy muốn mua quà lưu niệm.","hl":["veut"],"tokens":["Elle","veut","acheter","des","souvenirs"]},{"t":"Nous voulons visiter la vieille ville.","ph":"nu vu-LO~ vi-zi-TÊ la VIEY VIL","vi":"Chúng tôi muốn tham quan khu phố cổ.","hl":["voulons"],"tokens":["Nous","voulons","visiter","la","vieille","ville"]},{"t":"Je voudrais changer mon billet pour demain.","ph":"jơ vu-ĐRÊ sha~-JÊ mo~ bi-YÊ pur đơ-ME~","vi":"Tôi muốn đổi vé sang ngày mai.","hl":["voudrais"],"tokens":["Je","voudrais","changer","mon","billet","pour","demain"]}]},{"id":5,"vi":"thích","note":"Aimer (thích) + danh từ có mạo từ xác định (le, la, les) hoặc + động từ nguyên mẫu.","pivot":{"t":"aimer","ph":"ê-MÊ"},"branches":[{"steps":[{"t":"café","ph":"ka-FÊ","vi":"cà phê","hl":[]},{"t":"aime le café","ph":"EM lơ ka-FÊ","vi":"thích cà phê","hl":["aime"]},{"t":"J'aime le café français.","ph":"JEM lơ ka-FÊ fra~-XÊ","vi":"Tôi thích cà phê Pháp.","hl":["aime"],"tokens":["J'aime","le","café","français"]}]},{"steps":[{"t":"voyager","ph":"voa-ya-JÊ","vi":"đi du lịch","hl":[]},{"t":"aime voyager","ph":"EM voa-ya-JÊ","vi":"thích đi du lịch","hl":["aime"]},{"t":"Elle aime voyager en train.","ph":"e-LEM voa-ya-JÊ a~ TRE~","vi":"Cô ấy thích đi du lịch bằng tàu hỏa.","hl":["aime"],"tokens":["Elle","aime","voyager","en","train"]}]},{"steps":[{"t":"plage","ph":"PLAJ","vi":"bãi biển","hl":[]},{"t":"aimez la plage","ph":"ê-MÊ la PLAJ","vi":"thích bãi biển","hl":["aimez"]},{"t":"Vous aimez la plage ?","ph":"vu-zê-MÊ la PLAJ","vi":"Anh có thích biển không?","hl":["aimez"],"tokens":["Vous","aimez","la","plage"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"P","t":"aimer"},{"k":"O","t":"le/la/les + Danh từ / Động từ"}],"points":["Aimer chia: j'aime, tu aimes, il/elle aime, nous aimons, vous aimez, ils aiment.","Sau aimer, danh từ chỉ sở thích luôn có mạo từ xác định le/la/les (\"J'aime le café\").","Aimer + động từ nguyên mẫu để nói thích làm gì (\"J'aime voyager\").","Muốn nói rất thích thì dùng aimer beaucoup hoặc adorer (\"J'adore la plage\")."],"mistakes":[{"wrong":"J'aime café.","right":"J'aime le café.","why":"Danh từ sau aimer phải có mạo từ le/la/les, khác tiếng Việt."},{"wrong":"Je aime voyager.","right":"J'aime voyager.","why":"Je đứng trước nguyên âm a phải rút thành J'."}],"compare":"Trật tự giống tiếng Việt (Tôi thích cà phê); khác ở chỗ tiếng Pháp bắt buộc có le/la/les trước danh từ chỉ sở thích chung.","tip":"Thích cái gì thì \"đội mũ\" le/la/les cho nó: J'aime LE café, J'aime LA plage.","how":["Chia aimer với je thành aime rồi thêm le café → aime le café, sau đó ghép Je + aime thành J'aime và thêm français → J'aime le café français.","Đặt động từ nguyên mẫu voyager ngay sau aime → aime voyager, rồi thêm Elle ở đầu (đọc nối e-LEM) và en train ở cuối → Elle aime voyager en train.","Chia aimer với vous thành aimez rồi thêm la plage → aimez la plage, sau đó đặt Vous lên đầu và lên giọng hỏi → Vous aimez la plage ?"],"dialog":[{"who":"A","t":"Tu aimes la cuisine vietnamienne ?","ph":"tuy EM la kuy-ZIN viết-na-MIEN","vi":"Bạn thích món ăn Việt Nam không?","hl":["aimes"]},{"who":"B","t":"Oui, j'aime beaucoup le phở.","ph":"UY JEM bô-KU lơ FƠ","vi":"Có, tôi rất thích phở.","hl":["aime"]},{"who":"A","t":"Et tu aimes cuisiner ?","ph":"ê tuy EM kuy-zi-NÊ","vi":"Thế bạn có thích nấu ăn không?","hl":["aimes"]},{"who":"B","t":"Non, je préfère manger dehors.","ph":"NO~ jơ prê-FER ma~-JÊ đơ-OR","vi":"Không, tôi thích ăn ở ngoài hơn.","hl":[]}],"more":[{"t":"J'aime la musique.","ph":"JEM la muy-ZIK","vi":"Tôi thích âm nhạc.","hl":["aime"],"tokens":["J'aime","la","musique"]},{"t":"Tu aimes le thé ?","ph":"tuy EM lơ TÊ","vi":"Bạn thích trà không?","hl":["aimes"],"tokens":["Tu","aimes","le","thé"]},{"t":"Il aime marcher le matin.","ph":"i-LEM mar-SHÊ lơ ma-TE~","vi":"Anh ấy thích đi bộ buổi sáng.","hl":["aime"],"tokens":["Il","aime","marcher","le","matin"]},{"t":"Nous aimons les petits villages.","ph":"nu-zê-MO~ lê pơ-ti vi-LAJ","vi":"Chúng tôi thích những ngôi làng nhỏ.","hl":["aimons"],"tokens":["Nous","aimons","les","petits","villages"]},{"t":"Mes enfants aiment beaucoup la mer.","ph":"mê-za~-FA~ EM bô-KU la MER","vi":"Các con tôi rất thích biển.","hl":["aiment"],"tokens":["Mes","enfants","aiment","beaucoup","la","mer"]},{"t":"Vous aimez manger au restaurant le soir ?","ph":"vu-zê-MÊ ma~-JÊ ô res-tô-RA~ lơ SOAR","vi":"Anh có thích ăn nhà hàng buổi tối không?","hl":["aimez"],"tokens":["Vous","aimez","manger","au","restaurant","le","soir"]}]},{"id":6,"vi":"cần","note":"Avoir besoin de (cần) + danh từ hoặc động từ nguyên mẫu; de thành d' trước nguyên âm.","pivot":{"t":"avoir besoin de","ph":"a-VOAR bơ-ZOE~ đơ"},"branches":[{"steps":[{"t":"taxi","ph":"tắc-XI","vi":"taxi","hl":[]},{"t":"besoin d'un taxi","ph":"bơ-ZOE~ đa~ tắc-XI","vi":"cần một taxi","hl":["besoin","d'"]},{"t":"J'ai besoin d'un taxi.","ph":"JÊ bơ-ZOE~ đa~ tắc-XI","vi":"Tôi cần một chiếc taxi.","hl":["J'ai","besoin","d'"],"tokens":["J'ai","besoin","d'un","taxi"]}]},{"steps":[{"t":"aide","ph":"ĐED","vi":"sự giúp đỡ","hl":[]},{"t":"besoin d'aide","ph":"bơ-ZOE~ ĐED","vi":"cần giúp đỡ","hl":["besoin","d'"]},{"t":"Nous avons besoin d'aide.","ph":"nu-za-VO~ bơ-ZOE~ ĐED","vi":"Chúng tôi cần giúp đỡ.","hl":["avons","besoin","d'"],"tokens":["Nous","avons","besoin","d'aide"]}]},{"steps":[{"t":"dormir","ph":"đor-MIR","vi":"ngủ","hl":[]},{"t":"besoin de dormir","ph":"bơ-ZOE~ đơ đor-MIR","vi":"cần ngủ","hl":["besoin","de"]},{"t":"J'ai besoin de dormir un peu.","ph":"JÊ bơ-ZOE~ đơ đor-MIR a~ PƠ","vi":"Tôi cần ngủ một chút.","hl":["J'ai","besoin","de"],"tokens":["J'ai","besoin","de","dormir","un","peu"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"P","t":"avoir besoin de (d')"},{"k":"O","t":"Danh từ / Động từ nguyên mẫu"}],"points":["Cấu trúc cố định: avoir (chia theo chủ ngữ) + besoin + de, dịch sát là \"có nhu cầu về\".","Sau de là danh từ (\"besoin d'un taxi\") hoặc động từ nguyên mẫu (\"besoin de dormir\").","De rút thành d' trước nguyên âm hoặc h câm (\"besoin d'aide\", \"besoin d'un médecin\").","Phủ định thì kẹp avoir: \"Je n'ai pas besoin de sac\" (tôi không cần túi)."],"mistakes":[{"wrong":"Je besoin un taxi.","right":"J'ai besoin d'un taxi.","why":"Không có động từ \"cần\" đứng một mình: phải có avoir (J'ai) và de trước danh từ."},{"wrong":"J'ai besoin de aide.","right":"J'ai besoin d'aide.","why":"De gặp nguyên âm phải rút thành d'."}],"compare":"Tiếng Việt chỉ cần một chữ \"cần\"; tiếng Pháp phải nói thành cụm ba mảnh avoir + besoin + de, nhưng trật tự Chủ ngữ + cần + vật vẫn giống.","tip":"Cần gì thì nhớ \"J'ai besoin de...\" như một câu thần chú dính liền, đừng tách ra.","how":["Ghép besoin + d' (vì un bắt đầu bằng nguyên âm) + un taxi → besoin d'un taxi, rồi thêm J'ai ở đầu → J'ai besoin d'un taxi.","aide bắt đầu bằng nguyên âm nên de rút thành d' → besoin d'aide, rồi thêm Nous avons ở đầu (đọc nối nu-za-VO~) → Nous avons besoin d'aide.","Đặt động từ nguyên mẫu dormir sau besoin de → besoin de dormir, rồi thêm J'ai ở đầu và un peu ở cuối → J'ai besoin de dormir un peu."],"dialog":[{"who":"A","t":"Bonjour, vous avez besoin d'aide ?","ph":"bo~-JUR vu-za-VÊ bơ-ZOE~ ĐED","vi":"Chào anh, anh cần giúp gì không?","hl":["besoin d'"]},{"who":"B","t":"Oui, j'ai besoin d'une pharmacie.","ph":"UY JÊ bơ-ZOE~ đuyn far-ma-XI","vi":"Vâng, tôi cần tìm hiệu thuốc.","hl":["besoin d'"]},{"who":"A","t":"Il y en a une à côté.","ph":"i-li-a~-NA uyn a kô-TÊ","vi":"Có một hiệu ngay bên cạnh.","hl":[]},{"who":"B","t":"Merci, j'ai besoin de médicaments.","ph":"mer-XI JÊ bơ-ZOE~ đơ mê-đi-ka-MA~","vi":"Cảm ơn, tôi cần mua thuốc.","hl":["besoin de"]}],"more":[{"t":"J'ai besoin d'eau.","ph":"JÊ bơ-ZOE~ ĐÔ","vi":"Tôi cần nước.","hl":["besoin d'"],"tokens":["J'ai","besoin","d'eau"]},{"t":"Tu as besoin d'un parapluie ?","ph":"tuy A bơ-ZOE~ đa~ pa-ra-PLUY","vi":"Bạn có cần ô không?","hl":["besoin d'"],"tokens":["Tu","as","besoin","d'un","parapluie"]},{"t":"Elle a besoin de repos.","ph":"e-LA bơ-ZOE~ đơ rơ-PÔ","vi":"Cô ấy cần nghỉ ngơi.","hl":["besoin de"],"tokens":["Elle","a","besoin","de","repos"]},{"t":"Nous avons besoin d'une carte de la ville.","ph":"nu-za-VO~ bơ-ZOE~ đuyn KART đơ la VIL","vi":"Chúng tôi cần một tấm bản đồ thành phố.","hl":["besoin d'"],"tokens":["Nous","avons","besoin","d'une","carte","de","la","ville"]},{"t":"Je n'ai pas besoin de sac.","ph":"jơ NÊ pa bơ-ZOE~ đơ XAK","vi":"Tôi không cần túi.","hl":["besoin de"],"tokens":["Je","n'ai","pas","besoin","de","sac"]},{"t":"Vous avez besoin de changer de l'argent ?","ph":"vu-za-VÊ bơ-ZOE~ đơ sha~-JÊ đơ lar-JA~","vi":"Anh có cần đổi tiền không?","hl":["besoin de"],"tokens":["Vous","avez","besoin","de","changer","de","l'argent"]}]},{"id":7,"vi":"có thể","note":"Pouvoir (có thể) + động từ nguyên mẫu, dùng để nói khả năng hoặc xin phép: je peux, vous pouvez, on peut.","pivot":{"t":"pouvoir","ph":"pu-VOAR"},"branches":[{"steps":[{"t":"payer","ph":"pê-YÊ","vi":"trả tiền","hl":[]},{"t":"peux payer","ph":"PƠ pê-YÊ","vi":"có thể trả tiền","hl":["peux"]},{"t":"Je peux payer par carte ?","ph":"jơ PƠ pê-YÊ par KART","vi":"Tôi trả bằng thẻ được không?","hl":["peux"],"tokens":["Je","peux","payer","par","carte"]}]},{"steps":[{"t":"aider","ph":"ê-ĐÊ","vi":"giúp","hl":[]},{"t":"pouvez m'aider","ph":"pu-VÊ mê-ĐÊ","vi":"có thể giúp tôi","hl":["pouvez"]},{"t":"Vous pouvez m'aider s'il vous plaît ?","ph":"vu pu-VÊ mê-ĐÊ xin vu PLÊ","vi":"Anh có thể giúp tôi được không?","hl":["pouvez"],"tokens":["Vous","pouvez","m'aider","s'il","vous","plaît"]}]},{"steps":[{"t":"entrer","ph":"a~-TRÊ","vi":"vào","hl":[]},{"t":"peut entrer","ph":"pơ-ta~-TRÊ","vi":"có thể vào","hl":["peut"]},{"t":"On peut entrer maintenant ?","ph":"o~ pơ-ta~-TRÊ me~t-NA~","vi":"Bây giờ chúng ta vào được chưa?","hl":["peut"],"tokens":["On","peut","entrer","maintenant"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"P","t":"pouvoir"},{"k":"V","t":"Động từ nguyên mẫu"},{"k":"O","t":"(Tân ngữ)"}],"points":["Pouvoir chia: je peux, tu peux, il/on peut, nous pouvons, vous pouvez, ils peuvent.","Sau pouvoir luôn là động từ nguyên mẫu, không thêm de hay à (\"Je peux payer\").","Je peux ... ? dùng để xin phép, Vous pouvez ... ? dùng để nhờ vả (\"Vous pouvez m'aider ?\").","Đại từ tân ngữ (me, le, la) đứng trước động từ nguyên mẫu, sau pouvoir (\"Vous pouvez m'aider\")."],"mistakes":[{"wrong":"Je peux de payer par carte ?","right":"Je peux payer par carte ?","why":"Sau pouvoir đặt thẳng động từ nguyên mẫu, không thêm de."},{"wrong":"Vous pouvez aider moi ?","right":"Vous pouvez m'aider ?","why":"Đại từ \"tôi\" (me → m') phải đứng TRƯỚC động từ, không đứng sau như tiếng Việt."}],"compare":"Giống tiếng Việt: có thể + động từ; khác ở chỗ đại từ tân ngữ phải chen lên trước động từ (\"m'aider\" = giúp tôi).","tip":"Xin phép thì \"Je peux...?\", nhờ ai thì \"Vous pouvez...?\" — chỉ cần lên giọng ở cuối câu.","how":["Chia pouvoir với je thành peux, đặt trước động từ nguyên mẫu payer → peux payer, rồi thêm Je ở đầu và par carte ở cuối, lên giọng hỏi → Je peux payer par carte ?","Chia pouvoir với vous thành pouvez, thêm m'aider (me rút thành m' trước aider) → pouvez m'aider, rồi thêm Vous ở đầu và s'il vous plaît ở cuối → Vous pouvez m'aider s'il vous plaît ?","Chia pouvoir với on thành peut, đặt trước entrer (đọc nối pơ-ta~) → peut entrer, rồi thêm On ở đầu và maintenant ở cuối → On peut entrer maintenant ?"],"dialog":[{"who":"A","t":"Excusez-moi, je peux m'asseoir ici ?","ph":"ếch-kuy-zê-MOA jơ PƠ ma-XOAR i-XI","vi":"Xin lỗi, tôi ngồi đây được không?","hl":["peux"]},{"who":"B","t":"Oui, bien sûr.","ph":"UY BIE~ XUYR","vi":"Vâng, tất nhiên rồi.","hl":[]},{"who":"A","t":"Vous pouvez fermer la fenêtre ?","ph":"vu pu-VÊ fer-MÊ la fơ-NE-TR","vi":"Anh đóng cửa sổ giúp được không?","hl":["pouvez"]},{"who":"B","t":"Oui, je peux la fermer.","ph":"UY jơ PƠ la fer-MÊ","vi":"Được, tôi đóng nó lại được.","hl":["peux"]}],"more":[{"t":"Je peux entrer ?","ph":"jơ pơ-ta~-TRÊ","vi":"Tôi vào được không?","hl":["peux"],"tokens":["Je","peux","entrer"]},{"t":"Tu peux répéter ?","ph":"tuy PƠ rê-pê-TÊ","vi":"Bạn nhắc lại được không?","hl":["peux"],"tokens":["Tu","peux","répéter"]},{"t":"On peut prendre des photos ici ?","ph":"o~ PƠ PRA~-ĐR đê fô-TÔ i-XI","vi":"Ở đây có được chụp ảnh không?","hl":["peut"],"tokens":["On","peut","prendre","des","photos","ici"]},{"t":"Nous pouvons partir à huit heures.","ph":"nu pu-VO~ par-TIR a uy-TƠR","vi":"Chúng tôi có thể đi lúc tám giờ.","hl":["pouvons"],"tokens":["Nous","pouvons","partir","à","huit","heures"]},{"t":"Vous pouvez appeler un taxi pour moi ?","ph":"vu pu-VÊ ap-LÊ a~ tắc-XI pur MOA","vi":"Anh gọi giúp tôi một chiếc taxi được không?","hl":["pouvez"],"tokens":["Vous","pouvez","appeler","un","taxi","pour","moi"]},{"t":"Je ne peux pas venir à la réunion.","ph":"jơ nơ PƠ pa vơ-NIR a la rê-uy-NIO~","vi":"Tôi không thể đến cuộc họp.","hl":["peux"],"tokens":["Je","ne","peux","pas","venir","à","la","réunion"]}]},{"id":8,"vi":"đi","note":"Aller (đi) + à/au + nơi chốn; phương tiện dùng en (en train, en métro). Chia: je vais, nous allons, vous allez.","pivot":{"t":"aller","ph":"a-LÊ"},"branches":[{"steps":[{"t":"gare","ph":"GAR","vi":"nhà ga","hl":[]},{"t":"vais à la gare","ph":"VÊ a la GAR","vi":"đi ra ga","hl":["vais"]},{"t":"Je vais à la gare en taxi.","ph":"jơ VÊ a la GAR a~ tắc-XI","vi":"Tôi đi ra ga bằng taxi.","hl":["vais"],"tokens":["Je","vais","à","la","gare","en","taxi"]}]},{"steps":[{"t":"musée","ph":"muy-ZÊ","vi":"bảo tàng","hl":[]},{"t":"allons au musée","ph":"a-LO~ ô muy-ZÊ","vi":"đi bảo tàng","hl":["allons"]},{"t":"Nous allons au musée demain.","ph":"nu-za-LO~ ô muy-ZÊ đơ-ME~","vi":"Ngày mai chúng tôi đi bảo tàng.","hl":["allons"],"tokens":["Nous","allons","au","musée","demain"]}]},{"steps":[{"t":"métro","ph":"mê-TRÔ","vi":"tàu điện ngầm","hl":[]},{"t":"allez en métro","ph":"a-LÊ a~ mê-TRÔ","vi":"đi bằng tàu điện ngầm","hl":["allez"]},{"t":"Vous allez en métro ou en bus ?","ph":"vu-za-LÊ a~ mê-TRÔ u a~ BUYT","vi":"Anh đi bằng tàu điện ngầm hay xe buýt?","hl":["allez"],"tokens":["Vous","allez","en","métro","ou","en","bus"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"P","t":"aller"},{"k":"O","t":"à/au + Nơi chốn"},{"k":"X","t":"(en + Phương tiện)"}],"points":["Aller chia bất quy tắc: je vais, tu vas, il va, nous allons, vous allez, ils vont.","Đi đến đâu dùng à + nơi chốn; à + le gộp thành au (\"au musée\"), à + les thành aux.","Đi bằng phương tiện kín dùng en (\"en train\", \"en métro\"), đi bộ thì nói à pied.","Nous allons, vous allez đọc nối âm z (nu-za-LO~, vu-za-LÊ)."],"mistakes":[{"wrong":"Je vais à le musée.","right":"Je vais au musée.","why":"à + le bắt buộc gộp thành au."},{"wrong":"Je vais par train.","right":"Je vais en train.","why":"Phương tiện đi lại dùng en, không dịch \"bằng\" thành par."}],"compare":"Trật tự giống tiếng Việt: Chủ ngữ + đi + đến đâu + bằng gì; khác ở chỗ phải có giới từ à/au trước nơi đến, còn tiếng Việt nói thẳng \"đi ga\".","tip":"Nhớ cặp \"vais-vas-va\" như tiếng còi tàu, còn \"au\" là à + le dính chặt vào nhau.","how":["Chia aller với je thành vais rồi thêm à la gare → vais à la gare, sau đó đặt Je ở đầu và en taxi ở cuối → Je vais à la gare en taxi.","Chia aller với nous thành allons, musée là giống đực nên à + le thành au → allons au musée, rồi thêm Nous ở đầu và demain ở cuối → Nous allons au musée demain.","Chia aller với vous thành allez rồi thêm phương tiện en métro → allez en métro, sau đó đặt Vous lên đầu và thêm ou en bus để hỏi lựa chọn → Vous allez en métro ou en bus ?"],"dialog":[{"who":"A","t":"Où allez-vous ce week-end ?","ph":"U a-lê-VU xơ uých-KEN","vi":"Cuối tuần này anh đi đâu?","hl":["allez"]},{"who":"B","t":"Je vais à Nice avec ma famille.","ph":"jơ VÊ a NIX a-VEK ma fa-MIY","vi":"Tôi đi Nice với gia đình.","hl":["vais"]},{"who":"A","t":"Vous allez en avion ?","ph":"vu-za-LÊ a~-na-VIO~","vi":"Anh đi bằng máy bay à?","hl":["allez"]},{"who":"B","t":"Non, nous allons en voiture.","ph":"NO~ nu-za-LO~ a~ voa-TUYR","vi":"Không, chúng tôi đi ô tô.","hl":["allons"]}],"more":[{"t":"Je vais au marché.","ph":"jơ VÊ ô mar-SHÊ","vi":"Tôi đi chợ.","hl":["vais"],"tokens":["Je","vais","au","marché"]},{"t":"Tu vas au bureau à pied ?","ph":"tuy VA ô buy-RÔ a PIÊ","vi":"Bạn đi bộ đến văn phòng à?","hl":["vas"],"tokens":["Tu","vas","au","bureau","à","pied"]},{"t":"Elle va à la banque ce matin.","ph":"el VA a la BA~K xơ ma-TE~","vi":"Sáng nay cô ấy đi ngân hàng.","hl":["va"],"tokens":["Elle","va","à","la","banque","ce","matin"]},{"t":"Nous allons à Lyon en train.","ph":"nu-za-LO~ a li-O~ a~ TRE~","vi":"Chúng tôi đi Lyon bằng tàu hỏa.","hl":["allons"],"tokens":["Nous","allons","à","Lyon","en","train"]},{"t":"Ils vont à la plage tous les jours.","ph":"il VO~ a la PLAJ tu lê JUR","vi":"Ngày nào họ cũng đi biển.","hl":["vont"],"tokens":["Ils","vont","à","la","plage","tous","les","jours"]},{"t":"Vous allez à l'aéroport avec la navette ?","ph":"vu-za-LÊ a la-ê-rô-PÔR a-VEK la na-VET","vi":"Anh đi sân bay bằng xe đưa đón à?","hl":["allez"],"tokens":["Vous","allez","à","l'aéroport","avec","la","navette"]}]},{"id":9,"vi":"ở đâu","note":"Hỏi địa điểm bằng où (ở đâu): où est + danh từ số ít, où sont + danh từ số nhiều.","pivot":{"t":"où","ph":"U"},"branches":[{"steps":[{"t":"gare","ph":"GAR","vi":"nhà ga","hl":[]},{"t":"où est la gare","ph":"U e la GAR","vi":"nhà ga ở đâu","hl":["où"]},{"t":"Savez-vous où est la gare ?","ph":"sa-vê-VU U e la GAR","vi":"Anh có biết nhà ga ở đâu không?","hl":["où"],"tokens":["Savez-vous","où","est","la","gare"]}]},{"steps":[{"t":"toilettes","ph":"toa-LET","vi":"nhà vệ sinh","hl":[]},{"t":"Où sont les toilettes","ph":"U xo~ lê toa-LET","vi":"nhà vệ sinh ở đâu","hl":["Où"]},{"t":"Où sont les toilettes s'il vous plaît ?","ph":"U xo~ lê toa-LET xin vu PLÊ","vi":"Làm ơn cho hỏi nhà vệ sinh ở đâu?","hl":["Où"],"tokens":["Où","sont","les","toilettes","s'il","vous","plaît"]}]},{"steps":[{"t":"habitez","ph":"a-bi-TÊ","vi":"sống","hl":[]},{"t":"Où habitez-vous","ph":"U a-bi-tê-VU","vi":"anh sống ở đâu","hl":["Où"]},{"t":"Où habitez-vous en France ?","ph":"U a-bi-tê-VU a~ FRA~X","vi":"Anh sống ở đâu bên Pháp?","hl":["Où"],"tokens":["Où","habitez-vous","en","France"]}]}],"formula":[{"k":"P","t":"Où"},{"k":"V","t":"est / sont"},{"k":"O","t":"le/la/les + Danh từ"}],"points":["Où (ở đâu) đứng đầu câu: où est + danh từ số ít, où sont + danh từ số nhiều.","Hỏi ai đó ở/sống ở đâu thì đảo động từ lên trước chủ ngữ, nối bằng gạch ngang (\"Où habitez-vous ?\").","Trong câu hỏi gián tiếp, où đứng giữa câu và không đảo ngữ (\"Savez-vous où est la gare ?\").","Lưu ý où có dấu huyền để phân biệt với ou (hoặc)."],"mistakes":[{"wrong":"La gare est où ?","right":"Où est la gare ?","why":"Câu đặt où ở cuối chỉ dùng trong văn nói suồng sã; nên đặt Où lên đầu câu."},{"wrong":"Où est les toilettes ?","right":"Où sont les toilettes ?","why":"Danh từ số nhiều (les toilettes) phải dùng sont chứ không dùng est."}],"compare":"Tiếng Việt đặt \"ở đâu\" ở CUỐI câu (Nhà ga ở đâu?); tiếng Pháp đưa Où lên ĐẦU câu rồi mới đến động từ và danh từ.","tip":"Hỏi đường là kêu \"U!\" trước tiên: Où est...? — giống gọi người ta lại để hỏi.","how":["Ghép où + est + la gare → où est la gare, rồi đặt Savez-vous (Anh có biết) phía trước để thành câu hỏi lịch sự → Savez-vous où est la gare ?","les toilettes là số nhiều nên dùng sont → Où sont les toilettes, rồi thêm s'il vous plaît ở cuối cho lịch sự → Où sont les toilettes s'il vous plaît ?","Đặt Où trước động từ habitez rồi đảo vous ra sau có gạch nối → Où habitez-vous, rồi thêm en France ở cuối → Où habitez-vous en France ?"],"dialog":[{"who":"A","t":"Pardon, où est l'arrêt de bus ?","ph":"par-ĐO~ U e la-RE đơ BUYT","vi":"Xin lỗi, bến xe buýt ở đâu?","hl":["où"]},{"who":"B","t":"Il est en face de la poste.","ph":"i-LE-ta~ FAX đơ la POST","vi":"Nó ở đối diện bưu điện.","hl":[]},{"who":"A","t":"Et où sont les taxis ?","ph":"ê U xo~ lê tắc-XI","vi":"Còn taxi đỗ ở đâu?","hl":["où"]},{"who":"B","t":"Ils sont devant la gare.","ph":"il XO~ đơ-VA~ la GAR","vi":"Ở trước nhà ga.","hl":[]}],"more":[{"t":"Où est mon sac ?","ph":"U e mo~ XAK","vi":"Túi của tôi đâu rồi?","hl":["Où"],"tokens":["Où","est","mon","sac"]},{"t":"Où sont mes clés ?","ph":"U xo~ mê KLÊ","vi":"Chìa khóa của tôi đâu?","hl":["Où"],"tokens":["Où","sont","mes","clés"]},{"t":"Où est la sortie s'il vous plaît ?","ph":"U e la xor-TI xin vu PLÊ","vi":"Làm ơn cho hỏi lối ra ở đâu?","hl":["Où"],"tokens":["Où","est","la","sortie","s'il","vous","plaît"]},{"t":"Où travaillez-vous maintenant ?","ph":"U tra-va-yê-VU me~t-NA~","vi":"Bây giờ anh làm việc ở đâu?","hl":["Où"],"tokens":["Où","travaillez-vous","maintenant"]},{"t":"Où est-ce qu'on peut acheter des billets ?","ph":"U es-ko~ PƠ ash-TÊ đê bi-YÊ","vi":"Có thể mua vé ở đâu?","hl":["Où"],"tokens":["Où","est-ce","qu'on","peut","acheter","des","billets"]},{"t":"Je ne sais pas où est mon hôtel.","ph":"jơ nơ XÊ pa U e mo~-nô-TEL","vi":"Tôi không biết khách sạn của tôi ở đâu.","hl":["où"],"tokens":["Je","ne","sais","pas","où","est","mon","hôtel"]}]},{"id":10,"vi":"bao nhiêu","note":"Combien (bao nhiêu) hỏi giá; combien de + danh từ hỏi số lượng.","pivot":{"t":"combien","ph":"ko~-BIE~"},"branches":[{"steps":[{"t":"coûte","ph":"KUT","vi":"có giá","hl":[]},{"t":"coûte combien","ph":"KUT ko~-BIE~","vi":"giá bao nhiêu","hl":["combien"]},{"t":"Ce billet coûte combien ?","ph":"xơ bi-YÊ KUT ko~-BIE~","vi":"Vé này bao nhiêu tiền?","hl":["combien"],"tokens":["Ce","billet","coûte","combien"]}]},{"steps":[{"t":"personnes","ph":"per-XÔN","vi":"người","hl":[]},{"t":"combien de personnes","ph":"ko~-BIE~ đơ per-XÔN","vi":"bao nhiêu người","hl":["combien"]},{"t":"Vous êtes combien de personnes ?","ph":"vu-ZET ko~-BIE~ đơ per-XÔN","vi":"Quý khách đi mấy người?","hl":["combien"],"tokens":["Vous","êtes","combien","de","personnes"]}]},{"steps":[{"t":"temps","ph":"TA~","vi":"thời gian","hl":[]},{"t":"Combien de temps","ph":"ko~-BIE~ đơ TA~","vi":"bao lâu","hl":["Combien"]},{"t":"Combien de temps dure le trajet ?","ph":"ko~-BIE~ đơ TA~ ĐUYR lơ tra-JÊ","vi":"Chuyến đi mất bao lâu?","hl":["Combien"],"tokens":["Combien","de","temps","dure","le","trajet"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"V","t":"coûte / êtes"},{"k":"P","t":"combien (de)"},{"k":"O","t":"(Danh từ)"}],"points":["Hỏi giá: \"C'est combien ?\" hoặc \"Ça coûte combien ?\" (cái này bao nhiêu tiền).","Hỏi số lượng: combien de + danh từ, de rút thành d' trước nguyên âm (\"combien d'enfants\").","Combien có thể đứng đầu câu (\"Combien de temps...\") hoặc cuối câu trong văn nói (\"Ça coûte combien ?\").","Sau combien de, danh từ đếm được để ở số nhiều và không có mạo từ (\"combien de personnes\")."],"mistakes":[{"wrong":"Combien des personnes ?","right":"Combien de personnes ?","why":"Sau combien chỉ dùng de, không dùng des."},{"wrong":"Combien coûte ?","right":"Ça coûte combien ?","why":"Câu cần có chủ ngữ (Ça / Ce billet), không bỏ trống như tiếng Việt."}],"compare":"Giống tiếng Việt khi đặt cuối câu (Vé này bao nhiêu?); khác ở chỗ hỏi số lượng phải thêm de trước danh từ: combien de personnes.","tip":"Đi chợ chỉ cần chỉ tay và hỏi \"C'est combien ?\" — đọc là \"xê ko~-BIE~\".","how":["Đặt combien sau động từ coûte → coûte combien, rồi thêm chủ ngữ Ce billet ở đầu và lên giọng hỏi → Ce billet coûte combien ?","Ghép combien + de + personnes (số nhiều, không mạo từ) → combien de personnes, rồi đặt Vous êtes ở đầu → Vous êtes combien de personnes ?","Ghép Combien + de + temps → Combien de temps đặt ở đầu câu, rồi thêm dure le trajet → Combien de temps dure le trajet ?"],"dialog":[{"who":"A","t":"Bonjour, c'est combien ces mangues ?","ph":"bo~-JUR xê ko~-BIE~ xê MA~G","vi":"Chào chị, mấy quả xoài này bao nhiêu tiền?","hl":["combien"]},{"who":"B","t":"Trois euros le kilo.","ph":"troa-zơ-RÔ lơ ki-LÔ","vi":"Ba euro một cân.","hl":[]},{"who":"A","t":"Et combien de kilos il vous reste ?","ph":"ê ko~-BIE~ đơ ki-LÔ il vu REST","vi":"Thế chị còn bao nhiêu cân?","hl":["combien"]},{"who":"B","t":"Il me reste deux kilos.","ph":"il mơ REST đơ ki-LÔ","vi":"Tôi còn hai cân.","hl":[]}],"more":[{"t":"C'est combien la chambre ?","ph":"xê ko~-BIE~ la SHA~-BR","vi":"Phòng giá bao nhiêu?","hl":["combien"],"tokens":["C'est","combien","la","chambre"]},{"t":"Ça coûte combien ?","ph":"xa KUT ko~-BIE~","vi":"Cái đó giá bao nhiêu?","hl":["combien"],"tokens":["Ça","coûte","combien"]},{"t":"Combien de nuits restez-vous ?","ph":"ko~-BIE~ đơ NUY res-tê-VU","vi":"Anh ở lại bao nhiêu đêm?","hl":["Combien"],"tokens":["Combien","de","nuits","restez-vous"]},{"t":"Vous avez combien d'enfants ?","ph":"vu-za-VÊ ko~-BIE~ đa~-FA~","vi":"Anh có mấy con?","hl":["combien"],"tokens":["Vous","avez","combien","d'enfants"]},{"t":"Combien de stations jusqu'au centre ?","ph":"ko~-BIE~ đơ xta-XIO~ juys-kô XA~-TR","vi":"Còn bao nhiêu ga nữa thì đến trung tâm?","hl":["Combien"],"tokens":["Combien","de","stations","jusqu'au","centre"]},{"t":"Combien de temps faut-il pour aller à l'aéroport ?","ph":"ko~-BIE~ đơ TA~ fô-TIL pur a-LÊ a la-ê-rô-PÔR","vi":"Đi đến sân bay mất bao lâu?","hl":["Combien"],"tokens":["Combien","de","temps","faut-il","pour","aller","à","l'aéroport"]}]},{"id":11,"vi":"cái gì","note":"Qu'est-ce que đứng đầu câu hỏi cái gì / làm gì; trong văn nói có thể đặt quoi ở cuối câu.","pivot":{"t":"qu'est-ce que","ph":"kes-KƠ"},"branches":[{"steps":[{"t":"fais","ph":"FE","vi":"làm","hl":[]},{"t":"Qu'est-ce que tu fais","ph":"kes-KƠ tuy FE","vi":"bạn làm gì","hl":["Qu'est-ce que"]},{"t":"Qu'est-ce que tu fais ce soir ?","ph":"kes-KƠ tuy FE xơ SOAR","vi":"Tối nay bạn làm gì?","hl":["Qu'est-ce que"],"tokens":["Qu'est-ce","que","tu","fais","ce","soir"]}]},{"steps":[{"t":"recommandez","ph":"rơ-ko-ma~-ĐÊ","vi":"gợi ý","hl":[]},{"t":"Qu'est-ce que vous recommandez","ph":"kes-KƠ vu rơ-ko-ma~-ĐÊ","vi":"anh gợi ý món gì","hl":["Qu'est-ce que"]},{"t":"Qu'est-ce que vous recommandez ici ?","ph":"kes-KƠ vu rơ-ko-ma~-ĐÊ i-XI","vi":"Ở đây anh gợi ý món gì?","hl":["Qu'est-ce que"],"tokens":["Qu'est-ce","que","vous","recommandez","ici"]}]},{"steps":[{"t":"veut","ph":"VƠ","vi":"muốn (nói)","hl":[]},{"t":"veut dire quoi","ph":"VƠ ĐIA KOA","vi":"nghĩa là gì","hl":["quoi"]},{"t":"Ce mot veut dire quoi ?","ph":"xơ MÔ VƠ ĐIA KOA","vi":"Từ này nghĩa là gì?","hl":["quoi"],"tokens":["Ce","mot","veut","dire","quoi"]}]}],"formula":[{"k":"P","t":"Qu'est-ce que"},{"k":"S","t":"Chủ ngữ"},{"k":"V","t":"Động từ"},{"k":"O","t":"(Thời gian / Nơi chốn)"}],"points":["Qu'est-ce que (cái gì / làm gì) đứng đầu câu, sau đó giữ nguyên trật tự Chủ ngữ + Động từ (\"Qu'est-ce que tu fais ?\").","Trước nguyên âm, que rút thành qu' (\"Qu'est-ce qu'il dit ?\").","Trong văn nói thân mật, có thể bỏ qu'est-ce que và đặt quoi ở cuối câu (\"Tu fais quoi ?\").","Hỏi nghĩa của từ dùng \"veut dire quoi\" hoặc \"Qu'est-ce que ça veut dire ?\"."],"mistakes":[{"wrong":"Tu fais qu'est-ce que ?","right":"Qu'est-ce que tu fais ?","why":"Qu'est-ce que luôn đứng đầu câu; ở cuối câu thì dùng quoi."},{"wrong":"Qu'est-ce que fais-tu ?","right":"Qu'est-ce que tu fais ?","why":"Sau qu'est-ce que không đảo chủ ngữ ra sau động từ."}],"compare":"Tiếng Việt để \"gì\" ở cuối (Bạn làm gì?), giống kiểu văn nói \"Tu fais quoi ?\"; còn kiểu chuẩn Qu'est-ce que lại đưa từ hỏi lên đầu câu.","tip":"Qu'est-ce que đọc nhanh thành \"kes-kơ\" — chỉ hai tiếng như hỏi \"cái gì kìa?\".","how":["Đặt Qu'est-ce que lên đầu, theo sau là tu + fais → Qu'est-ce que tu fais, rồi thêm ce soir ở cuối → Qu'est-ce que tu fais ce soir ?","Đặt Qu'est-ce que lên đầu, theo sau là vous + recommandez → Qu'est-ce que vous recommandez, rồi thêm ici ở cuối → Qu'est-ce que vous recommandez ici ?","Kiểu văn nói: sau veut thêm dire quoi (muốn nói gì) → veut dire quoi, rồi đặt Ce mot lên đầu → Ce mot veut dire quoi ?"],"dialog":[{"who":"A","t":"Qu'est-ce que tu manges ?","ph":"kes-KƠ tuy MA~J","vi":"Bạn đang ăn gì vậy?","hl":["Qu'est-ce que"]},{"who":"B","t":"Une galette bretonne.","ph":"uyn ga-LET brơ-TÔN","vi":"Một cái bánh galette vùng Bretagne.","hl":[]},{"who":"A","t":"Ça veut dire quoi, galette ?","ph":"xa VƠ ĐIA KOA ga-LET","vi":"Galette nghĩa là gì?","hl":["quoi"]},{"who":"B","t":"C'est une crêpe salée.","ph":"xê-tuyn KREP xa-LÊ","vi":"Là một loại bánh crêpe mặn.","hl":[]}],"more":[{"t":"Qu'est-ce que c'est ?","ph":"kes-KƠ XÊ","vi":"Cái này là gì?","hl":["Qu'est-ce que"],"tokens":["Qu'est-ce","que","c'est"]},{"t":"Tu cherches quoi ?","ph":"tuy SHERSH KOA","vi":"Bạn đang tìm gì?","hl":["quoi"],"tokens":["Tu","cherches","quoi"]},{"t":"Qu'est-ce que vous prenez ?","ph":"kes-KƠ vu prơ-NÊ","vi":"Anh dùng món gì?","hl":["Qu'est-ce que"],"tokens":["Qu'est-ce","que","vous","prenez"]},{"t":"Qu'est-ce qu'il y a dans ce plat ?","ph":"kes-ki-li-A đa~ xơ PLA","vi":"Món này có những gì?","hl":["Qu'est-ce qu'"],"tokens":["Qu'est-ce","qu'il","y","a","dans","ce","plat"]},{"t":"Qu'est-ce que vous faites dans la vie ?","ph":"kes-KƠ vu FET đa~ la VI","vi":"Anh làm nghề gì?","hl":["Qu'est-ce que"],"tokens":["Qu'est-ce","que","vous","faites","dans","la","vie"]},{"t":"Qu'est-ce que nous visitons demain matin ?","ph":"kes-KƠ nu vi-zi-TO~ đơ-ME~ ma-TE~","vi":"Sáng mai chúng ta tham quan gì?","hl":["Qu'est-ce que"],"tokens":["Qu'est-ce","que","nous","visitons","demain","matin"]}]},{"id":12,"vi":"ai","note":"Qui (ai) đứng đầu câu hỏi người: qui + động từ (ai làm gì), qui est (là ai), avec qui (với ai).","pivot":{"t":"qui","ph":"KI"},"branches":[{"steps":[{"t":"est","ph":"E","vi":"là","hl":[]},{"t":"Qui est","ph":"KI E","vi":"ai là","hl":["Qui"]},{"t":"Qui est le responsable ici ?","ph":"KI E lơ rết-po~-XA-BL i-XI","vi":"Ai là người phụ trách ở đây?","hl":["Qui"],"tokens":["Qui","est","le","responsable","ici"]}]},{"steps":[{"t":"parle","ph":"PARL","vi":"nói","hl":[]},{"t":"Qui parle","ph":"KI PARL","vi":"ai nói","hl":["Qui"]},{"t":"Qui parle anglais ici ?","ph":"KI PARL a~-GLE i-XI","vi":"Ở đây ai nói tiếng Anh?","hl":["Qui"],"tokens":["Qui","parle","anglais","ici"]}]},{"steps":[{"t":"voyagez","ph":"voa-ya-JÊ","vi":"đi du lịch","hl":[]},{"t":"Avec qui voyagez-vous","ph":"a-VEK KI voa-ya-jê-VU","vi":"bạn đi du lịch với ai","hl":["qui"]},{"t":"Avec qui voyagez-vous cet été ?","ph":"a-VEK KI voa-ya-jê-VU xê-tê-TÊ","vi":"Mùa hè này bạn đi du lịch với ai?","hl":["qui"],"tokens":["Avec","qui","voyagez-vous","cet","été"]}]}],"formula":[{"k":"X","t":"(Giới từ)"},{"k":"P","t":"Qui"},{"k":"V","t":"Động từ"},{"k":"O","t":"(Bổ ngữ)"}],"points":["Qui (ai) làm chủ ngữ thì đứng đầu, động từ chia ngôi thứ ba số ít (\"Qui parle anglais ?\").","Qui est + danh từ dùng để hỏi \"là ai\" (\"Qui est le responsable ?\").","Có giới từ thì giới từ đứng trước qui: avec qui (với ai), pour qui (cho ai), à qui (của ai).","Qui không bao giờ rút thành qu' (\"Qui est là ?\", không viết \"Qu'est là\")."],"mistakes":[{"wrong":"Qui parlent anglais ?","right":"Qui parle anglais ?","why":"Sau qui động từ chia ở ngôi thứ ba số ít, dù câu trả lời có thể là nhiều người."},{"wrong":"Qui avec voyagez-vous ?","right":"Avec qui voyagez-vous ?","why":"Giới từ avec phải đứng trước qui, không tách ra như \"đi với ai\" tiếng Việt."}],"compare":"Tiếng Việt có thể để \"ai\" ở đầu (Ai nói tiếng Anh?) giống tiếng Pháp; nhưng \"với ai\" thì tiếng Việt để cuối, còn tiếng Pháp đưa cả cụm Avec qui lên đầu câu.","tip":"Qui đọc là \"KI\" — nghe như \"ki\" trong \"ai kia?\", rất dễ nhớ.","how":["Đặt Qui trước động từ est → Qui est, rồi thêm le responsable ici để hỏi người phụ trách → Qui est le responsable ici ?","Qui làm chủ ngữ nên đứng ngay trước động từ parle → Qui parle, rồi thêm anglais ici ở cuối → Qui parle anglais ici ?","Ghép giới từ Avec + qui đặt đầu câu, rồi đảo voyagez-vous → Avec qui voyagez-vous, sau đó thêm cet été → Avec qui voyagez-vous cet été ?"],"dialog":[{"who":"A","t":"Qui est cette femme ?","ph":"KI e xet FAM","vi":"Người phụ nữ kia là ai?","hl":["Qui"]},{"who":"B","t":"C'est notre guide.","ph":"xê no-trơ GHID","vi":"Đó là hướng dẫn viên của chúng ta.","hl":[]},{"who":"A","t":"Et qui a les billets ?","ph":"ê KI a lê bi-YÊ","vi":"Thế ai cầm vé?","hl":["qui"]},{"who":"B","t":"Elle a tous les billets.","ph":"e-LA tu lê bi-YÊ","vi":"Cô ấy giữ tất cả vé.","hl":[]}],"more":[{"t":"Qui est là ?","ph":"KI e LA","vi":"Ai đó?","hl":["Qui"],"tokens":["Qui","est","là"]},{"t":"Qui veut du café ?","ph":"KI VƠ đuy ka-FÊ","vi":"Ai muốn uống cà phê?","hl":["Qui"],"tokens":["Qui","veut","du","café"]},{"t":"C'est pour qui ?","ph":"xê pur KI","vi":"Cái này cho ai?","hl":["qui"],"tokens":["C'est","pour","qui"]},{"t":"Qui connaît un bon restaurant ici ?","ph":"KI ko-NE a~ BO~ res-tô-RA~ i-XI","vi":"Ai biết nhà hàng nào ngon ở đây không?","hl":["Qui"],"tokens":["Qui","connaît","un","bon","restaurant","ici"]},{"t":"À qui est cette valise ?","ph":"a KI e xet va-LIZ","vi":"Va li này của ai?","hl":["qui"],"tokens":["À","qui","est","cette","valise"]},{"t":"Avec qui travaillez-vous sur ce projet ?","ph":"a-VEK KI tra-va-yê-VU xuyr xơ pro-JÊ","vi":"Anh làm dự án này với ai?","hl":["qui"],"tokens":["Avec","qui","travaillez-vous","sur","ce","projet"]}]},{"id":13,"vi":"khi nào","note":"Quand (khi nào) đứng đầu câu hỏi thời gian; hỏi giờ cụ thể dùng à quelle heure (mấy giờ).","pivot":{"t":"quand","ph":"KA~"},"branches":[{"steps":[{"t":"part","ph":"PAR","vi":"khởi hành","hl":[]},{"t":"Quand part le train","ph":"KA~ PAR lơ TRE~","vi":"khi nào tàu chạy","hl":["Quand"]},{"t":"Quand part le train pour Paris ?","ph":"KA~ PAR lơ TRE~ pur pa-RI","vi":"Khi nào tàu đi Paris khởi hành?","hl":["Quand"],"tokens":["Quand","part","le","train","pour","Paris"]}]},{"steps":[{"t":"arrivez","ph":"a-ri-VÊ","vi":"đến","hl":[]},{"t":"Quand arrivez-vous","ph":"ka~-ta-ri-vê-VU","vi":"khi nào anh đến","hl":["Quand"]},{"t":"Quand arrivez-vous à Hanoï ?","ph":"ka~-ta-ri-vê-VU a a-nô-I","vi":"Khi nào anh đến Hà Nội?","hl":["Quand"],"tokens":["Quand","arrivez-vous","à","Hanoï"]}]},{"steps":[{"t":"ouvre","ph":"UVR","vi":"mở cửa","hl":[]},{"t":"À quelle heure ouvre","ph":"a KEL ƠR UVR","vi":"mấy giờ mở cửa","hl":["À quelle heure"]},{"t":"À quelle heure ouvre le musée ?","ph":"a KEL ƠR UVR lơ muy-ZÊ","vi":"Mấy giờ bảo tàng mở cửa?","hl":["À quelle heure"],"tokens":["À","quelle","heure","ouvre","le","musée"]}]}],"formula":[{"k":"P","t":"Quand / À quelle heure"},{"k":"V","t":"Động từ"},{"k":"S","t":"Chủ ngữ"},{"k":"O","t":"(Nơi chốn)"}],"points":["Quand (khi nào) đứng đầu câu hỏi, sau đó đảo động từ lên trước chủ ngữ (\"Quand part le train ?\").","Với đại từ, đảo bằng gạch nối: \"Quand arrivez-vous ?\" (đọc nối ka~-ta-ri-vê-VU).","Hỏi giờ cụ thể dùng À quelle heure (mấy giờ) thay cho quand.","Quand cũng dùng trong câu trả lời với nghĩa \"khi\" (\"Je t'appelle quand j'arrive\")."],"mistakes":[{"wrong":"Quand vous arrivez à Hanoï ?","right":"Quand arrivez-vous à Hanoï ?","why":"Câu hỏi chuẩn cần đảo động từ lên trước chủ ngữ (hoặc dùng Quand est-ce que vous arrivez)."},{"wrong":"Quand heure ouvre le musée ?","right":"À quelle heure ouvre le musée ?","why":"Hỏi giờ phải dùng cụm À quelle heure, không ghép quand với heure."}],"compare":"Tiếng Việt để \"khi nào\" ở đầu hoặc cuối câu tùy nghĩa; tiếng Pháp luôn đưa Quand lên đầu và còn đảo động từ lên trước chủ ngữ.","tip":"Quand đọc là \"KA~\" — nghe như \"căng\": căng thẳng vì không biết khi nào tàu chạy!","how":["Đặt Quand lên đầu, đảo động từ part lên trước chủ ngữ le train → Quand part le train, rồi thêm pour Paris → Quand part le train pour Paris ?","Đặt Quand lên đầu và đảo arrivez-vous có gạch nối (đọc nối ka~-ta) → Quand arrivez-vous, rồi thêm à Hanoï → Quand arrivez-vous à Hanoï ?","Hỏi giờ nên dùng À quelle heure đặt trước động từ ouvre → À quelle heure ouvre, rồi thêm chủ ngữ le musée → À quelle heure ouvre le musée ?"],"dialog":[{"who":"A","t":"Quand partez-vous en vacances ?","ph":"KA~ par-tê-VU a~ va-KA~X","vi":"Khi nào anh đi nghỉ?","hl":["Quand"]},{"who":"B","t":"La semaine prochaine.","ph":"la xơ-MEN pro-SHEN","vi":"Tuần sau.","hl":[]},{"who":"A","t":"À quelle heure est votre vol ?","ph":"a KEL ƠR e vo-trơ VOL","vi":"Chuyến bay của anh lúc mấy giờ?","hl":["À quelle heure"]},{"who":"B","t":"À dix heures du matin.","ph":"a đi-ZƠR đuy ma-TE~","vi":"Lúc mười giờ sáng.","hl":[]}],"more":[{"t":"Quand commence le film ?","ph":"KA~ ko-MA~X lơ FILM","vi":"Khi nào phim bắt đầu?","hl":["Quand"],"tokens":["Quand","commence","le","film"]},{"t":"Quand rentrez-vous en France ?","ph":"KA~ ra~-trê-VU a~ FRA~X","vi":"Khi nào anh về Pháp?","hl":["Quand"],"tokens":["Quand","rentrez-vous","en","France"]},{"t":"À quelle heure ferme la banque ?","ph":"a KEL ƠR FERM la BA~K","vi":"Ngân hàng đóng cửa lúc mấy giờ?","hl":["À quelle heure"],"tokens":["À","quelle","heure","ferme","la","banque"]},{"t":"Quand est le prochain bus ?","ph":"ka~-TE lơ pro-she~ BUYT","vi":"Khi nào có chuyến xe buýt tiếp theo?","hl":["Quand"],"tokens":["Quand","est","le","prochain","bus"]},{"t":"À quelle heure est le petit-déjeuner ?","ph":"a KEL ƠR e lơ pơ-ti-đê-jơ-NÊ","vi":"Bữa sáng lúc mấy giờ?","hl":["À quelle heure"],"tokens":["À","quelle","heure","est","le","petit-déjeuner"]},{"t":"Quand est-ce que la réunion commence demain ?","ph":"ka~-tes-KƠ la rê-uy-NIO~ ko-MA~X đơ-ME~","vi":"Ngày mai cuộc họp bắt đầu khi nào?","hl":["Quand"],"tokens":["Quand","est-ce","que","la","réunion","commence","demain"]}]},{"id":14,"vi":"tại sao / vì","note":"Hỏi lý do bằng pourquoi (tại sao), trả lời bằng parce que (vì); que thành qu' trước nguyên âm.","pivot":{"t":"pourquoi ... parce que","ph":"pur-KOA ... par-sơ KƠ"},"branches":[{"steps":[{"t":"fermé","ph":"fer-MÊ","vi":"đóng cửa","hl":[]},{"t":"Pourquoi c'est fermé","ph":"pur-KOA xê fer-MÊ","vi":"tại sao đóng cửa","hl":["Pourquoi"]},{"t":"Pourquoi c'est fermé aujourd'hui ?","ph":"pur-KOA xê fer-MÊ ô-jur-ĐUY","vi":"Tại sao hôm nay đóng cửa?","hl":["Pourquoi"],"tokens":["Pourquoi","c'est","fermé","aujourd'hui"]}]},{"steps":[{"t":"fatigué","ph":"fa-ti-GHÊ","vi":"mệt","hl":[]},{"t":"parce que je suis fatigué","ph":"par-sơ KƠ jơ XUY fa-ti-GHÊ","vi":"vì tôi mệt","hl":["parce que"]},{"t":"Je reste ici parce que je suis fatigué.","ph":"jơ REST i-XI par-sơ KƠ jơ XUY fa-ti-GHÊ","vi":"Tôi ở lại đây vì tôi mệt.","hl":["parce que"],"tokens":["Je","reste","ici","parce","que","je","suis","fatigué"]}]},{"steps":[{"t":"pleut","ph":"PLƠ","vi":"mưa","hl":[]},{"t":"parce qu'il pleut","ph":"par-sơ KIL PLƠ","vi":"vì trời mưa","hl":["parce qu'"]},{"t":"Je prends un taxi parce qu'il pleut.","ph":"jơ PRA~ a~ tắc-XI par-sơ KIL PLƠ","vi":"Tôi đi taxi vì trời mưa.","hl":["parce qu'"],"tokens":["Je","prends","un","taxi","parce","qu'il","pleut"]}]}],"formula":[{"k":"P","t":"Pourquoi"},{"k":"X","t":"Câu hỏi"},{"k":"P","t":"parce que (qu')"},{"k":"X","t":"Lý do"}],"points":["Pourquoi (tại sao) đứng đầu câu hỏi (\"Pourquoi c'est fermé ?\").","Trả lời bằng parce que (vì) + một mệnh đề đầy đủ có chủ ngữ và động từ (\"parce que je suis fatigué\").","Que rút thành qu' trước nguyên âm: parce qu'il, parce qu'elle, parce qu'on.","Parce que thường đứng giữa câu, sau phần kết quả (\"Je reste ici parce que je suis fatigué\")."],"mistakes":[{"wrong":"Pourquoi? Parce que fatigué.","right":"Parce que je suis fatigué.","why":"Sau parce que phải có đủ chủ ngữ và động từ, không chỉ một tính từ như tiếng Việt \"vì mệt\"."},{"wrong":"Je reste ici parce que il pleut.","right":"Je reste ici parce qu'il pleut.","why":"Que gặp nguyên âm i phải rút thành qu'."}],"compare":"Giống tiếng Việt: \"tại sao\" ở đầu câu hỏi, \"vì\" đứng trước lý do; khác ở chỗ sau parce que phải có câu đầy đủ chủ ngữ + động từ.","tip":"Hỏi \"pur-KOA\", đáp \"par-sơ-KƠ\" — một cặp như hỏi và trả lời, luôn đi cùng nhau.","how":["Đặt Pourquoi trước c'est fermé (đang đóng cửa) → Pourquoi c'est fermé, rồi thêm aujourd'hui ở cuối → Pourquoi c'est fermé aujourd'hui ?","Ghép parce que với câu đầy đủ je suis fatigué → parce que je suis fatigué, rồi đặt phần kết quả Je reste ici phía trước → Je reste ici parce que je suis fatigué.","il bắt đầu bằng nguyên âm nên que rút thành qu' → parce qu'il pleut, rồi đặt Je prends un taxi phía trước → Je prends un taxi parce qu'il pleut."],"dialog":[{"who":"A","t":"Pourquoi tu es en retard ?","ph":"pur-KOA tuy E-za~ rơ-TAR","vi":"Tại sao bạn đến muộn?","hl":["Pourquoi"]},{"who":"B","t":"Parce que le métro est en panne.","ph":"par-sơ KƠ lơ mê-TRÔ e-ta~ PAN","vi":"Vì tàu điện ngầm bị hỏng.","hl":["Parce que"]},{"who":"A","t":"Pourquoi tu n'as pas pris un taxi ?","ph":"pur-KOA tuy NA pa pri a~ tắc-XI","vi":"Sao bạn không đi taxi?","hl":["Pourquoi"]},{"who":"B","t":"Parce que c'est trop cher.","ph":"par-sơ KƠ xê TRÔ SHER","vi":"Vì đắt quá.","hl":["Parce que"]}],"more":[{"t":"Pourquoi tu ris ?","ph":"pur-KOA tuy RI","vi":"Sao bạn cười?","hl":["Pourquoi"],"tokens":["Pourquoi","tu","ris"]},{"t":"Pourquoi le train est en retard ?","ph":"pur-KOA lơ TRE~ e-ta~ rơ-TAR","vi":"Tại sao tàu đến muộn?","hl":["Pourquoi"],"tokens":["Pourquoi","le","train","est","en","retard"]},{"t":"Je mange ici parce que c'est bon.","ph":"jơ MA~J i-XI par-sơ KƠ xê BO~","vi":"Tôi ăn ở đây vì nó ngon.","hl":["parce que"],"tokens":["Je","mange","ici","parce","que","c'est","bon"]},{"t":"Elle ne vient pas parce qu'elle est malade.","ph":"el nơ VIE~ pa par-sơ KEL e ma-LAĐ","vi":"Cô ấy không đến vì bị ốm.","hl":["parce qu'"],"tokens":["Elle","ne","vient","pas","parce","qu'elle","est","malade"]},{"t":"Pourquoi voulez-vous changer de chambre ?","ph":"pur-KOA vu-lê-VU sha~-JÊ đơ SHA~-BR","vi":"Tại sao anh muốn đổi phòng?","hl":["Pourquoi"],"tokens":["Pourquoi","voulez-vous","changer","de","chambre"]},{"t":"On reste dedans parce qu'il fait froid.","ph":"o~ REST đơ-ĐA~ par-sơ KIL fe FROA","vi":"Chúng tôi ở trong nhà vì trời lạnh.","hl":["parce qu'"],"tokens":["On","reste","dedans","parce","qu'il","fait","froid"]}]},{"id":15,"vi":"làm ơn","note":"Nhờ vả lịch sự bằng cách thêm s'il vous plaît (làm ơn) cuối câu, hoặc hỏi pourriez-vous + động từ nguyên mẫu.","pivot":{"t":"s'il vous plaît","ph":"xin vu PLÊ"},"branches":[{"steps":[{"t":"lentement","ph":"la~t-MA~","vi":"chậm","hl":[]},{"t":"lentement s'il vous plaît","ph":"la~t-MA~ xin vu PLÊ","vi":"làm ơn chậm thôi","hl":["s'il vous plaît"]},{"t":"Parlez plus lentement s'il vous plaît.","ph":"par-LÊ pluy la~t-MA~ xin vu PLÊ","vi":"Làm ơn nói chậm hơn.","hl":["s'il vous plaît"],"tokens":["Parlez","plus","lentement","s'il","vous","plaît"]}]},{"steps":[{"t":"aider","ph":"ê-ĐÊ","vi":"giúp","hl":[]},{"t":"Pourriez-vous m'aider","ph":"pu-ri-ê-VU mê-ĐÊ","vi":"làm ơn giúp tôi","hl":["Pourriez-vous"]},{"t":"Pourriez-vous m'aider avec ma valise ?","ph":"pu-ri-ê-VU mê-ĐÊ a-VEK ma va-LIZ","vi":"Làm ơn giúp tôi mang va li được không?","hl":["Pourriez-vous"],"tokens":["Pourriez-vous","m'aider","avec","ma","valise"]}]},{"steps":[{"t":"eau","ph":"Ô","vi":"nước","hl":[]},{"t":"d'eau s'il vous plaît","ph":"ĐÔ xin vu PLÊ","vi":"làm ơn cho nước","hl":["s'il vous plaît"]},{"t":"Une bouteille d'eau s'il vous plaît.","ph":"uyn bu-TEY ĐÔ xin vu PLÊ","vi":"Làm ơn cho tôi một chai nước.","hl":["s'il vous plaît"],"tokens":["Une","bouteille","d'eau","s'il","vous","plaît"]}]}],"formula":[{"k":"V","t":"Yêu cầu / Đồ vật"},{"k":"O","t":"(Bổ ngữ)"},{"k":"P","t":"s'il vous plaît"}],"points":["Thêm s'il vous plaît vào cuối câu để nhờ hoặc gọi món lịch sự (\"Un café s'il vous plaît\").","Có thể chỉ cần danh từ + s'il vous plaît, không cần động từ (\"L'addition s'il vous plaît\").","Nhờ vả lịch sự hơn nữa: Pourriez-vous + động từ nguyên mẫu (\"Pourriez-vous m'aider ?\").","Với bạn bè, người thân dùng s'il te plaît thay cho s'il vous plaît."],"mistakes":[{"wrong":"S'il vous plaît donnez-moi l'eau.","right":"De l'eau s'il vous plaît.","why":"Người Pháp thường để s'il vous plaît ở cuối câu và chỉ cần nói ngắn gọn món mình cần."},{"wrong":"Pourriez-vous m'aidez ?","right":"Pourriez-vous m'aider ?","why":"Sau Pourriez-vous động từ phải ở dạng nguyên mẫu (-er), không chia."}],"compare":"Tiếng Việt đặt \"làm ơn\" ở đầu câu (Làm ơn cho tôi...), còn tiếng Pháp thường để s'il vous plaît ở cuối câu, giống chữ \"nhé ạ\".","tip":"Đọc \"xin vu PLÊ\" — nghe như \"xin vui lòng\" của tiếng Việt, cực dễ nhớ!","how":["Thêm s'il vous plaît sau trạng từ lentement → lentement s'il vous plaît, rồi đặt Parlez plus ở đầu để nhờ nói chậm hơn → Parlez plus lentement s'il vous plaît.","Dùng Pourriez-vous (Anh có thể) + m'aider (giúp tôi) → Pourriez-vous m'aider, rồi thêm avec ma valise ở cuối → Pourriez-vous m'aider avec ma valise ?","eau bắt đầu bằng nguyên âm nên de thành d' → d'eau s'il vous plaît, rồi thêm Une bouteille ở đầu → Une bouteille d'eau s'il vous plaît."],"dialog":[{"who":"A","t":"Bonjour, un croissant s'il vous plaît.","ph":"bo~-JUR a~ croa-XA~ xin vu PLÊ","vi":"Chào chị, cho tôi một bánh sừng bò.","hl":["s'il vous plaît"]},{"who":"B","t":"Voilà. Autre chose ?","ph":"voa-LA ô-trơ SHÔZ","vi":"Đây ạ. Anh cần gì nữa không?","hl":[]},{"who":"A","t":"Pourriez-vous le mettre dans un sac ?","ph":"pu-ri-ê-VU lơ ME-TR đa~-za~ XAK","vi":"Chị có thể cho nó vào túi được không?","hl":["Pourriez-vous"]},{"who":"B","t":"Bien sûr. Un euro s'il vous plaît.","ph":"BIE~ XUYR a~-nơ-RÔ xin vu PLÊ","vi":"Tất nhiên. Một euro ạ.","hl":["s'il vous plaît"]}],"more":[{"t":"L'addition s'il vous plaît.","ph":"la-đi-XIO~ xin vu PLÊ","vi":"Làm ơn cho tính tiền.","hl":["s'il vous plaît"],"tokens":["L'addition","s'il","vous","plaît"]},{"t":"Un instant s'il vous plaît.","ph":"a~-ne~s-TA~ xin vu PLÊ","vi":"Xin đợi một chút.","hl":["s'il vous plaît"],"tokens":["Un","instant","s'il","vous","plaît"]},{"t":"Deux billets pour Lyon s'il vous plaît.","ph":"đơ bi-YÊ pur li-O~ xin vu PLÊ","vi":"Làm ơn cho hai vé đi Lyon.","hl":["s'il vous plaît"],"tokens":["Deux","billets","pour","Lyon","s'il","vous","plaît"]},{"t":"Pourriez-vous répéter le prix ?","ph":"pu-ri-ê-VU rê-pê-TÊ lơ PRI","vi":"Anh có thể nhắc lại giá được không?","hl":["Pourriez-vous"],"tokens":["Pourriez-vous","répéter","le","prix"]},{"t":"Fermez la porte s'il vous plaît.","ph":"fer-MÊ la PORT xin vu PLÊ","vi":"Làm ơn đóng cửa lại.","hl":["s'il vous plaît"],"tokens":["Fermez","la","porte","s'il","vous","plaît"]},{"t":"Pourriez-vous appeler un taxi pour nous ?","ph":"pu-ri-ê-VU ap-LÊ a~ tắc-XI pur NU","vi":"Anh có thể gọi taxi giúp chúng tôi không?","hl":["Pourriez-vous"],"tokens":["Pourriez-vous","appeler","un","taxi","pour","nous"]}]},{"id":16,"vi":"đừng","note":"Câu mệnh lệnh phủ định: ne + động từ mệnh lệnh + pas; ne thành n' trước nguyên âm.","pivot":{"t":"ne ... pas","ph":"nơ ... PA"},"branches":[{"steps":[{"t":"touchez","ph":"tu-SHÊ","vi":"chạm","hl":[]},{"t":"Ne touchez pas","ph":"nơ tu-SHÊ PA","vi":"đừng chạm","hl":["Ne","pas"]},{"t":"Ne touchez pas les tableaux.","ph":"nơ tu-SHÊ pa lê ta-BLÔ","vi":"Đừng chạm vào tranh.","hl":["Ne","pas"],"tokens":["Ne","touchez","pas","les","tableaux"]}]},{"steps":[{"t":"oublie","ph":"u-BLI","vi":"quên","hl":[]},{"t":"N'oublie pas","ph":"nu-BLI PA","vi":"đừng quên","hl":["N'","pas"]},{"t":"N'oublie pas ton passeport !","ph":"nu-BLI pa to~ pas-PÔR","vi":"Đừng quên hộ chiếu nhé!","hl":["N'","pas"],"tokens":["N'oublie","pas","ton","passeport"]}]},{"steps":[{"t":"inquiétez","ph":"e~-kiê-TÊ","vi":"lo lắng","hl":[]},{"t":"Ne vous inquiétez pas","ph":"nơ vu-ze~-kiê-TÊ PA","vi":"đừng lo","hl":["Ne","pas"]},{"t":"Ne vous inquiétez pas pour moi.","ph":"nơ vu-ze~-kiê-TÊ pa pur MOA","vi":"Đừng lo cho tôi.","hl":["Ne","pas"],"tokens":["Ne","vous","inquiétez","pas","pour","moi"]}]}],"formula":[{"k":"P","t":"Ne (N')"},{"k":"X","t":"(Đại từ)"},{"k":"V","t":"Động từ mệnh lệnh"},{"k":"P","t":"pas"},{"k":"O","t":"(Tân ngữ)"}],"points":["Câu \"đừng\" = Ne + động từ mệnh lệnh + pas, không có chủ ngữ (\"Ne touchez pas\").","Ne rút thành N' trước nguyên âm hoặc h câm (\"N'oublie pas\").","Dùng dạng tu (oublie, mange) với bạn bè, dạng vous (oubliez, touchez) cho lịch sự hoặc nhiều người.","Đại từ (vous, te, le) đứng giữa ne và động từ (\"Ne vous inquiétez pas\")."],"mistakes":[{"wrong":"Pas toucher les tableaux.","right":"Ne touchez pas les tableaux.","why":"Mệnh lệnh chuẩn cần đủ ne + động từ chia + pas; \"pas toucher\" chỉ là văn nói trẻ con."},{"wrong":"Ne inquiétez-vous pas.","right":"Ne vous inquiétez pas.","why":"Trong câu phủ định, đại từ vous đứng trước động từ, không gắn gạch nối ra sau."}],"compare":"Tiếng Việt chỉ cần \"Đừng\" ở đầu câu; tiếng Pháp cũng mở đầu bằng Ne nhưng phải đóng lại bằng pas sau động từ.","tip":"\"Đừng\" trong tiếng Pháp là cái kẹp Ne ... pas, chỉ là bỏ chủ ngữ đi thôi.","how":["Kẹp động từ mệnh lệnh touchez giữa Ne và pas → Ne touchez pas, rồi thêm les tableaux ở cuối → Ne touchez pas les tableaux.","oublie bắt đầu bằng nguyên âm nên Ne rút thành N' → N'oublie pas, rồi thêm ton passeport để nhắc → N'oublie pas ton passeport !","Đặt đại từ vous giữa Ne và inquiétez (đọc nối vu-ze~) rồi đóng bằng pas → Ne vous inquiétez pas, sau đó thêm pour moi → Ne vous inquiétez pas pour moi."],"dialog":[{"who":"A","t":"Ne cours pas, on a le temps !","ph":"nơ KUR pa o~-na lơ TA~","vi":"Đừng chạy, mình còn thời gian mà!","hl":["Ne","pas"]},{"who":"B","t":"Le train part dans cinq minutes.","ph":"lơ TRE~ PAR đa~ xe~ mi-NUYT","vi":"Năm phút nữa tàu chạy rồi.","hl":[]},{"who":"A","t":"N'oublie pas les billets alors.","ph":"nu-BLI pa lê bi-YÊ a-LOR","vi":"Vậy thì đừng quên vé nhé.","hl":["N'","pas"]},{"who":"B","t":"Ne t'inquiète pas, je les ai.","ph":"nơ te~-KIET pa jơ lê-ZÊ","vi":"Đừng lo, tớ cầm rồi.","hl":["Ne","pas"]}],"more":[{"t":"Ne fume pas ici.","ph":"nơ FUYM pa i-XI","vi":"Đừng hút thuốc ở đây.","hl":["Ne","pas"],"tokens":["Ne","fume","pas","ici"]},{"t":"N'ayez pas peur.","ph":"nê-YÊ pa PƠR","vi":"Đừng sợ.","hl":["N'","pas"],"tokens":["N'ayez","pas","peur"]},{"t":"Ne parlez pas trop fort.","ph":"nơ par-LÊ pa TRÔ FOR","vi":"Đừng nói quá to.","hl":["Ne","pas"],"tokens":["Ne","parlez","pas","trop","fort"]},{"t":"N'ouvrez pas la fenêtre s'il vous plaît.","ph":"nu-VRÊ pa la fơ-NE-TR xin vu PLÊ","vi":"Làm ơn đừng mở cửa sổ.","hl":["N'","pas"],"tokens":["N'ouvrez","pas","la","fenêtre","s'il","vous","plaît"]},{"t":"Ne mange pas trop de sucre.","ph":"nơ MA~J pa TRÔ đơ XUY-KR","vi":"Đừng ăn quá nhiều đường.","hl":["Ne","pas"],"tokens":["Ne","mange","pas","trop","de","sucre"]},{"t":"Ne laissez pas vos bagages sans surveillance.","ph":"nơ le-XÊ pa vô ba-GAJ xa~ xuyr-ve-YA~X","vi":"Đừng để hành lý không người trông.","hl":["Ne","pas"],"tokens":["Ne","laissez","pas","vos","bagages","sans","surveillance"]}]},{"id":17,"vi":"đã","note":"Thì quá khứ passé composé: avoir hoặc être (với động từ di chuyển như arriver) + phân từ quá khứ; với être phân từ hợp giống, số.","pivot":{"t":"avoir / être + participe","ph":"a-VOAR / E-TR"},"branches":[{"steps":[{"t":"mangé","ph":"ma~-JÊ","vi":"ăn (quá khứ)","hl":[]},{"t":"ai mangé","ph":"Ê ma~-JÊ","vi":"đã ăn","hl":["ai"]},{"t":"J'ai mangé une crêpe hier.","ph":"JÊ ma~-JÊ uyn KREP i-E","vi":"Hôm qua tôi đã ăn bánh crêpe.","hl":["ai"],"tokens":["J'ai","mangé","une","crêpe","hier"]}]},{"steps":[{"t":"arrivés","ph":"a-ri-VÊ","vi":"đến (quá khứ)","hl":[]},{"t":"sommes arrivés","ph":"xom-za-ri-VÊ","vi":"đã đến","hl":["sommes"]},{"t":"Nous sommes arrivés hier soir.","ph":"nu xom-za-ri-VÊ i-e SOAR","vi":"Chúng tôi đã đến tối qua.","hl":["sommes"],"tokens":["Nous","sommes","arrivés","hier","soir"]}]},{"steps":[{"t":"perdu","ph":"per-ĐUY","vi":"mất (quá khứ)","hl":[]},{"t":"as perdu","ph":"A per-ĐUY","vi":"đã làm mất","hl":["as"]},{"t":"Tu as perdu ta clé ?","ph":"tuy A per-ĐUY ta KLÊ","vi":"Bạn đã làm mất chìa khóa à?","hl":["as"],"tokens":["Tu","as","perdu","ta","clé"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"P","t":"avoir / être"},{"k":"V","t":"Phân từ quá khứ"},{"k":"O","t":"(Bổ ngữ / Thời gian)"}],"points":["Quá khứ (passé composé) = avoir hoặc être (chia ở hiện tại) + phân từ quá khứ (\"J'ai mangé\").","Phần lớn động từ dùng avoir; động từ di chuyển như aller, venir, arriver, partir, rester dùng être (\"Je suis arrivé\").","Với être, phân từ hợp giống, số với chủ ngữ (\"Elle est arrivée\", \"Nous sommes arrivés\").","Động từ -er có phân từ đuôi -é (manger → mangé); nhiều động từ khác bất quy tắc (perdre → perdu, prendre → pris)."],"mistakes":[{"wrong":"Je mangé hier.","right":"J'ai mangé hier.","why":"Thì quá khứ bắt buộc có trợ động từ avoir/être, không chỉ đổi động từ như thêm \"đã\" trong tiếng Việt."},{"wrong":"J'ai arrivé hier soir.","right":"Je suis arrivé hier soir.","why":"Arriver là động từ di chuyển nên dùng être, không dùng avoir."}],"compare":"Tiếng Việt chỉ thêm \"đã\" trước động từ; tiếng Pháp cần cả hai phần: trợ động từ avoir/être + động từ đổi sang dạng phân từ.","tip":"Nhớ \"nhà của être\": đi, đến, về, ở lại, ra, vào... — những động từ chuyển động \"vào nhà\" thì dùng être.","how":["Chia avoir với je thành ai rồi thêm phân từ mangé → ai mangé, sau đó ghép J'ai, thêm une crêpe và hier → J'ai mangé une crêpe hier.","arriver là động từ di chuyển nên dùng être: sommes + arrivés (thêm -s vì nous số nhiều) → sommes arrivés, rồi thêm Nous ở đầu và hier soir ở cuối → Nous sommes arrivés hier soir.","Chia avoir với tu thành as rồi thêm phân từ perdu (của perdre) → as perdu, sau đó thêm Tu ở đầu, ta clé ở cuối và lên giọng hỏi → Tu as perdu ta clé ?"],"dialog":[{"who":"A","t":"Tu as bien dormi ?","ph":"tuy A BIE~ đor-MI","vi":"Bạn ngủ ngon không?","hl":["as"]},{"who":"B","t":"Oui, mais je suis arrivé très tard.","ph":"UY me jơ xuy-za-ri-VÊ TRE TAR","vi":"Ngon, nhưng tôi đến rất muộn.","hl":["suis"]},{"who":"A","t":"Tu as mangé quelque chose ?","ph":"tuy A ma~-JÊ kel-kơ SHÔZ","vi":"Bạn đã ăn gì chưa?","hl":["as"]},{"who":"B","t":"Non, je n'ai rien mangé.","ph":"NO~ jơ NÊ RIE~ ma~-JÊ","vi":"Chưa, tôi chưa ăn gì cả.","hl":["ai"]}],"more":[{"t":"J'ai déjà fini.","ph":"JÊ đê-ja fi-NI","vi":"Tôi xong rồi.","hl":["ai"],"tokens":["J'ai","déjà","fini"]},{"t":"Elle est partie ce matin.","ph":"e-LE par-TI xơ ma-TE~","vi":"Cô ấy đã đi sáng nay.","hl":["est"],"tokens":["Elle","est","partie","ce","matin"]},{"t":"Nous avons visité Versailles.","ph":"nu-za-VO~ vi-zi-TÊ ver-XAY","vi":"Chúng tôi đã tham quan Versailles.","hl":["avons"],"tokens":["Nous","avons","visité","Versailles"]},{"t":"Tu as pris ton parapluie ?","ph":"tuy A PRI to~ pa-ra-PLUY","vi":"Bạn đã mang ô chưa?","hl":["as"],"tokens":["Tu","as","pris","ton","parapluie"]},{"t":"Ils sont restés trois jours à Nice.","ph":"il XO~ res-TÊ troa JUR a NIX","vi":"Họ đã ở lại Nice ba ngày.","hl":["sont"],"tokens":["Ils","sont","restés","trois","jours","à","Nice"]},{"t":"J'ai réservé une table pour ce soir.","ph":"JÊ rê-zer-VÊ uyn TA-BL pur xơ SOAR","vi":"Tôi đã đặt bàn cho tối nay.","hl":["ai"],"tokens":["J'ai","réservé","une","table","pour","ce","soir"]}]},{"id":18,"vi":"sẽ","note":"Tương lai gần: aller (je vais, il va) + động từ nguyên mẫu; tương lai đơn thêm đuôi -ai, -a... vào động từ (j'appellerai).","pivot":{"t":"aller + infinitif","ph":"a-LÊ"},"branches":[{"steps":[{"t":"visiter","ph":"vi-zi-TÊ","vi":"tham quan","hl":[]},{"t":"vais visiter","ph":"VÊ vi-zi-TÊ","vi":"sẽ tham quan","hl":["vais"]},{"t":"Je vais visiter le Louvre demain.","ph":"jơ VÊ vi-zi-TÊ lơ LUVR đơ-ME~","vi":"Ngày mai tôi sẽ đi thăm bảo tàng Louvre.","hl":["vais"],"tokens":["Je","vais","visiter","le","Louvre","demain"]}]},{"steps":[{"t":"pleuvoir","ph":"plơ-VOAR","vi":"mưa","hl":[]},{"t":"va pleuvoir","ph":"VA plơ-VOAR","vi":"sẽ mưa","hl":["va"]},{"t":"Il va pleuvoir ce soir.","ph":"il VA plơ-VOAR xơ SOAR","vi":"Tối nay trời sẽ mưa.","hl":["va"],"tokens":["Il","va","pleuvoir","ce","soir"]}]},{"steps":[{"t":"appellerai","ph":"a-pe-lơ-RÊ","vi":"sẽ gọi","hl":[]},{"t":"vous appellerai","ph":"vu-za-pe-lơ-RÊ","vi":"sẽ gọi cho anh","hl":["appellerai"]},{"t":"Je vous appellerai demain matin.","ph":"jơ vu-za-pe-lơ-RÊ đơ-ME~ ma-TE~","vi":"Sáng mai tôi sẽ gọi cho anh.","hl":["appellerai"],"tokens":["Je","vous","appellerai","demain","matin"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"P","t":"aller"},{"k":"V","t":"Động từ nguyên mẫu"},{"k":"O","t":"(Thời gian)"}],"points":["Tương lai gần = aller (je vais, tu vas, il va, nous allons, vous allez) + động từ nguyên mẫu (\"Je vais visiter\").","Dùng tương lai gần cho kế hoạch sắp tới hoặc điều chắc chắn sắp xảy ra (\"Il va pleuvoir\").","Tương lai đơn: thêm đuôi -ai, -as, -a, -ons, -ez, -ont vào động từ (je partirai, nous verrons).","Phủ định tương lai gần thì kẹp aller: \"Je ne vais pas sortir\"."],"mistakes":[{"wrong":"Je vais visite le Louvre.","right":"Je vais visiter le Louvre.","why":"Sau aller động từ phải ở dạng nguyên mẫu (-er), không chia."},{"wrong":"Je vais à visiter le Louvre.","right":"Je vais visiter le Louvre.","why":"Tương lai gần không có à; à chỉ dùng khi đi đến một nơi."}],"compare":"Tiếng Việt chỉ thêm \"sẽ\" trước động từ; tương lai gần tiếng Pháp mượn động từ aller (đi), giống kiểu nói \"tôi đi xem phim\" để chỉ việc sắp làm.","tip":"\"Sẽ\" = \"đi\" + làm gì: Je vais + manger = tôi sắp đi ăn đây!","how":["Chia aller với je thành vais rồi đặt động từ nguyên mẫu visiter ngay sau → vais visiter, sau đó thêm Je ở đầu, le Louvre và demain ở cuối → Je vais visiter le Louvre demain.","Chia aller với il thành va rồi thêm pleuvoir (mưa) → va pleuvoir, sau đó thêm chủ ngữ giả Il và ce soir → Il va pleuvoir ce soir.","Dùng tương lai đơn appellerai (appeler + -ai), đặt đại từ vous trước động từ → vous appellerai, rồi thêm Je ở đầu và demain matin ở cuối → Je vous appellerai demain matin."],"dialog":[{"who":"A","t":"Qu'est-ce que tu vas faire demain ?","ph":"kes-KƠ tuy VA FER đơ-ME~","vi":"Ngày mai bạn sẽ làm gì?","hl":["vas"]},{"who":"B","t":"Je vais faire du shopping.","ph":"jơ VÊ fer đuy sho-PING","vi":"Tôi sẽ đi mua sắm.","hl":["vais"]},{"who":"A","t":"Il va faire beau, je pense.","ph":"il VA fer BÔ jơ PA~X","vi":"Tôi nghĩ trời sẽ đẹp.","hl":["va"]},{"who":"B","t":"Super, je t'enverrai des photos.","ph":"xuy-PER jơ ta~-ve-RÊ đê fô-TÔ","vi":"Tuyệt, tôi sẽ gửi ảnh cho bạn.","hl":["enverrai"]}],"more":[{"t":"Je vais dormir.","ph":"jơ VÊ đor-MIR","vi":"Tôi sẽ đi ngủ.","hl":["vais"],"tokens":["Je","vais","dormir"]},{"t":"On va manger ensemble ?","ph":"o~ VA ma~-JÊ a~-XA~-BL","vi":"Mình sẽ ăn cùng nhau chứ?","hl":["va"],"tokens":["On","va","manger","ensemble"]},{"t":"Nous allons prendre le train.","ph":"nu-za-LO~ PRA~-ĐR lơ TRE~","vi":"Chúng tôi sẽ đi tàu.","hl":["allons"],"tokens":["Nous","allons","prendre","le","train"]},{"t":"Je partirai à six heures.","ph":"jơ par-ti-RÊ a xi-ZƠR","vi":"Tôi sẽ đi lúc sáu giờ.","hl":["partirai"],"tokens":["Je","partirai","à","six","heures"]},{"t":"Vous allez rester combien de temps ?","ph":"vu-za-LÊ res-TÊ ko~-BIE~ đơ TA~","vi":"Anh sẽ ở lại bao lâu?","hl":["allez"],"tokens":["Vous","allez","rester","combien","de","temps"]},{"t":"Je ne vais pas sortir ce soir.","ph":"jơ nơ VÊ pa xor-TIR xơ SOAR","vi":"Tối nay tôi sẽ không ra ngoài.","hl":["vais"],"tokens":["Je","ne","vais","pas","sortir","ce","soir"]}]},{"id":19,"vi":"đang","note":"Hành động đang diễn ra: être en train de + động từ nguyên mẫu; de thành d' trước nguyên âm.","pivot":{"t":"en train de","ph":"a~ TRE~ đơ"},"branches":[{"steps":[{"t":"manger","ph":"ma~-JÊ","vi":"ăn","hl":[]},{"t":"en train de manger","ph":"a~ TRE~ đơ ma~-JÊ","vi":"đang ăn","hl":["en train de"]},{"t":"Nous sommes en train de manger.","ph":"nu XOM a~ TRE~ đơ ma~-JÊ","vi":"Chúng tôi đang ăn.","hl":["en train de"],"tokens":["Nous","sommes","en","train","de","manger"]}]},{"steps":[{"t":"chercher","ph":"sher-SHÊ","vi":"tìm","hl":[]},{"t":"en train de chercher","ph":"a~ TRE~ đơ sher-SHÊ","vi":"đang tìm","hl":["en train de"]},{"t":"Je suis en train de chercher l'hôtel.","ph":"jơ XUY a~ TRE~ đơ sher-SHÊ lô-TEL","vi":"Tôi đang tìm khách sạn.","hl":["en train de"],"tokens":["Je","suis","en","train","de","chercher","l'hôtel"]}]},{"steps":[{"t":"attendre","ph":"a-TA~-ĐR","vi":"đợi","hl":[]},{"t":"en train d'attendre","ph":"a~ TRE~ đa-TA~-ĐR","vi":"đang đợi","hl":["en train d'"]},{"t":"Elle est en train d'attendre le bus.","ph":"e-LE a~ TRE~ đa-TA~-ĐR lơ BUYT","vi":"Cô ấy đang đợi xe buýt.","hl":["en train d'"],"tokens":["Elle","est","en","train","d'attendre","le","bus"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"V","t":"être (chia)"},{"k":"P","t":"en train de"},{"k":"V","t":"Động từ nguyên mẫu"},{"k":"O","t":"(Tân ngữ)"}],"points":["Dùng être en train de + động từ nguyên mẫu để nhấn mạnh hành động ĐANG diễn ra ngay lúc nói (\"Je suis en train de manger\").","Chỉ chia être theo chủ ngữ (je suis, tu es, il est, nous sommes, vous êtes, ils sont); động từ sau de luôn để nguyên mẫu.","De rút thành d' trước động từ bắt đầu bằng nguyên âm hoặc h câm (\"en train d'attendre\").","Thì hiện tại thường cũng có nghĩa \"đang\" (\"Je mange\" = tôi ăn / tôi đang ăn); en train de chỉ dùng khi muốn nhấn mạnh."],"mistakes":[{"wrong":"Je en train de manger.","right":"Je suis en train de manger.","why":"Thiếu động từ être: \"đang\" không đứng một mình, phải có suis/es/est... trước en train de."},{"wrong":"Elle est en train de attendre.","right":"Elle est en train d'attendre.","why":"Trước nguyên âm, de phải rút gọn thành d'."}],"compare":"Tiếng Việt chỉ cần thêm \"đang\" trước động từ; tiếng Pháp phải dùng cả cụm être + en train de, và chia être theo chủ ngữ.","tip":"\"En train\" nghĩa đen là \"trên tàu\": đang ngồi trên tàu = việc đang chạy dở, chưa xong!","how":["Đặt en train de trước động từ nguyên mẫu manger → en train de manger, rồi thêm chủ ngữ Nous với être chia thành sommes → Nous sommes en train de manger.","Ghép en train de với chercher → en train de chercher, thêm Je suis ở đầu và tân ngữ l'hôtel ở cuối → Je suis en train de chercher l'hôtel.","Vì attendre bắt đầu bằng nguyên âm nên de rút thành d' → en train d'attendre, thêm Elle est ở đầu và le bus ở cuối → Elle est en train d'attendre le bus."],"dialog":[{"who":"A","t":"Tu es où ?","ph":"tuy e U","vi":"Bạn đang ở đâu?","hl":[]},{"who":"B","t":"Je suis en train de faire les courses.","ph":"jơ XUY a~ TRE~ đơ FER lê KURS","vi":"Mình đang đi chợ.","hl":["en train de"]},{"who":"A","t":"Et Paul ?","ph":"ê PÔL","vi":"Còn Paul?","hl":[]},{"who":"B","t":"Il est en train de dormir à l'hôtel.","ph":"i-LE a~ TRE~ đơ đor-MIR a lô-TEL","vi":"Anh ấy đang ngủ ở khách sạn.","hl":["en train de"]}],"more":[{"t":"Je suis en train de lire.","ph":"jơ XUY a~ TRE~ đơ LIR","vi":"Tôi đang đọc sách.","hl":["en train de"],"tokens":["Je","suis","en","train","de","lire"]},{"t":"Il est en train de travailler.","ph":"i-LE a~ TRE~ đơ tra-va-YÊ","vi":"Anh ấy đang làm việc.","hl":["en train de"],"tokens":["Il","est","en","train","de","travailler"]},{"t":"Tu es en train de manger ?","ph":"tuy E a~ TRE~ đơ ma~-JÊ","vi":"Bạn đang ăn à?","hl":["en train de"],"tokens":["Tu","es","en","train","de","manger"]},{"t":"Je suis en train d'appeler un taxi.","ph":"jơ XUY a~ TRE~ đap-LÊ a~ tak-XI","vi":"Tôi đang gọi taxi.","hl":["en train d'"],"tokens":["Je","suis","en","train","d'appeler","un","taxi"]},{"t":"Nous sommes en train d'arriver à la gare.","ph":"nu XOM a~ TRE~ đa-ri-VÊ a la GAR","vi":"Chúng tôi đang đến ga.","hl":["en train d'"],"tokens":["Nous","sommes","en","train","d'arriver","à","la","gare"]},{"t":"Ils sont en train de visiter le musée.","ph":"il XO~ a~ TRE~ đơ vi-zi-TÊ lơ muy-ZÊ","vi":"Họ đang tham quan bảo tàng.","hl":["en train de"],"tokens":["Ils","sont","en","train","de","visiter","le","musée"]}]},{"id":20,"vi":"rồi","note":"Déjà (rồi) đặt giữa trợ động từ và phân từ quá khứ trong passé composé: j'ai déjà payé.","pivot":{"t":"déjà","ph":"đê-JA"},"branches":[{"steps":[{"t":"mangé","ph":"ma~-JÊ","vi":"ăn (quá khứ)","hl":[]},{"t":"déjà mangé","ph":"đê-JA ma~-JÊ","vi":"ăn rồi","hl":["déjà"]},{"t":"Nous avons déjà mangé.","ph":"nu-za-VO~ đê-JA ma~-JÊ","vi":"Chúng tôi ăn rồi.","hl":["déjà"],"tokens":["Nous","avons","déjà","mangé"]}]},{"steps":[{"t":"payé","ph":"pê-YÊ","vi":"trả tiền (quá khứ)","hl":[]},{"t":"déjà payé","ph":"đê-JA pê-YÊ","vi":"trả tiền rồi","hl":["déjà"]},{"t":"J'ai déjà payé la chambre.","ph":"JÊ đê-JA pê-YÊ la SHA~-BR","vi":"Tôi trả tiền phòng rồi.","hl":["déjà"],"tokens":["J'ai","déjà","payé","la","chambre"]}]},{"steps":[{"t":"parti","ph":"par-TI","vi":"đi (quá khứ)","hl":[]},{"t":"déjà parti","ph":"đê-JA par-TI","vi":"đi rồi","hl":["déjà"]},{"t":"Le bus est déjà parti.","ph":"lơ BUYT e đê-JA par-TI","vi":"Xe buýt đi mất rồi.","hl":["déjà"],"tokens":["Le","bus","est","déjà","parti"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"X","t":"avoir / être (chia)"},{"k":"P","t":"déjà"},{"k":"V","t":"Phân từ quá khứ"},{"k":"O","t":"(Tân ngữ)"}],"points":["Déjà nghĩa là \"rồi / đã ... rồi\", dùng nhiều nhất với thì quá khứ passé composé.","Trong passé composé, déjà đứng GIỮA trợ động từ (avoir/être) và phân từ quá khứ (\"J'ai déjà payé\").","Đa số động từ dùng avoir (j'ai mangé), còn động từ chỉ di chuyển như partir, arriver dùng être (il est parti).","Ở thì hiện tại, déjà đứng ngay sau động từ (\"Il est déjà là\" = Anh ấy đến rồi)."],"mistakes":[{"wrong":"J'ai payé déjà.","right":"J'ai déjà payé.","why":"Tiếng Việt để \"rồi\" cuối câu, nhưng tiếng Pháp chen déjà vào giữa ai và payé."},{"wrong":"Le bus a déjà parti.","right":"Le bus est déjà parti.","why":"Partir dùng trợ động từ être, không dùng avoir."}],"compare":"Tiếng Việt nói \"ăn rồi\" với \"rồi\" ở cuối; tiếng Pháp đưa déjà vào giữa câu, ngay trước phân từ quá khứ.","tip":"Nhớ cụm \"déjà vu\" (đã thấy rồi): déjà luôn đứng trước phân từ, y như đứng trước vu!","how":["Đặt déjà trước phân từ mangé → déjà mangé, rồi thêm Nous avons (trợ động từ avoir) ở trước → Nous avons déjà mangé.","Ghép déjà với payé → déjà payé, thêm J'ai ở đầu và tân ngữ la chambre ở cuối → J'ai déjà payé la chambre.","Ghép déjà với parti → déjà parti, vì partir dùng être nên thêm Le bus est ở trước → Le bus est déjà parti."],"dialog":[{"who":"A","t":"Tu veux manger quelque chose ?","ph":"tuy VƠ ma~-JÊ kel-kơ SHÔZ","vi":"Bạn muốn ăn gì không?","hl":[]},{"who":"B","t":"Non merci, j'ai déjà mangé.","ph":"no~ mer-XI JÊ đê-JA ma~-JÊ","vi":"Thôi cảm ơn, mình ăn rồi.","hl":["déjà"]},{"who":"A","t":"Tu as déjà vu ce film ?","ph":"tuy a đê-JA VUY xơ FILM","vi":"Bạn xem phim này rồi à?","hl":["déjà"]},{"who":"B","t":"Oui, deux fois !","ph":"uy đơ FOA","vi":"Ừ, hai lần rồi!","hl":[]}],"more":[{"t":"Il est déjà là.","ph":"i-LE đê-JA LA","vi":"Anh ấy đến rồi.","hl":["déjà"],"tokens":["Il","est","déjà","là"]},{"t":"J'ai déjà fini.","ph":"JÊ đê-JA fi-NI","vi":"Tôi xong rồi.","hl":["déjà"],"tokens":["J'ai","déjà","fini"]},{"t":"Elle est déjà partie ?","ph":"e-LE đê-JA par-TI","vi":"Cô ấy đi rồi à?","hl":["déjà"],"tokens":["Elle","est","déjà","partie"]},{"t":"Nous avons déjà visité Paris.","ph":"nu-za-VO~ đê-JA vi-zi-TÊ pa-RI","vi":"Chúng tôi đã thăm Paris rồi.","hl":["déjà"],"tokens":["Nous","avons","déjà","visité","Paris"]},{"t":"Vous avez déjà commandé le dîner ?","ph":"vu-za-VÊ đê-JA ko-ma~-ĐÊ lơ đi-NÊ","vi":"Anh chị gọi bữa tối rồi à?","hl":["déjà"],"tokens":["Vous","avez","déjà","commandé","le","dîner"]},{"t":"J'ai déjà acheté les billets de train.","ph":"JÊ đê-JA ash-TÊ lê bi-YÊ đơ TRE~","vi":"Tôi mua vé tàu rồi.","hl":["déjà"],"tokens":["J'ai","déjà","acheté","les","billets","de","train"]}]},{"id":21,"vi":"chưa","note":"Chưa làm gì: ne ... pas encore kẹp quanh trợ động từ; hỏi đã ... chưa dùng déjà trong câu hỏi.","pivot":{"t":"pas encore","ph":"pa-za~-KOR"},"branches":[{"steps":[{"t":"mangé","ph":"ma~-JÊ","vi":"ăn (quá khứ)","hl":[]},{"t":"pas encore mangé","ph":"pa-za~-KOR ma~-JÊ","vi":"chưa ăn","hl":["pas encore"]},{"t":"Je n'ai pas encore mangé.","ph":"jơ NÊ pa-za~-KOR ma~-JÊ","vi":"Tôi chưa ăn.","hl":["n'","pas encore"],"tokens":["Je","n'ai","pas","encore","mangé"]}]},{"steps":[{"t":"prêt","ph":"PRÊ","vi":"sẵn sàng","hl":[]},{"t":"pas encore prêt","ph":"pa-za~-KOR PRÊ","vi":"chưa xong","hl":["pas encore"]},{"t":"Le repas n'est pas encore prêt.","ph":"lơ rơ-PA NE pa-za~-KOR PRÊ","vi":"Bữa ăn chưa xong.","hl":["n'","pas encore"],"tokens":["Le","repas","n'est","pas","encore","prêt"]}]},{"steps":[{"t":"réservé","ph":"rê-zer-VÊ","vi":"đặt (quá khứ)","hl":[]},{"t":"déjà réservé","ph":"đê-JA rê-zer-VÊ","vi":"đặt chưa","hl":["déjà"]},{"t":"Vous avez déjà réservé l'hôtel ?","ph":"vu-za-VÊ đê-JA rê-zer-VÊ lô-TEL","vi":"Anh đã đặt khách sạn chưa?","hl":["déjà"],"tokens":["Vous","avez","déjà","réservé","l'hôtel"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"X","t":"ne (n')"},{"k":"X","t":"avoir / être (chia)"},{"k":"P","t":"pas encore"},{"k":"V","t":"Phân từ / Tính từ"}],"points":["\"Chưa\" = ne ... pas encore: ne (n') đứng trước động từ chia, pas encore đứng ngay sau nó (\"Je n'ai pas encore mangé\").","Ne rút thành n' trước nguyên âm (n'ai, n'est); văn nói hay bỏ ne (\"J'ai pas encore mangé\") nhưng khi học nên giữ.","Muốn hỏi \"đã ... chưa?\" thì dùng déjà trong câu hỏi (\"Vous avez déjà réservé ?\"), không dùng pas encore.","Trả lời ngắn \"chưa\" là \"Pas encore\", \"rồi\" là \"Oui, déjà\"."],"mistakes":[{"wrong":"Je pas encore mangé.","right":"Je n'ai pas encore mangé.","why":"Thiếu ne và trợ động từ ai: \"chưa ăn\" phải là n'ai pas encore mangé."},{"wrong":"Vous avez réservé pas encore ?","right":"Vous avez déjà réservé ?","why":"Câu hỏi \"đã ... chưa\" dùng déjà, không dịch từng chữ \"chưa\" thành pas encore."}],"compare":"Tiếng Việt chỉ thêm \"chưa\" trước động từ; tiếng Pháp kẹp ne ... pas encore quanh trợ động từ như kẹp bánh mì.","tip":"Cặp đôi dễ nhớ: déjà = rồi, pas encore = chưa. Hỏi bằng déjà, trả lời \"chưa\" bằng pas encore.","how":["Đặt pas encore trước phân từ mangé → pas encore mangé, rồi thêm Je n'ai (ne rút thành n' trước ai) ở đầu → Je n'ai pas encore mangé.","Ghép pas encore với tính từ prêt → pas encore prêt, thêm Le repas n'est ở trước → Le repas n'est pas encore prêt.","Để hỏi \"đã ... chưa\", đặt déjà trước réservé → déjà réservé, thêm Vous avez ở đầu, l'hôtel ở cuối và dấu ? → Vous avez déjà réservé l'hôtel ?"],"dialog":[{"who":"A","t":"Tu as déjà fini ton travail ?","ph":"tuy a đê-JA fi-NI to~ tra-VAI","vi":"Bạn làm xong việc chưa?","hl":["déjà"]},{"who":"B","t":"Non, pas encore.","ph":"no~ pa-za~-KOR","vi":"Chưa.","hl":["pas encore"]},{"who":"A","t":"Et tu as mangé ?","ph":"ê tuy a ma~-JÊ","vi":"Thế bạn ăn chưa?","hl":[]},{"who":"B","t":"Non, je n'ai pas encore eu le temps.","ph":"no~ jơ NÊ pa-za~-KOR uy lơ TA~","vi":"Chưa, mình chưa có thời gian.","hl":["n'","pas encore"]}],"more":[{"t":"Il n'est pas encore là.","ph":"il NE pa-za~-KOR LA","vi":"Anh ấy chưa đến.","hl":["n'","pas encore"],"tokens":["Il","n'est","pas","encore","là"]},{"t":"Je n'ai pas encore payé.","ph":"jơ NÊ pa-za~-KOR pê-YÊ","vi":"Tôi chưa trả tiền.","hl":["n'","pas encore"],"tokens":["Je","n'ai","pas","encore","payé"]},{"t":"Le train n'est pas encore arrivé.","ph":"lơ TRE~ ne pa-za~-KOR a-ri-VÊ","vi":"Tàu chưa đến.","hl":["n'","pas encore"],"tokens":["Le","train","n'est","pas","encore","arrivé"]},{"t":"Nous n'avons pas encore choisi.","ph":"nu na-VO~ pa-za~-KOR shoa-ZI","vi":"Chúng tôi chưa chọn món.","hl":["n'","pas encore"],"tokens":["Nous","n'avons","pas","encore","choisi"]},{"t":"Elle n'a pas encore réservé l'hôtel.","ph":"el NA pa-za~-KOR rê-zer-VÊ lô-TEL","vi":"Cô ấy chưa đặt khách sạn.","hl":["n'","pas encore"],"tokens":["Elle","n'a","pas","encore","réservé","l'hôtel"]},{"t":"Vous n'avez pas encore reçu la clé ?","ph":"vu na-VÊ pa-za~-KOR rơ-XUY la KLÊ","vi":"Anh chị chưa nhận chìa khóa à?","hl":["n'","pas encore"],"tokens":["Vous","n'avez","pas","encore","reçu","la","clé"]}]},{"id":22,"vi":"rất","note":"Très (rất) đứng trước tính từ; tính từ hợp giống và số với danh từ (bon, belle, gentils).","pivot":{"t":"très","ph":"TRE"},"branches":[{"steps":[{"t":"bon","ph":"BO~","vi":"ngon","hl":[]},{"t":"très bon","ph":"TRE BO~","vi":"rất ngon","hl":["très"]},{"t":"Ce gâteau est très bon.","ph":"xơ ga-TÔ e TRE BO~","vi":"Bánh này rất ngon.","hl":["très"],"tokens":["Ce","gâteau","est","très","bon"]}]},{"steps":[{"t":"belle","ph":"BEL","vi":"đẹp","hl":[]},{"t":"très belle","ph":"TRE BEL","vi":"rất đẹp","hl":["très"]},{"t":"La ville est très belle.","ph":"la VIL e TRE BEL","vi":"Thành phố rất đẹp.","hl":["très"],"tokens":["La","ville","est","très","belle"]}]},{"steps":[{"t":"gentils","ph":"ja~-TI","vi":"tử tế","hl":[]},{"t":"très gentils","ph":"TRE ja~-TI","vi":"rất tử tế","hl":["très"]},{"t":"Les gens sont très gentils ici.","ph":"lê JA~ xo~ TRE ja~-TI i-XI","vi":"Người ở đây rất tử tế.","hl":["très"],"tokens":["Les","gens","sont","très","gentils","ici"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"V","t":"être (chia)"},{"k":"P","t":"très"},{"k":"A","t":"Tính từ"}],"points":["Très (rất) đứng ngay trước tính từ hoặc trạng từ (\"très bon\", \"très vite\").","Tính từ phải hợp giống và số với danh từ (bon/bonne, beau/belle, gentil/gentils), còn très thì không bao giờ đổi.","Très cũng đi với trạng từ: \"très bien\" (rất tốt), \"très loin\" (rất xa).","Không dùng très với danh từ hay động từ: cảm ơn rất nhiều là \"merci beaucoup\", không phải \"merci très\"."],"mistakes":[{"wrong":"Ce gâteau est bon très.","right":"Ce gâteau est très bon.","why":"Très đứng TRƯỚC tính từ, không đặt sau như kiểu \"ngon lắm\"."},{"wrong":"Merci très.","right":"Merci beaucoup.","why":"Très chỉ đi với tính từ/trạng từ; \"cảm ơn rất nhiều\" dùng beaucoup."}],"compare":"Giống tiếng Việt, très đứng trước tính từ (rất ngon = très bon); khác ở chỗ tiếng Pháp cần động từ être (est) và tính từ phải đổi theo giống, số.","tip":"Très = \"rất\": cả hai đều đứng trước tính từ, cứ đặt như tiếng Việt là đúng!","how":["Đặt très trước tính từ bon → très bon, rồi thêm Ce gâteau est ở trước → Ce gâteau est très bon.","Ghép très với belle (giống cái vì ville là giống cái) → très belle, thêm La ville est ở trước → La ville est très belle.","Ghép très với gentils (số nhiều theo gens) → très gentils, thêm Les gens sont ở trước và ici ở cuối → Les gens sont très gentils ici."],"dialog":[{"who":"A","t":"Comment est ton hôtel ?","ph":"ko-MA~ e to~-nô-TEL","vi":"Khách sạn của bạn thế nào?","hl":[]},{"who":"B","t":"Il est très confortable.","ph":"i-LE TRE ko~-for-TA-BL","vi":"Rất thoải mái.","hl":["très"]},{"who":"A","t":"Et la vue ?","ph":"ê la VUY","vi":"Còn cảnh nhìn thì sao?","hl":[]},{"who":"B","t":"Très belle, on voit la mer !","ph":"TRE BEL o~ VOA la MER","vi":"Rất đẹp, nhìn thấy cả biển!","hl":["Très"]}],"more":[{"t":"C'est très bien.","ph":"xê TRE BIE~","vi":"Rất tốt.","hl":["très"],"tokens":["C'est","très","bien"]},{"t":"Il fait très chaud.","ph":"il FE TRE SHÔ","vi":"Trời rất nóng.","hl":["très"],"tokens":["Il","fait","très","chaud"]},{"t":"Elle est très fatiguée.","ph":"e-LE TRE fa-ti-GHÊ","vi":"Cô ấy rất mệt.","hl":["très"],"tokens":["Elle","est","très","fatiguée"]},{"t":"Le musée est très intéressant.","ph":"lơ muy-ZÊ e TRE-ze~-tê-rê-XA~","vi":"Bảo tàng rất thú vị.","hl":["très"],"tokens":["Le","musée","est","très","intéressant"]},{"t":"Ce restaurant n'est pas très cher.","ph":"xơ rết-tô-RA~ ne PA TRE SHER","vi":"Nhà hàng này không đắt lắm.","hl":["très"],"tokens":["Ce","restaurant","n'est","pas","très","cher"]},{"t":"Vous parlez très bien le français.","ph":"vu par-LÊ TRE BIE~ lơ fra~-XÊ","vi":"Bạn nói tiếng Pháp rất giỏi.","hl":["très"],"tokens":["Vous","parlez","très","bien","le","français"]}]},{"id":23,"vi":"quá","note":"Trop (quá) đứng trước tính từ hoặc trạng từ để chỉ mức độ vượt quá mong muốn.","pivot":{"t":"trop","ph":"TRÔ"},"branches":[{"steps":[{"t":"cher","ph":"SHER","vi":"đắt","hl":[]},{"t":"trop cher","ph":"TRÔ SHER","vi":"quá đắt","hl":["trop"]},{"t":"C'est trop cher pour moi.","ph":"xê TRÔ SHER pur MOA","vi":"Cái này quá đắt với tôi.","hl":["trop"],"tokens":["C'est","trop","cher","pour","moi"]}]},{"steps":[{"t":"chaude","ph":"SHÔT","vi":"nóng","hl":[]},{"t":"trop chaude","ph":"TRÔ SHÔT","vi":"quá nóng","hl":["trop"]},{"t":"La soupe est trop chaude.","ph":"la XUP e TRÔ SHÔT","vi":"Súp nóng quá.","hl":["trop"],"tokens":["La","soupe","est","trop","chaude"]}]},{"steps":[{"t":"loin","ph":"LOE~","vi":"xa","hl":[]},{"t":"trop loin","ph":"TRÔ LOE~","vi":"quá xa","hl":["trop"]},{"t":"L'hôtel est trop loin d'ici.","ph":"lô-TEL e TRÔ LOE~ đi-XI","vi":"Khách sạn xa quá.","hl":["trop"],"tokens":["L'hôtel","est","trop","loin","d'ici"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"V","t":"être (chia)"},{"k":"P","t":"trop"},{"k":"A","t":"Tính từ / Trạng từ"},{"k":"O","t":"(pour + ai)"}],"points":["Trop (quá) đứng trước tính từ hoặc trạng từ và mang nghĩa TIÊU CỰC: vượt mức mong muốn (\"trop cher\" = đắt quá, không mua nổi).","Muốn khen \"ngon quá!\" thì dùng très hoặc vraiment (\"C'est vraiment bon !\"), không dùng trop trong văn chuẩn.","Trop de + danh từ = quá nhiều cái gì (\"trop de monde\" = quá đông người).","Tính từ sau trop vẫn hợp giống, số với danh từ (\"la soupe est trop chaude\")."],"mistakes":[{"wrong":"C'est cher trop.","right":"C'est trop cher.","why":"Tiếng Việt nói \"đắt quá\", nhưng trop phải đứng TRƯỚC tính từ."},{"wrong":"Il y a trop des gens.","right":"Il y a trop de gens.","why":"Sau trop, danh từ chỉ đi với de, không dùng des."}],"compare":"Tiếng Việt \"quá\" thường đứng sau tính từ (đắt quá) và hay dùng để khen; tiếng Pháp trop luôn đứng trước và thường mang ý phàn nàn.","tip":"Trop nghe như \"tràn\": tràn ra ngoài mức cho phép, nên đó là điều không mong muốn!","how":["Đặt trop trước tính từ cher → trop cher, rồi thêm C'est ở đầu và pour moi ở cuối → C'est trop cher pour moi.","Ghép trop với chaude (giống cái theo soupe) → trop chaude, thêm La soupe est ở trước → La soupe est trop chaude.","Ghép trop với trạng từ loin → trop loin, thêm L'hôtel est ở trước và d'ici ở cuối → L'hôtel est trop loin d'ici."],"dialog":[{"who":"A","t":"On prend un taxi ?","ph":"o~ PRA~ a~ tak-XI","vi":"Mình đi taxi nhé?","hl":[]},{"who":"B","t":"Non, c'est trop cher.","ph":"no~ xê TRÔ SHER","vi":"Thôi, đắt quá.","hl":["trop"]},{"who":"A","t":"À pied alors ?","ph":"a PIÊ a-LOR","vi":"Vậy đi bộ nhé?","hl":[]},{"who":"B","t":"C'est trop loin, prenons le métro.","ph":"xê TRÔ LOE~ prơ-NO~ lơ mê-TRÔ","vi":"Xa quá, đi tàu điện ngầm đi.","hl":["trop"]}],"more":[{"t":"C'est trop petit.","ph":"xê TRÔ pơ-TI","vi":"Nhỏ quá.","hl":["trop"],"tokens":["C'est","trop","petit"]},{"t":"Vous parlez trop vite.","ph":"vu par-LÊ TRÔ VIT","vi":"Anh nói nhanh quá.","hl":["trop"],"tokens":["Vous","parlez","trop","vite"]},{"t":"Ce café est trop sucré.","ph":"xơ ka-FÊ e TRÔ xuy-KRÊ","vi":"Cà phê này ngọt quá.","hl":["trop"],"tokens":["Ce","café","est","trop","sucré"]},{"t":"Il y a trop de monde ici.","ph":"i-li-A TRÔ đơ MO~Đ i-XI","vi":"Ở đây đông người quá.","hl":["trop"],"tokens":["Il","y","a","trop","de","monde","ici"]},{"t":"Ces chaussures sont trop grandes pour moi.","ph":"xê shô-XUYR xo~ TRÔ GRA~Đ pur MOA","vi":"Đôi giày này rộng quá với tôi.","hl":["trop"],"tokens":["Ces","chaussures","sont","trop","grandes","pour","moi"]},{"t":"Je suis trop fatigué pour sortir ce soir.","ph":"jơ XUY TRÔ fa-ti-GHÊ pur xor-TIR xơ SOAR","vi":"Tối nay tôi mệt quá không đi chơi được.","hl":["trop"],"tokens":["Je","suis","trop","fatigué","pour","sortir","ce","soir"]}]},{"id":24,"vi":"hơn","note":"So sánh hơn: plus + tính từ + que (hơn); tính từ hợp giống, số với chủ ngữ.","pivot":{"t":"plus ... que","ph":"PLUY ... KƠ"},"branches":[{"steps":[{"t":"grand","ph":"GRA~","vi":"lớn","hl":[]},{"t":"plus grand que","ph":"PLUY GRA~ KƠ","vi":"lớn hơn","hl":["plus","que"]},{"t":"Paris est plus grand que Lyon.","ph":"pa-RI e PLUY GRA~ kơ li-O~","vi":"Paris lớn hơn Lyon.","hl":["plus","que"],"tokens":["Paris","est","plus","grand","que","Lyon"]}]},{"steps":[{"t":"chère","ph":"SHER","vi":"đắt","hl":[]},{"t":"plus chère que","ph":"PLUY SHER KƠ","vi":"đắt hơn","hl":["plus","que"]},{"t":"Cette chambre est plus chère que l'autre.","ph":"xét SHA~-BR e PLUY SHER kơ LÔ-TR","vi":"Phòng này đắt hơn phòng kia.","hl":["plus","que"],"tokens":["Cette","chambre","est","plus","chère","que","l'autre"]}]},{"steps":[{"t":"rapide","ph":"ra-PIT","vi":"nhanh","hl":[]},{"t":"plus rapide que","ph":"PLUY ra-PIT KƠ","vi":"nhanh hơn","hl":["plus","que"]},{"t":"Le train est plus rapide que le bus.","ph":"lơ TRE~ e PLUY ra-PIT kơ lơ BUYT","vi":"Tàu hỏa nhanh hơn xe buýt.","hl":["plus","que"],"tokens":["Le","train","est","plus","rapide","que","le","bus"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"V","t":"être (chia)"},{"k":"P","t":"plus"},{"k":"A","t":"Tính từ"},{"k":"P","t":"que"},{"k":"O","t":"Đối tượng so sánh"}],"points":["So sánh hơn: plus + tính từ + que + đối tượng (\"plus grand que Lyon\").","Tính từ hợp giống, số với chủ ngữ (\"cette chambre est plus chère\").","Que rút thành qu' trước nguyên âm (\"qu'hier\") và đi với đại từ nhấn mạnh moi, toi (\"plus grand que moi\").","Bon không nói \"plus bon\" mà là meilleur (tốt hơn, ngon hơn): \"Ce vin est meilleur\"."],"mistakes":[{"wrong":"Paris est grand plus Lyon.","right":"Paris est plus grand que Lyon.","why":"Tiếng Việt để \"hơn\" sau tính từ, còn tiếng Pháp đặt plus TRƯỚC tính từ và cần que trước đối tượng."},{"wrong":"Ce vin est plus bon.","right":"Ce vin est meilleur.","why":"Bon là tính từ bất quy tắc: \"ngon hơn\" là meilleur."}],"compare":"Tiếng Việt: tính từ + hơn + đối tượng (to hơn Lyon); tiếng Pháp: plus + tính từ + que + đối tượng, tức chữ \"hơn\" bị tách làm hai.","tip":"Kẹp tính từ như bánh sandwich: plus ở trên, que ở dưới → plus GRAND que.","how":["Kẹp tính từ grand giữa plus và que → plus grand que, rồi thêm Paris est ở đầu và Lyon ở cuối → Paris est plus grand que Lyon.","Kẹp chère (giống cái theo chambre) vào plus ... que → plus chère que, thêm Cette chambre est ở trước và l'autre ở sau → Cette chambre est plus chère que l'autre.","Kẹp rapide vào plus ... que → plus rapide que, thêm Le train est ở đầu và le bus ở cuối → Le train est plus rapide que le bus."],"dialog":[{"who":"A","t":"On prend le train ou l'avion ?","ph":"o~ PRA~ lơ TRE~ u la-VIO~","vi":"Mình đi tàu hay máy bay?","hl":[]},{"who":"B","t":"L'avion est plus rapide que le train.","ph":"la-VIO~ e PLUY ra-PIT kơ lơ TRE~","vi":"Máy bay nhanh hơn tàu.","hl":["plus","que"]},{"who":"A","t":"Oui, mais il est plus cher.","ph":"uy mê i-LE PLUY SHER","vi":"Ừ, nhưng đắt hơn.","hl":["plus"]}],"more":[{"t":"Il est plus grand que moi.","ph":"i-LE PLUY GRA~ kơ MOA","vi":"Anh ấy cao hơn tôi.","hl":["plus","que"],"tokens":["Il","est","plus","grand","que","moi"]},{"t":"Cette robe est plus jolie que l'autre.","ph":"xét RÔP e PLUY jo-LI kơ LÔ-TR","vi":"Chiếc váy này đẹp hơn chiếc kia.","hl":["plus","que"],"tokens":["Cette","robe","est","plus","jolie","que","l'autre"]},{"t":"Le métro est plus pratique que le taxi.","ph":"lơ mê-TRÔ e PLUY pra-TIK kơ lơ tak-XI","vi":"Tàu điện ngầm tiện hơn taxi.","hl":["plus","que"],"tokens":["Le","métro","est","plus","pratique","que","le","taxi"]},{"t":"Aujourd'hui il fait plus froid qu'hier.","ph":"ô-jur-ĐUY il FE PLUY FROA kiê-ER","vi":"Hôm nay lạnh hơn hôm qua.","hl":["plus","qu'"],"tokens":["Aujourd'hui","il","fait","plus","froid","qu'hier"]},{"t":"Ma valise est plus lourde que la tienne.","ph":"ma va-LIZ e PLUY LURĐ kơ la TIEN","vi":"Vali của tôi nặng hơn của bạn.","hl":["plus","que"],"tokens":["Ma","valise","est","plus","lourde","que","la","tienne"]},{"t":"Le français est plus difficile que l'anglais.","ph":"lơ fra~-XÊ e PLUY đi-fi-XIL kơ la~-GLÊ","vi":"Tiếng Pháp khó hơn tiếng Anh.","hl":["plus","que"],"tokens":["Le","français","est","plus","difficile","que","l'anglais"]}]},{"id":25,"vi":"nhất","note":"So sánh nhất: le/la/les plus + tính từ (nhất); bon thành le meilleur (tốt nhất).","pivot":{"t":"le plus","ph":"lơ PLUY"},"branches":[{"steps":[{"t":"beau","ph":"BÔ","vi":"đẹp","hl":[]},{"t":"le plus beau","ph":"lơ PLUY BÔ","vi":"đẹp nhất","hl":["le plus"]},{"t":"C'est le plus beau musée de Paris.","ph":"xê lơ PLUY BÔ muy-ZÊ đơ pa-RI","vi":"Đây là bảo tàng đẹp nhất Paris.","hl":["le plus"],"tokens":["C'est","le","plus","beau","musée","de","Paris"]}]},{"steps":[{"t":"proche","ph":"PROSH","vi":"gần","hl":[]},{"t":"la plus proche","ph":"la PLUY PROSH","vi":"gần nhất","hl":["la plus"]},{"t":"Où est la pharmacie la plus proche ?","ph":"U e la far-ma-XI la PLUY PROSH","vi":"Hiệu thuốc gần nhất ở đâu?","hl":["la plus"],"tokens":["Où","est","la","pharmacie","la","plus","proche"]}]},{"steps":[{"t":"meilleur","ph":"me-YƠR","vi":"tốt hơn","hl":[]},{"t":"le meilleur","ph":"lơ me-YƠR","vi":"tốt nhất","hl":["le meilleur"]},{"t":"C'est le meilleur restaurant du quartier.","ph":"xê lơ me-YƠR rết-tô-RA~ đuy kar-TIÊ","vi":"Đây là nhà hàng ngon nhất khu này.","hl":["le meilleur"],"tokens":["C'est","le","meilleur","restaurant","du","quartier"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"V","t":"être (chia)"},{"k":"P","t":"le / la / les plus"},{"k":"A","t":"Tính từ"},{"k":"O","t":"(de + phạm vi)"}],"points":["So sánh nhất: le/la/les + plus + tính từ; mạo từ hợp giống, số với danh từ (le plus beau, la plus proche, les plus chers).","Phạm vi so sánh dùng de: \"le plus beau musée de Paris\" (đẹp nhất ở Paris).","Khi tính từ đứng sau danh từ thì phải lặp lại mạo từ: \"la pharmacie la plus proche\".","Bon thành le meilleur / la meilleure (tốt nhất, ngon nhất), không nói \"le plus bon\"."],"mistakes":[{"wrong":"Où est la pharmacie plus proche ?","right":"Où est la pharmacie la plus proche ?","why":"Tính từ đứng sau danh từ phải lặp lại mạo từ la trước plus, nếu thiếu thì thành so sánh hơn."},{"wrong":"C'est le plus bon restaurant.","right":"C'est le meilleur restaurant.","why":"\"Ngon nhất / tốt nhất\" của bon là le meilleur."}],"compare":"Tiếng Việt chỉ thêm \"nhất\" sau tính từ (đẹp nhất); tiếng Pháp đặt le/la/les plus trước tính từ và dùng de cho phạm vi (nhất Paris = de Paris).","tip":"Le plus = \"cái hơn cả\": gắn mạo từ le vào plus là từ \"hơn\" biến thành \"nhất\".","how":["Đặt le plus trước tính từ beau → le plus beau, rồi thêm C'est ở đầu, musée và de Paris ở sau → C'est le plus beau musée de Paris.","Vì pharmacie là giống cái nên dùng la plus với proche → la plus proche, đặt sau la pharmacie và mở đầu bằng Où est → Où est la pharmacie la plus proche ?","Bon ở dạng so sánh nhất là le meilleur → le meilleur, thêm C'est ở đầu và restaurant du quartier ở sau → C'est le meilleur restaurant du quartier."],"dialog":[{"who":"A","t":"Quel est le plat le plus connu ici ?","ph":"kel E lơ PLA lơ PLUY ko-NUY i-XI","vi":"Món nổi tiếng nhất ở đây là gì?","hl":["le plus"]},{"who":"B","t":"Le coq au vin, c'est le plus populaire.","ph":"lơ KOK ô VE~ xê lơ PLUY po-puy-LER","vi":"Gà nấu rượu vang, món phổ biến nhất.","hl":["le plus"]},{"who":"A","t":"Et le meilleur dessert ?","ph":"ê lơ me-YƠR đê-XER","vi":"Còn món tráng miệng ngon nhất?","hl":["le meilleur"]},{"who":"B","t":"La tarte aux pommes !","ph":"la TART ô POM","vi":"Bánh táo!","hl":[]}],"more":[{"t":"C'est le plus grand.","ph":"xê lơ PLUY GRA~","vi":"Cái này lớn nhất.","hl":["le plus"],"tokens":["C'est","le","plus","grand"]},{"t":"C'est la plus belle plage.","ph":"xê la PLUY BEL PLAJ","vi":"Đây là bãi biển đẹp nhất.","hl":["la plus"],"tokens":["C'est","la","plus","belle","plage"]},{"t":"Voici les fruits les plus frais.","ph":"voa-XI lê FRUY lê PLUY FRE","vi":"Đây là những trái cây tươi nhất.","hl":["les plus"],"tokens":["Voici","les","fruits","les","plus","frais"]},{"t":"Quel est le chemin le plus court ?","ph":"kel E lơ shơ-ME~ lơ PLUY KUR","vi":"Đường nào ngắn nhất?","hl":["le plus"],"tokens":["Quel","est","le","chemin","le","plus","court"]},{"t":"C'est l'hôtel le plus cher de la ville.","ph":"xê lô-TEL lơ PLUY SHER đơ la VIL","vi":"Đây là khách sạn đắt nhất thành phố.","hl":["le plus"],"tokens":["C'est","l'hôtel","le","plus","cher","de","la","ville"]},{"t":"Paris est la plus grande ville de France.","ph":"pa-RI e la PLUY GRA~Đ VIL đơ FRA~X","vi":"Paris là thành phố lớn nhất nước Pháp.","hl":["la plus"],"tokens":["Paris","est","la","plus","grande","ville","de","France"]}]},{"id":26,"vi":"cũng","note":"Aussi (cũng) thường đứng ngay sau động từ chia; moi aussi = tôi cũng vậy.","pivot":{"t":"aussi","ph":"ô-XI"},"branches":[{"steps":[{"t":"aime","ph":"EM","vi":"thích","hl":[]},{"t":"aime aussi","ph":"EM ô-XI","vi":"cũng thích","hl":["aussi"]},{"t":"J'aime aussi le fromage.","ph":"JEM ô-XI lơ fro-MAJ","vi":"Tôi cũng thích phô mai.","hl":["aussi"],"tokens":["J'aime","aussi","le","fromage"]}]},{"steps":[{"t":"parle","ph":"PARL","vi":"nói","hl":[]},{"t":"parle aussi","ph":"PARL ô-XI","vi":"cũng nói","hl":["aussi"]},{"t":"Elle parle aussi français.","ph":"el PARL ô-XI fra~-XÊ","vi":"Cô ấy cũng nói tiếng Pháp.","hl":["aussi"],"tokens":["Elle","parle","aussi","français"]}]},{"steps":[{"t":"viens","ph":"VIE~","vi":"đi cùng, đến","hl":[]},{"t":"viens aussi","ph":"VIE~ ô-XI","vi":"cũng đi","hl":["aussi"]},{"t":"Je viens aussi avec vous.","ph":"jơ VIE~ ô-XI a-VEK VU","vi":"Tôi cũng đi cùng các bạn.","hl":["aussi"],"tokens":["Je","viens","aussi","avec","vous"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"V","t":"Động từ (chia)"},{"k":"P","t":"aussi"},{"k":"O","t":"Tân ngữ"}],"points":["Aussi (cũng) thường đứng ngay SAU động từ đã chia (\"J'aime aussi le fromage\").","Trả lời \"tôi cũng vậy\" dùng đại từ nhấn mạnh + aussi: moi aussi, toi aussi, lui aussi.","Với thì kép, aussi đứng giữa trợ động từ và phân từ (\"J'ai aussi visité Lyon\").","\"Cũng không\" là non plus, không dùng aussi: \"Moi non plus\" (tôi cũng không)."],"mistakes":[{"wrong":"Je aussi aime le fromage.","right":"J'aime aussi le fromage.","why":"Tiếng Việt đặt \"cũng\" trước động từ, còn tiếng Pháp đặt aussi SAU động từ; je còn phải rút thành j'."},{"wrong":"Moi aussi pas.","right":"Moi non plus.","why":"\"Tôi cũng không\" là moi non plus, không ghép aussi với pas."}],"compare":"Tiếng Việt: \"cũng\" đứng trước động từ (tôi cũng thích); tiếng Pháp: aussi đứng sau động từ (j'aime aussi).","tip":"Động từ đi trước, aussi theo sau như cái đuôi: \"aime aussi\", \"parle aussi\".","how":["Đặt aussi ngay sau động từ aime → aime aussi, thêm J' ở đầu và le fromage ở cuối → J'aime aussi le fromage.","Đặt aussi sau động từ parle → parle aussi, thêm Elle ở đầu và français ở cuối → Elle parle aussi français.","Đặt aussi sau động từ viens → viens aussi, thêm Je ở đầu và avec vous ở cuối → Je viens aussi avec vous."],"dialog":[{"who":"A","t":"J'adore cette ville !","ph":"ja-ĐOR xét VIL","vi":"Mình mê thành phố này quá!","hl":[]},{"who":"B","t":"Moi aussi !","ph":"MOA ô-XI","vi":"Mình cũng vậy!","hl":["aussi"]},{"who":"A","t":"Tu visites aussi le Louvre demain ?","ph":"tuy vi-ZIT ô-XI lơ LU-VR đơ-ME~","vi":"Mai bạn cũng đi bảo tàng Louvre à?","hl":["aussi"]},{"who":"B","t":"Oui, et ma sœur vient aussi.","ph":"uy ê ma XƠR VIE~ ô-XI","vi":"Ừ, chị mình cũng đi.","hl":["aussi"]}],"more":[{"t":"Il travaille aussi ici.","ph":"il tra-VAI ô-XI i-XI","vi":"Anh ấy cũng làm việc ở đây.","hl":["aussi"],"tokens":["Il","travaille","aussi","ici"]},{"t":"Nous mangeons aussi du riz.","ph":"nu ma~-JO~ ô-XI đuy RI","vi":"Chúng tôi cũng ăn cơm.","hl":["aussi"],"tokens":["Nous","mangeons","aussi","du","riz"]},{"t":"Ils parlent aussi anglais.","ph":"il PARL ô-XI a~-GLÊ","vi":"Họ cũng nói tiếng Anh.","hl":["aussi"],"tokens":["Ils","parlent","aussi","anglais"]},{"t":"Tu veux aussi un café ?","ph":"tuy VƠ ô-XI a~ ka-FÊ","vi":"Bạn cũng muốn một ly cà phê à?","hl":["aussi"],"tokens":["Tu","veux","aussi","un","café"]},{"t":"J'ai aussi visité le château.","ph":"JÊ ô-XI vi-zi-TÊ lơ sha-TÔ","vi":"Tôi cũng đã thăm lâu đài.","hl":["aussi"],"tokens":["J'ai","aussi","visité","le","château"]},{"t":"Ma femme aime aussi la cuisine vietnamienne.","ph":"ma FAM EM ô-XI la kuy-ZIN viết-na-MIEN","vi":"Vợ tôi cũng thích món ăn Việt Nam.","hl":["aussi"],"tokens":["Ma","femme","aime","aussi","la","cuisine","vietnamienne"]}]},{"id":27,"vi":"và","note":"Et (và) nối hai danh từ hoặc hai mệnh đề; mỗi danh từ giữ mạo từ riêng (un café et un thé).","pivot":{"t":"et","ph":"Ê"},"branches":[{"steps":[{"t":"thé","ph":"TÊ","vi":"trà","hl":[]},{"t":"et un thé","ph":"Ê a~ TÊ","vi":"và một trà","hl":["et"]},{"t":"Un café et un thé s'il vous plaît.","ph":"a~ ka-FÊ ê a~ TÊ xin vu PLÊ","vi":"Cho một cà phê và một trà.","hl":["et"],"tokens":["Un","café","et","un","thé","s'il","vous","plaît"]}]},{"steps":[{"t":"sœur","ph":"XƠR","vi":"chị/em gái","hl":[]},{"t":"et ma sœur","ph":"Ê ma XƠR","vi":"và chị gái tôi","hl":["et"]},{"t":"Mon frère et ma sœur habitent à Paris.","ph":"mo~ FRER ê ma XƠR a-BIT a pa-RI","vi":"Anh trai và chị gái tôi sống ở Paris.","hl":["et"],"tokens":["Mon","frère","et","ma","sœur","habitent","à","Paris"]}]},{"steps":[{"t":"rentre","ph":"RA~-TR","vi":"về","hl":[]},{"t":"et je rentre","ph":"Ê jơ RA~-TR","vi":"và tôi về","hl":["et"]},{"t":"Je dîne et je rentre à l'hôtel.","ph":"jơ ĐIN ê jơ RA~-TR a lô-TEL","vi":"Tôi ăn tối và về khách sạn.","hl":["et"],"tokens":["Je","dîne","et","je","rentre","à","l'hôtel"]}]}],"formula":[{"k":"X","t":"Từ / Mệnh đề 1"},{"k":"P","t":"et"},{"k":"X","t":"Từ / Mệnh đề 2"}],"points":["Et (và) nối hai danh từ, hai tính từ hoặc hai mệnh đề (\"un café et un thé\", \"je dîne et je rentre\").","Mỗi danh từ giữ mạo từ hoặc từ sở hữu riêng (\"mon frère et ma sœur\"), không dùng chung như tiếng Việt.","Không bao giờ nối âm sau et: \"et un\" đọc là \"ê a~\", không đọc \"ê-ta~\".","Liệt kê nhiều thứ thì chỉ đặt et trước thứ cuối cùng (\"du pain, du fromage et du vin\")."],"mistakes":[{"wrong":"Mon frère et sœur habitent à Paris.","right":"Mon frère et ma sœur habitent à Paris.","why":"Mỗi danh từ cần từ sở hữu riêng: sœur là giống cái nên phải có ma."},{"wrong":"Du pain et du fromage et du vin.","right":"Du pain, du fromage et du vin.","why":"Khi liệt kê, dùng dấu phẩy và chỉ đặt et trước món cuối."}],"compare":"Giống tiếng Việt, et đứng giữa hai thứ được nối; khác ở chỗ mỗi danh từ cần mạo từ riêng (un café et un thé = một cà phê và một trà).","tip":"Et đọc gọn là \"ê\" như tiếng gọi bạn \"ê!\", và không bao giờ nối âm với từ đứng sau.","how":["Đặt et trước danh từ có mạo từ un thé → et un thé, rồi thêm Un café ở trước và s'il vous plaît ở cuối → Un café et un thé s'il vous plaît.","Đặt et trước ma sœur → et ma sœur, thêm Mon frère ở đầu và habitent à Paris ở cuối → Mon frère et ma sœur habitent à Paris.","Đặt et trước mệnh đề je rentre → et je rentre, thêm Je dîne ở trước và à l'hôtel ở cuối → Je dîne et je rentre à l'hôtel."],"dialog":[{"who":"A","t":"Vous désirez ?","ph":"vu đê-zi-RÊ","vi":"Quý khách dùng gì ạ?","hl":[]},{"who":"B","t":"Un croissant et un jus d'orange.","ph":"a~ kroa-XA~ ê a~ JUY đo-RA~J","vi":"Một bánh sừng bò và một ly nước cam.","hl":["et"]},{"who":"A","t":"Et pour vous, madame ?","ph":"ê pur VU ma-ĐAM","vi":"Còn bà dùng gì ạ?","hl":["Et"]},{"who":"B","t":"Un thé et une tarte.","ph":"a~ TÊ ê uyn TART","vi":"Một trà và một bánh tart.","hl":["et"]}],"more":[{"t":"Paul et Marie arrivent.","ph":"pôl ê ma-RI a-RIV","vi":"Paul và Marie đến.","hl":["et"],"tokens":["Paul","et","Marie","arrivent"]},{"t":"J'ai faim et soif.","ph":"JÊ FE~ ê XOAF","vi":"Tôi đói và khát.","hl":["et"],"tokens":["J'ai","faim","et","soif"]},{"t":"Il fait beau et chaud.","ph":"il FE BÔ ê SHÔ","vi":"Trời đẹp và nóng.","hl":["et"],"tokens":["Il","fait","beau","et","chaud"]},{"t":"Je voudrais du pain et du fromage.","ph":"jơ vu-ĐRÊ đuy PE~ ê đuy fro-MAJ","vi":"Tôi muốn bánh mì và phô mai.","hl":["et"],"tokens":["Je","voudrais","du","pain","et","du","fromage"]},{"t":"Elle est gentille et très drôle.","ph":"e-LE ja~-TIY ê TRE ĐRÔL","vi":"Cô ấy dễ thương và rất vui tính.","hl":["et"],"tokens":["Elle","est","gentille","et","très","drôle"]},{"t":"Je prends une douche et je sors.","ph":"jơ PRA~ uyn ĐUSH ê jơ XOR","vi":"Tôi tắm rồi đi ra ngoài.","hl":["et"],"tokens":["Je","prends","une","douche","et","je","sors"]}]},{"id":28,"vi":"nhưng","note":"Mais (nhưng) nối hai ý đối lập; câu ngắn không cần dấu phẩy trước mais.","pivot":{"t":"mais","ph":"MÊ"},"branches":[{"steps":[{"t":"délicieux","ph":"đê-li-XIƠ","vi":"ngon","hl":[]},{"t":"mais délicieux","ph":"MÊ đê-li-XIƠ","vi":"nhưng ngon","hl":["mais"]},{"t":"C'est cher mais délicieux.","ph":"xê SHER mê đê-li-XIƠ","vi":"Đắt nhưng ngon.","hl":["mais"],"tokens":["C'est","cher","mais","délicieux"]}]},{"steps":[{"t":"propre","ph":"PRO-PR","vi":"sạch","hl":[]},{"t":"mais propre","ph":"MÊ PRO-PR","vi":"nhưng sạch","hl":["mais"]},{"t":"La chambre est petite mais propre.","ph":"la SHA~-BR e pơ-TIT mê PRO-PR","vi":"Phòng nhỏ nhưng sạch sẽ.","hl":["mais"],"tokens":["La","chambre","est","petite","mais","propre"]}]},{"steps":[{"t":"comprends","ph":"ko~-PRA~","vi":"hiểu","hl":[]},{"t":"mais je comprends","ph":"MÊ jơ ko~-PRA~","vi":"nhưng tôi hiểu","hl":["mais"]},{"t":"Je parle peu mais je comprends.","ph":"jơ PARL PƠ mê jơ ko~-PRA~","vi":"Tôi nói ít nhưng tôi hiểu.","hl":["mais"],"tokens":["Je","parle","peu","mais","je","comprends"]}]}],"formula":[{"k":"X","t":"Ý 1"},{"k":"P","t":"mais"},{"k":"X","t":"Ý 2 (trái ngược)"}],"points":["Mais (nhưng) nối hai ý trái ngược nhau (\"cher mais délicieux\").","Câu ngắn không cần dấu phẩy trước mais; câu dài có thể thêm dấu phẩy (\"Je voudrais venir, mais je travaille demain\").","Mais luôn đứng đầu ý thứ hai, ngay trước từ hoặc mệnh đề trái ngược.","Mais còn dùng để nhấn mạnh: \"Mais oui !\" (Tất nhiên rồi!)."],"mistakes":[{"wrong":"Bien que c'est cher mais c'est bon.","right":"C'est cher mais c'est bon.","why":"Tiếng Việt hay nói \"tuy ... nhưng\", tiếng Pháp chỉ dùng một từ mais, không ghép đôi."}],"compare":"Giống hệt tiếng Việt: mais đứng giữa hai ý đối lập như \"nhưng\"; chỉ khác là tiếng Pháp không có cặp \"tuy ... nhưng\".","tip":"Mais đọc là \"mê\": \"Mê\" món này nhưng (mais) đắt quá!","how":["Đặt mais trước tính từ délicieux → mais délicieux, rồi thêm C'est cher ở trước để tạo ý đối lập → C'est cher mais délicieux.","Đặt mais trước tính từ propre → mais propre, thêm La chambre est petite ở trước → La chambre est petite mais propre.","Đặt mais trước mệnh đề je comprends → mais je comprends, thêm Je parle peu ở trước → Je parle peu mais je comprends."],"dialog":[{"who":"A","t":"Tu aimes Paris ?","ph":"tuy EM pa-RI","vi":"Bạn thích Paris không?","hl":[]},{"who":"B","t":"Oui, mais c'est très cher.","ph":"uy mê xê TRE SHER","vi":"Thích, nhưng đắt lắm.","hl":["mais"]},{"who":"A","t":"Et le métro ?","ph":"ê lơ mê-TRÔ","vi":"Còn tàu điện ngầm thì sao?","hl":[]},{"who":"B","t":"Pratique mais toujours plein de monde.","ph":"pra-TIK mê tu-JUR PLE~ đơ MO~Đ","vi":"Tiện nhưng lúc nào cũng đông người.","hl":["mais"]}],"more":[{"t":"Il est petit mais rapide.","ph":"i-LE pơ-TI mê ra-PIT","vi":"Nó nhỏ nhưng nhanh.","hl":["mais"],"tokens":["Il","est","petit","mais","rapide"]},{"t":"C'est loin mais très joli.","ph":"xê LOE~ mê TRE jo-LI","vi":"Xa nhưng rất đẹp.","hl":["mais"],"tokens":["C'est","loin","mais","très","joli"]},{"t":"Je suis fatigué mais content.","ph":"jơ XUY fa-ti-GHÊ mê ko~-TA~","vi":"Tôi mệt nhưng vui.","hl":["mais"],"tokens":["Je","suis","fatigué","mais","content"]},{"t":"J'aime le café mais pas le thé.","ph":"JEM lơ ka-FÊ mê PA lơ TÊ","vi":"Tôi thích cà phê nhưng không thích trà.","hl":["mais"],"tokens":["J'aime","le","café","mais","pas","le","thé"]},{"t":"Je voudrais venir mais je travaille.","ph":"jơ vu-ĐRÊ vơ-NIR mê jơ tra-VAI","vi":"Tôi muốn đến nhưng tôi phải làm việc.","hl":["mais"],"tokens":["Je","voudrais","venir","mais","je","travaille"]},{"t":"L'hôtel est vieux mais le service est excellent.","ph":"lô-TEL e VIƠ mê lơ xer-VIX e-tek-xê-LA~","vi":"Khách sạn cũ nhưng phục vụ rất tốt.","hl":["mais"],"tokens":["L'hôtel","est","vieux","mais","le","service","est","excellent"]}]},{"id":29,"vi":"nếu","note":"Si (nếu) + thì hiện tại, mệnh đề chính ở hiện tại, mệnh lệnh hoặc tương lai; si thành s' trước il/ils.","pivot":{"t":"si","ph":"XI"},"branches":[{"steps":[{"t":"pleut","ph":"PLƠ","vi":"mưa","hl":[]},{"t":"s'il pleut","ph":"XIL PLƠ","vi":"nếu trời mưa","hl":["s'"]},{"t":"On reste ici s'il pleut.","ph":"o~ REST i-XI xil PLƠ","vi":"Nếu trời mưa thì mình ở lại đây.","hl":["s'"],"tokens":["On","reste","ici","s'il","pleut"]}]},{"steps":[{"t":"besoin","ph":"bơ-ZOE~","vi":"nhu cầu","hl":[]},{"t":"si vous avez besoin","ph":"XI vu-za-VÊ bơ-ZOE~","vi":"nếu anh cần","hl":["si"]},{"t":"Appelez-moi si vous avez besoin.","ph":"a-plê-MOA xi vu-za-VÊ bơ-ZOE~","vi":"Nếu anh cần thì cứ gọi tôi.","hl":["si"],"tokens":["Appelez-moi","si","vous","avez","besoin"]}]},{"steps":[{"t":"temps","ph":"TA~","vi":"thời gian","hl":[]},{"t":"si j'ai le temps","ph":"XI JÊ lơ TA~","vi":"nếu tôi có thời gian","hl":["si"]},{"t":"Je viendrai si j'ai le temps.","ph":"jơ viê~-ĐRÊ xi JÊ lơ TA~","vi":"Nếu có thời gian tôi sẽ đến.","hl":["si"],"tokens":["Je","viendrai","si","j'ai","le","temps"]}]}],"formula":[{"k":"X","t":"Mệnh đề chính"},{"k":"P","t":"si"},{"k":"S","t":"Chủ ngữ"},{"k":"V","t":"Động từ (hiện tại)"}],"points":["Si (nếu) + thì hiện tại; mệnh đề chính dùng hiện tại, tương lai hoặc mệnh lệnh (\"On reste ici s'il pleut\").","KHÔNG dùng thì tương lai sau si: nói \"si j'ai le temps\", không nói \"si j'aurai le temps\".","Si chỉ rút thành s' trước il/ils (s'il, s'ils); trước elle, on vẫn giữ si (\"si elle vient\").","Mệnh đề si đứng đầu hay cuối câu đều được; khi đứng đầu thì thêm dấu phẩy (\"S'il pleut, on reste ici\")."],"mistakes":[{"wrong":"Si j'aurai le temps, je viendrai.","right":"Si j'ai le temps, je viendrai.","why":"Sau si dùng thì hiện tại, dù nghĩa là tương lai."},{"wrong":"Si il pleut, on reste ici.","right":"S'il pleut, on reste ici.","why":"Si gặp il phải rút gọn thành s'il."}],"compare":"Giống tiếng Việt \"nếu ... thì ...\" nhưng tiếng Pháp không có từ \"thì\", và động từ sau si không bao giờ ở thì tương lai.","tip":"Si gặp il là dính liền thành s'il, như hai người bạn khoác vai nhau.","how":["Si gặp il nên rút thành s' → s'il pleut, rồi đặt mệnh đề chính On reste ici ở trước → On reste ici s'il pleut.","Đặt si trước vous avez besoin → si vous avez besoin, thêm mệnh lệnh Appelez-moi ở trước → Appelez-moi si vous avez besoin.","Đặt si trước j'ai le temps (thì hiện tại) → si j'ai le temps, thêm mệnh đề tương lai Je viendrai ở trước → Je viendrai si j'ai le temps."],"dialog":[{"who":"A","t":"On va à la plage demain ?","ph":"o~ VA a la PLAJ đơ-ME~","vi":"Mai mình đi biển nhé?","hl":[]},{"who":"B","t":"Oui, s'il fait beau.","ph":"uy xil FE BÔ","vi":"Ừ, nếu trời đẹp.","hl":["s'"]},{"who":"A","t":"Et s'il pleut ?","ph":"ê xil PLƠ","vi":"Còn nếu trời mưa?","hl":["s'"]},{"who":"B","t":"On visite le musée si tu veux.","ph":"o~ vi-ZIT lơ muy-ZÊ xi tuy VƠ","vi":"Thì mình đi bảo tàng, nếu bạn muốn.","hl":["si"]}],"more":[{"t":"Viens si tu peux.","ph":"VIE~ xi tuy PƠ","vi":"Đến nếu bạn có thể nhé.","hl":["si"],"tokens":["Viens","si","tu","peux"]},{"t":"On sort s'il fait beau.","ph":"o~ XOR xil FE BÔ","vi":"Mình ra ngoài nếu trời đẹp.","hl":["s'"],"tokens":["On","sort","s'il","fait","beau"]},{"t":"Dites-moi si vous avez faim.","ph":"đit-MOA xi vu-za-VÊ FE~","vi":"Hãy nói tôi biết nếu anh chị đói.","hl":["si"],"tokens":["Dites-moi","si","vous","avez","faim"]},{"t":"Je prends un taxi si c'est loin.","ph":"jơ PRA~ a~ tak-XI xi xê LOE~","vi":"Tôi sẽ đi taxi nếu xa.","hl":["si"],"tokens":["Je","prends","un","taxi","si","c'est","loin"]},{"t":"On dîne ensemble si vous êtes libres.","ph":"o~ ĐIN a~-XA~-BL xi vu-ZET LI-BR","vi":"Mình ăn tối cùng nhau nếu các bạn rảnh.","hl":["si"],"tokens":["On","dîne","ensemble","si","vous","êtes","libres"]},{"t":"Je t'appelle si le train est en retard.","ph":"jơ ta-PEL xi lơ TRE~ e-ta~ rơ-TAR","vi":"Tôi sẽ gọi bạn nếu tàu bị trễ.","hl":["si"],"tokens":["Je","t'appelle","si","le","train","est","en","retard"]}]},{"id":30,"vi":"này / kia","note":"Chỉ định: ce (giống đực), cette (giống cái), ces (số nhiều) = này; thêm -là (celui-là) để chỉ cái kia.","pivot":{"t":"ce ... -ci / -là","ph":"xơ ... XI / LA"},"branches":[{"steps":[{"t":"plat","ph":"PLA","vi":"món ăn","hl":[]},{"t":"ce plat","ph":"xơ PLA","vi":"món này","hl":["ce"]},{"t":"Je voudrais ce plat s'il vous plaît.","ph":"jơ vu-ĐRÊ xơ PLA xin vu PLÊ","vi":"Cho tôi món này.","hl":["ce"],"tokens":["Je","voudrais","ce","plat","s'il","vous","plaît"]}]},{"steps":[{"t":"robe","ph":"RÔP","vi":"váy","hl":[]},{"t":"cette robe","ph":"xét RÔP","vi":"cái váy này","hl":["cette"]},{"t":"Combien coûte cette robe ?","ph":"ko~-BIE~ KUT xét RÔP","vi":"Cái váy này bao nhiêu tiền?","hl":["cette"],"tokens":["Combien","coûte","cette","robe"]}]},{"steps":[{"t":"celui","ph":"xơ-LUY","vi":"cái (đó)","hl":[]},{"t":"celui-là","ph":"xơ-luy-LA","vi":"cái kia","hl":["celui-là"]},{"t":"Je préfère celui-là.","ph":"jơ prê-FER xơ-luy-LA","vi":"Tôi thích cái kia hơn.","hl":["celui-là"],"tokens":["Je","préfère","celui-là"]}]}],"formula":[{"k":"P","t":"ce / cette / ces"},{"k":"O","t":"Danh từ"},{"k":"P","t":"(-ci / -là)"}],"points":["Ce + danh từ giống đực (ce plat), cette + giống cái (cette robe), ces + số nhiều (ces chaussures) = ... này / đó.","Trước danh từ giống đực bắt đầu bằng nguyên âm hoặc h câm, ce đổi thành cet (cet hôtel).","Muốn phân biệt \"này\" và \"kia\", thêm -ci / -là sau danh từ (ce plat-ci, ce plat-là).","Đại từ thay cho danh từ: celui-là (cái kia, giống đực), celle-là (giống cái), ceux-là (số nhiều)."],"mistakes":[{"wrong":"Je voudrais ce robe.","right":"Je voudrais cette robe.","why":"Robe là danh từ giống cái nên phải dùng cette."},{"wrong":"Ce hôtel est cher.","right":"Cet hôtel est cher.","why":"Trước danh từ giống đực bắt đầu bằng nguyên âm hoặc h câm, ce đổi thành cet."}],"compare":"Tiếng Việt để \"này / kia\" SAU danh từ (cái váy này); tiếng Pháp đặt ce/cette TRƯỚC danh từ và đổi theo giống, số.","tip":"Ce đực, cette cái, ces nhiều; thêm -là là chỉ tay ra xa \"đằng kia\".","how":["Plat là danh từ giống đực nên đặt ce phía trước → ce plat, rồi thêm Je voudrais ở đầu và s'il vous plaît ở cuối → Je voudrais ce plat s'il vous plaît.","Robe là danh từ giống cái nên dùng cette → cette robe, thêm Combien coûte ở trước và dấu ? → Combien coûte cette robe ?","Gắn -là vào đại từ celui → celui-là (cái kia), rồi đặt sau Je préfère → Je préfère celui-là."],"dialog":[{"who":"A","t":"Vous aimez ce chapeau ?","ph":"vu-ze-MÊ xơ sha-PÔ","vi":"Anh thích cái mũ này không?","hl":["ce"]},{"who":"B","t":"Non, je préfère celui-là.","ph":"no~ jơ prê-FER xơ-luy-LA","vi":"Không, tôi thích cái kia hơn.","hl":["celui-là"]},{"who":"A","t":"Et ces lunettes ?","ph":"ê xê luy-NET","vi":"Còn cặp kính này?","hl":["ces"]},{"who":"B","t":"Oui, elles sont parfaites !","ph":"uy el XO~ par-FET","vi":"Ừ, cặp này hoàn hảo!","hl":[]}],"more":[{"t":"Cette chambre est grande.","ph":"xét SHA~-BR e GRA~Đ","vi":"Phòng này rộng.","hl":["Cette"],"tokens":["Cette","chambre","est","grande"]},{"t":"Ce bus va à la gare ?","ph":"xơ BUYT VA a la GAR","vi":"Xe buýt này đi ra ga à?","hl":["Ce"],"tokens":["Ce","bus","va","à","la","gare"]},{"t":"J'aime beaucoup ces chaussures.","ph":"JEM bô-KU xê shô-XUYR","vi":"Tôi rất thích đôi giày này.","hl":["ces"],"tokens":["J'aime","beaucoup","ces","chaussures"]},{"t":"Nous prenons cette table-là.","ph":"nu prơ-NO~ xét ta-blơ-LA","vi":"Chúng tôi lấy cái bàn kia.","hl":["cette","-là"],"tokens":["Nous","prenons","cette","table-là"]},{"t":"Cet hôtel est près de la plage.","ph":"xé-tô-TEL e PRE đơ la PLAJ","vi":"Khách sạn này gần bãi biển.","hl":["Cet"],"tokens":["Cet","hôtel","est","près","de","la","plage"]},{"t":"Ce plat-ci est meilleur que celui-là.","ph":"xơ PLA-XI e me-YƠR kơ xơ-luy-LA","vi":"Món này ngon hơn món kia.","hl":["Ce","-ci","celui-là"],"tokens":["Ce","plat-ci","est","meilleur","que","celui-là"]}]},{"id":31,"vi":"của","note":"Tính từ sở hữu đứng trước danh từ: mon (giống đực), ma (giống cái), mes (số nhiều) = của tôi; X de Y = X của Y.","pivot":{"t":"mon / ma / mes","ph":"MO~ / MA / MÊ"},"branches":[{"steps":[{"t":"valise","ph":"va-LIZ","vi":"va li","hl":[]},{"t":"ma valise","ph":"ma va-LIZ","vi":"va li của tôi","hl":["ma"]},{"t":"Où est ma valise ?","ph":"U e ma va-LIZ","vi":"Va li của tôi đâu rồi?","hl":["ma"],"tokens":["Où","est","ma","valise"]}]},{"steps":[{"t":"passeport","ph":"pas-PÔR","vi":"hộ chiếu","hl":[]},{"t":"mon passeport","ph":"mo~ pas-PÔR","vi":"hộ chiếu của tôi","hl":["mon"]},{"t":"J'ai perdu mon passeport.","ph":"JÊ per-ĐUY mo~ pas-PÔR","vi":"Tôi bị mất hộ chiếu.","hl":["mon"],"tokens":["J'ai","perdu","mon","passeport"]}]},{"steps":[{"t":"clés","ph":"KLÊ","vi":"chìa khóa","hl":[]},{"t":"mes clés","ph":"mê KLÊ","vi":"chìa khóa của tôi","hl":["mes"]},{"t":"Je cherche mes clés.","ph":"jơ SHERSH mê KLÊ","vi":"Tôi đang tìm chìa khóa của tôi.","hl":["mes"],"tokens":["Je","cherche","mes","clés"]}]}],"formula":[{"k":"P","t":"mon / ma / mes"},{"k":"O","t":"Danh từ"}],"points":["Mon + danh từ giống đực (mon passeport), ma + giống cái (ma valise), mes + số nhiều (mes clés) = ... của tôi.","Từ sở hữu đứng TRƯỚC danh từ và thay cho mạo từ (không nói \"le mon passeport\").","Trước danh từ giống cái bắt đầu bằng nguyên âm vẫn dùng mon cho dễ đọc (mon amie, mon adresse).","Của người khác: ton/ta/tes (của bạn), son/sa/ses (của anh ấy/cô ấy), votre/vos (của ông bà); X de Y = X của Y (la voiture de Paul)."],"mistakes":[{"wrong":"La valise de moi.","right":"Ma valise.","why":"\"Vali của tôi\" không dịch từng chữ mà dùng từ sở hữu ma đặt trước danh từ."},{"wrong":"Ma adresse est ici.","right":"Mon adresse est ici.","why":"Adresse là giống cái nhưng bắt đầu bằng nguyên âm nên dùng mon."}],"compare":"Tiếng Việt đặt \"của tôi\" sau danh từ (vali của tôi); tiếng Pháp đặt mon/ma/mes trước và đổi theo giống, số của đồ vật, không theo người sở hữu.","tip":"Nhìn đồ vật chứ đừng nhìn người: ma valise, mon passeport, mes clés, dù bạn là nam hay nữ!","how":["Valise là danh từ giống cái nên dùng ma → ma valise, rồi thêm Où est ở trước và dấu ? → Où est ma valise ?","Passeport là danh từ giống đực nên dùng mon → mon passeport, thêm J'ai perdu ở trước → J'ai perdu mon passeport.","Clés là số nhiều nên dùng mes → mes clés, thêm Je cherche ở trước → Je cherche mes clés."],"dialog":[{"who":"A","t":"Où est mon téléphone ?","ph":"U e mo~ tê-lê-FON","vi":"Điện thoại của tôi đâu rồi?","hl":["mon"]},{"who":"B","t":"Il est dans ton sac.","ph":"i-LE đa~ to~ XAK","vi":"Nó ở trong túi của bạn đó.","hl":[]},{"who":"A","t":"Et mes lunettes ?","ph":"ê mê luy-NET","vi":"Còn kính của tôi?","hl":["mes"]},{"who":"B","t":"Sur la table, à côté de ma tasse.","ph":"xuyr la TA-BL a kô-TÊ đơ ma TAX","vi":"Trên bàn, cạnh cái cốc của tôi.","hl":["ma"]}],"more":[{"t":"Voici mon billet.","ph":"voa-XI mo~ bi-YÊ","vi":"Đây là vé của tôi.","hl":["mon"],"tokens":["Voici","mon","billet"]},{"t":"Ma chambre est petite.","ph":"ma SHA~-BR e pơ-TIT","vi":"Phòng của tôi nhỏ.","hl":["Ma"],"tokens":["Ma","chambre","est","petite"]},{"t":"Mes amis sont français.","ph":"mê-za-MI xo~ fra~-XÊ","vi":"Bạn bè của tôi là người Pháp.","hl":["Mes"],"tokens":["Mes","amis","sont","français"]},{"t":"Je vous présente ma femme.","ph":"jơ vu prê-ZA~T ma FAM","vi":"Xin giới thiệu vợ tôi.","hl":["ma"],"tokens":["Je","vous","présente","ma","femme"]},{"t":"C'est la voiture de mon frère.","ph":"xê la voa-TUYR đơ mo~ FRER","vi":"Đây là xe của anh trai tôi.","hl":["mon"],"tokens":["C'est","la","voiture","de","mon","frère"]},{"t":"Mon adresse est dans mon sac à dos.","ph":"mo~-na-ĐRES e đa~ mo~ XAK a ĐÔ","vi":"Địa chỉ của tôi ở trong ba lô của tôi.","hl":["Mon","mon"],"tokens":["Mon","adresse","est","dans","mon","sac","à","dos"]}]},{"id":32,"vi":"ở / tại","note":"Vị trí: à + thành phố, en + tên nước giống cái, au (= à + le) + danh từ giống đực.","pivot":{"t":"à / en","ph":"A / A~"},"branches":[{"steps":[{"t":"Paris","ph":"pa-RI","vi":"Paris","hl":[]},{"t":"à Paris","ph":"a pa-RI","vi":"ở Paris","hl":["à"]},{"t":"J'habite à Paris depuis un an.","ph":"ja-BIT a pa-RI đơ-PUY a~-NA~","vi":"Tôi sống ở Paris được một năm rồi.","hl":["à"],"tokens":["J'habite","à","Paris","depuis","un","an"]}]},{"steps":[{"t":"France","ph":"FRA~X","vi":"nước Pháp","hl":[]},{"t":"en France","ph":"a~ FRA~X","vi":"ở Pháp","hl":["en"]},{"t":"Je travaille en France.","ph":"jơ tra-VAI a~ FRA~X","vi":"Tôi làm việc ở Pháp.","hl":["en"],"tokens":["Je","travaille","en","France"]}]},{"steps":[{"t":"restaurant","ph":"rết-tô-RA~","vi":"nhà hàng","hl":[]},{"t":"au restaurant","ph":"ô rết-tô-RA~","vi":"ở nhà hàng","hl":["au"]},{"t":"On mange au restaurant ce soir.","ph":"o~ MA~J ô rết-tô-RA~ xơ SOAR","vi":"Tối nay mình ăn ở nhà hàng.","hl":["au"],"tokens":["On","mange","au","restaurant","ce","soir"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"V","t":"Động từ"},{"k":"P","t":"à / en / au"},{"k":"O","t":"Nơi chốn"}],"points":["À + tên thành phố (\"à Paris\", \"à Hanoï\").","En + tên nước giống cái (đa số tận cùng bằng -e: en France, en Italie); au + nước giống đực (au Vietnam, au Japon).","À + le gộp thành au (au restaurant), à + les thành aux; còn à la, à l' giữ nguyên (à la gare, à l'hôtel).","Cùng giới từ này dùng cho cả \"ở\" lẫn \"đến\": \"Je vais à Paris\" (tôi đi Paris), \"J'habite à Paris\" (tôi sống ở Paris)."],"mistakes":[{"wrong":"J'habite en Paris.","right":"J'habite à Paris.","why":"Trước tên thành phố dùng à, en chỉ dùng cho nước giống cái."},{"wrong":"On mange à le restaurant.","right":"On mange au restaurant.","why":"À + le bắt buộc gộp thành au."}],"compare":"Tiếng Việt chỉ một từ \"ở\" cho mọi nơi; tiếng Pháp phải chọn à, en hay au tùy là thành phố, nước giống cái hay danh từ giống đực.","tip":"Câu thần chú: \"à phố, en nước, au quán\" — thành phố dùng à, nước giống cái dùng en, chỗ giống đực dùng au.","how":["Đặt à trước tên thành phố Paris → à Paris, rồi thêm J'habite ở trước và depuis un an ở cuối → J'habite à Paris depuis un an.","France là nước giống cái nên dùng en → en France, thêm Je travaille ở trước → Je travaille en France.","À + le restaurant gộp thành au → au restaurant, thêm On mange ở trước và ce soir ở cuối → On mange au restaurant ce soir."],"dialog":[{"who":"A","t":"Tu habites où ?","ph":"tuy a-BIT U","vi":"Bạn sống ở đâu?","hl":[]},{"who":"B","t":"J'habite à Lyon, en France.","ph":"ja-BIT a li-O~ a~ FRA~X","vi":"Mình sống ở Lyon, nước Pháp.","hl":["à","en"]},{"who":"A","t":"Et tu travailles au centre-ville ?","ph":"ê tuy tra-VAI ô xa~-trơ-VIL","vi":"Thế bạn làm việc ở trung tâm à?","hl":["au"]},{"who":"B","t":"Non, je travaille à l'aéroport.","ph":"no~ jơ tra-VAI a la-ê-rô-POR","vi":"Không, mình làm ở sân bay.","hl":["à"]}],"more":[{"t":"Je suis à l'hôtel.","ph":"jơ XUY a lô-TEL","vi":"Tôi đang ở khách sạn.","hl":["à"],"tokens":["Je","suis","à","l'hôtel"]},{"t":"Elle habite au Vietnam.","ph":"e-la-BIT ô viết-NAM","vi":"Cô ấy sống ở Việt Nam.","hl":["au"],"tokens":["Elle","habite","au","Vietnam"]},{"t":"Mon fils étudie au Japon.","ph":"mo~ FIX ê-tuy-ĐI ô ja-PO~","vi":"Con trai tôi học ở Nhật.","hl":["au"],"tokens":["Mon","fils","étudie","au","Japon"]},{"t":"On se retrouve à la gare ?","ph":"o~ xơ rơ-TRUV a la GAR","vi":"Mình gặp nhau ở ga nhé?","hl":["à"],"tokens":["On","se","retrouve","à","la","gare"]},{"t":"Nous sommes en vacances en Italie.","ph":"nu XOM a~ va-KA~X a~-ni-ta-LI","vi":"Chúng tôi đang đi nghỉ ở Ý.","hl":["en Italie"],"tokens":["Nous","sommes","en","vacances","en","Italie"]},{"t":"Je passe une semaine à Nice en juillet.","ph":"jơ PAX uyn xơ-MEN a NIX a~ jui-YÊ","vi":"Tôi ở Nice một tuần vào tháng Bảy.","hl":["à Nice"],"tokens":["Je","passe","une","semaine","à","Nice","en","juillet"]}]},{"id":33,"vi":"với","note":"Avec (với) + người hoặc vật; sau avec dùng đại từ nhấn mạnh moi, toi, vous.","pivot":{"t":"avec","ph":"a-VEK"},"branches":[{"steps":[{"t":"amis","ph":"a-MI","vi":"bạn bè","hl":[]},{"t":"avec mes amis","ph":"a-VEK mê-za-MI","vi":"với bạn bè tôi","hl":["avec"]},{"t":"Je voyage avec mes amis.","ph":"jơ voa-YAJ a-VEK mê-za-MI","vi":"Tôi đi du lịch với bạn bè.","hl":["avec"],"tokens":["Je","voyage","avec","mes","amis"]}]},{"steps":[{"t":"moi","ph":"MOA","vi":"tôi","hl":[]},{"t":"avec moi","ph":"a-VEK MOA","vi":"với tôi","hl":["avec"]},{"t":"Tu viens avec moi ?","ph":"tuy VIE~ a-VEK MOA","vi":"Bạn đi với tôi không?","hl":["avec"],"tokens":["Tu","viens","avec","moi"]}]},{"steps":[{"t":"lait","ph":"LÊ","vi":"sữa","hl":[]},{"t":"avec du lait","ph":"a-VEK đuy LÊ","vi":"với sữa","hl":["avec"]},{"t":"Un café avec du lait s'il vous plaît.","ph":"a~ ka-FÊ a-VEK đuy LÊ xin vu PLÊ","vi":"Cho tôi một cà phê với sữa.","hl":["avec"],"tokens":["Un","café","avec","du","lait","s'il","vous","plaît"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"V","t":"Động từ"},{"k":"P","t":"avec"},{"k":"O","t":"Người / Vật"}],"points":["Avec (với, cùng) đứng trước người hoặc vật đi kèm (\"avec mes amis\", \"avec du lait\").","Sau avec dùng đại từ nhấn mạnh: moi, toi, lui, elle, nous, vous, eux (\"avec moi\", không nói \"avec je\").","Avec còn chỉ phương tiện, cách thức: \"payer avec la carte\" (trả bằng thẻ).","Ngược nghĩa với avec là sans (không có): \"un café sans sucre\"."],"mistakes":[{"wrong":"Tu viens avec je ?","right":"Tu viens avec moi ?","why":"Sau giới từ phải dùng đại từ nhấn mạnh moi, không dùng je."},{"wrong":"Un café avec lait.","right":"Un café avec du lait.","why":"Đồ ăn uống không đếm được cần mạo từ bộ phận du / de la sau avec."}],"compare":"Giống tiếng Việt \"với\": đứng trước người hoặc vật đi kèm; khác ở chỗ \"với tôi\" phải là avec moi chứ không dùng je.","tip":"Muốn rủ ai đi cùng, chỉ cần hai chữ: \"Avec moi ?\" (Đi với mình không?)","how":["Đặt avec trước mes amis (nối âm thành mê-za-MI) → avec mes amis, thêm Je voyage ở trước → Je voyage avec mes amis.","Sau avec dùng đại từ nhấn mạnh moi → avec moi, thêm Tu viens ở trước và dấu ? → Tu viens avec moi ?","Đặt avec trước du lait (mạo từ bộ phận) → avec du lait, thêm Un café ở trước và s'il vous plaît ở cuối → Un café avec du lait s'il vous plaît."],"dialog":[{"who":"A","t":"Tu dînes avec qui ce soir ?","ph":"tuy ĐIN a-VEK KI xơ SOAR","vi":"Tối nay bạn ăn tối với ai?","hl":["avec"]},{"who":"B","t":"Avec mes collègues.","ph":"a-VEK mê ko-LEG","vi":"Với đồng nghiệp.","hl":["Avec"]},{"who":"A","t":"Je peux venir avec vous ?","ph":"jơ PƠ vơ-NIR a-VEK VU","vi":"Mình đi cùng được không?","hl":["avec"]},{"who":"B","t":"Bien sûr !","ph":"bie~ XUYR","vi":"Tất nhiên rồi!","hl":[]}],"more":[{"t":"Je pars avec lui.","ph":"jơ PAR a-VEK LUY","vi":"Tôi đi với anh ấy.","hl":["avec"],"tokens":["Je","pars","avec","lui"]},{"t":"Un thé avec du sucre.","ph":"a~ TÊ a-VEK đuy XUY-KR","vi":"Một trà có đường.","hl":["avec"],"tokens":["Un","thé","avec","du","sucre"]},{"t":"Elle habite avec ses parents.","ph":"e-la-BIT a-VEK xê pa-RA~","vi":"Cô ấy sống với bố mẹ.","hl":["avec"],"tokens":["Elle","habite","avec","ses","parents"]},{"t":"Je peux payer avec la carte ?","ph":"jơ PƠ pê-YÊ a-VEK la KART","vi":"Tôi trả bằng thẻ được không?","hl":["avec"],"tokens":["Je","peux","payer","avec","la","carte"]},{"t":"Une chambre avec vue sur la mer.","ph":"uyn SHA~-BR a-VEK VUY xuyr la MER","vi":"Một phòng nhìn ra biển.","hl":["avec"],"tokens":["Une","chambre","avec","vue","sur","la","mer"]},{"t":"Nous allons au musée avec les enfants.","ph":"nu-za-LO~ ô muy-ZÊ a-VEK lê-za~-FA~","vi":"Chúng tôi đi bảo tàng với bọn trẻ.","hl":["avec"],"tokens":["Nous","allons","au","musée","avec","les","enfants"]}]},{"id":34,"vi":"cho","note":"Pour + người (dành cho ai); donner/envoyer + vật + à + người (đưa/gửi cho ai); cho tôi = -moi sau động từ mệnh lệnh.","pivot":{"t":"pour / à","ph":"PUR / A"},"branches":[{"steps":[{"t":"toi","ph":"TOA","vi":"bạn","hl":[]},{"t":"pour toi","ph":"pur TOA","vi":"cho bạn","hl":["pour"]},{"t":"Ce cadeau est pour toi.","ph":"xơ ka-ĐÔ e pur TOA","vi":"Món quà này dành cho bạn.","hl":["pour"],"tokens":["Ce","cadeau","est","pour","toi"]}]},{"steps":[{"t":"donnez","ph":"đo-NÊ","vi":"đưa","hl":[]},{"t":"Donnez-moi","ph":"đo-nê-MOA","vi":"cho tôi","hl":["-moi"]},{"t":"Donnez-moi deux billets s'il vous plaît.","ph":"đo-nê-MOA đơ bi-YÊ xin vu PLÊ","vi":"Làm ơn cho tôi hai vé.","hl":["-moi"],"tokens":["Donnez-moi","deux","billets","s'il","vous","plaît"]}]},{"steps":[{"t":"mère","ph":"MER","vi":"mẹ","hl":[]},{"t":"à ma mère","ph":"a ma MER","vi":"cho mẹ tôi","hl":["à"]},{"t":"J'envoie une carte à ma mère.","ph":"ja~-VOA uyn KART a ma MER","vi":"Tôi gửi bưu thiếp cho mẹ.","hl":["à"],"tokens":["J'envoie","une","carte","à","ma","mère"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"V","t":"Động từ"},{"k":"O","t":"Vật"},{"k":"P","t":"pour / à"},{"k":"O","t":"Người nhận"}],"points":["Pour + người = dành cho ai (\"pour toi\", \"pour ma mère\").","Donner, envoyer, offrir + vật + à + người = đưa / gửi / tặng cho ai (\"J'envoie une carte à ma mère\").","Câu mệnh lệnh \"cho tôi\" gắn -moi sau động từ bằng gạch nối (\"Donnez-moi\", \"Montrez-moi\").","Ngoài câu mệnh lệnh, \"cho tôi\" là me đứng trước động từ (\"Il me donne la clé\")."],"mistakes":[{"wrong":"Donnez pour moi deux billets.","right":"Donnez-moi deux billets.","why":"\"Cho tôi\" trong câu mệnh lệnh là -moi gắn sau động từ, không dùng pour."},{"wrong":"J'envoie ma mère une carte.","right":"J'envoie une carte à ma mère.","why":"Người nhận phải có à phía trước và thường đứng sau vật được gửi."}],"compare":"Tiếng Việt chỉ có một chữ \"cho\"; tiếng Pháp tách thành pour (dành cho), à (đưa/gửi cho) và -moi gắn sau động từ mệnh lệnh.","tip":"Quà thì pour, gửi thì à, xin thì -moi: \"pour toi\" (tặng bạn), \"à ma mère\" (gửi mẹ), \"Donnez-moi\" (cho tôi).","how":["Đặt pour trước đại từ toi → pour toi, rồi thêm Ce cadeau est ở trước → Ce cadeau est pour toi.","Gắn -moi sau động từ mệnh lệnh donnez → Donnez-moi, thêm deux billets và s'il vous plaît ở sau → Donnez-moi deux billets s'il vous plaît.","Đặt à trước người nhận ma mère → à ma mère, thêm J'envoie une carte ở trước → J'envoie une carte à ma mère."],"dialog":[{"who":"A","t":"C'est pour qui, ces fleurs ?","ph":"xê pur KI xê FLƠR","vi":"Hoa này để tặng ai vậy?","hl":["pour"]},{"who":"B","t":"Pour ma femme, c'est son anniversaire.","ph":"pur ma FAM xê xo~-na-ni-ver-XER","vi":"Cho vợ tôi, hôm nay sinh nhật cô ấy.","hl":["Pour"]},{"who":"A","t":"Je fais un joli paquet ?","ph":"jơ FE a~ jo-LI pa-KÊ","vi":"Tôi gói đẹp cho anh nhé?","hl":[]},{"who":"B","t":"Oui, et donnez-moi une carte aussi.","ph":"uy ê đo-nê-MOA uyn KART ô-XI","vi":"Vâng, và cho tôi thêm một tấm thiệp.","hl":["-moi"]}],"more":[{"t":"C'est pour vous.","ph":"xê pur VU","vi":"Cái này dành cho anh chị.","hl":["pour"],"tokens":["C'est","pour","vous"]},{"t":"Donnez-moi la clé s'il vous plaît.","ph":"đo-nê-MOA la KLÊ xin vu PLÊ","vi":"Làm ơn đưa tôi chìa khóa.","hl":["-moi"],"tokens":["Donnez-moi","la","clé","s'il","vous","plaît"]},{"t":"J'achète du pain pour mes enfants.","ph":"ja-SHET đuy PE~ pur mê-za~-FA~","vi":"Tôi mua bánh mì cho các con.","hl":["pour"],"tokens":["J'achète","du","pain","pour","mes","enfants"]},{"t":"Elle écrit une lettre à son ami.","ph":"e-lê-KRI uyn LE-TR a xo~-na-MI","vi":"Cô ấy viết thư cho bạn.","hl":["à son"],"tokens":["Elle","écrit","une","lettre","à","son","ami"]},{"t":"Il donne son billet au contrôleur.","ph":"il ĐON xo~ bi-YÊ ô ko~-trô-LƠR","vi":"Anh ấy đưa vé cho người soát vé.","hl":["au"],"tokens":["Il","donne","son","billet","au","contrôleur"]},{"t":"Je voudrais une table pour quatre personnes.","ph":"jơ vu-ĐRÊ uyn TA-BL pur KA-TR per-XON","vi":"Tôi muốn một bàn cho bốn người.","hl":["pour"],"tokens":["Je","voudrais","une","table","pour","quatre","personnes"]}]},{"id":35,"vi":"phải","note":"Devoir (phải) + động từ nguyên mẫu: je dois, nous devons; il faut + nguyên mẫu = cần phải (chung chung).","pivot":{"t":"devoir","ph":"đơ-VOAR"},"branches":[{"steps":[{"t":"partir","ph":"par-TIR","vi":"đi","hl":[]},{"t":"dois partir","ph":"ĐOA par-TIR","vi":"phải đi","hl":["dois"]},{"t":"Je dois partir maintenant.","ph":"jơ ĐOA par-TIR me~t-NA~","vi":"Tôi phải đi bây giờ.","hl":["dois"],"tokens":["Je","dois","partir","maintenant"]}]},{"steps":[{"t":"changer","ph":"sha~-JÊ","vi":"đổi","hl":[]},{"t":"devons changer","ph":"đơ-VO~ sha~-JÊ","vi":"phải đổi","hl":["devons"]},{"t":"Nous devons changer de train.","ph":"nu đơ-VO~ sha~-JÊ đơ TRE~","vi":"Chúng tôi phải đổi tàu.","hl":["devons"],"tokens":["Nous","devons","changer","de","train"]}]},{"steps":[{"t":"réserver","ph":"rê-zer-VÊ","vi":"đặt trước","hl":[]},{"t":"Il faut réserver","ph":"il FÔ rê-zer-VÊ","vi":"phải đặt trước","hl":["Il faut"]},{"t":"Il faut réserver à l'avance.","ph":"il FÔ rê-zer-VÊ a la-VA~X","vi":"Phải đặt chỗ trước.","hl":["Il faut"],"tokens":["Il","faut","réserver","à","l'avance"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"P","t":"devoir (chia)"},{"k":"V","t":"Động từ nguyên mẫu"},{"k":"O","t":"(Tân ngữ)"}],"points":["Devoir (phải) + động từ nguyên mẫu; chia: je dois, tu dois, il doit, nous devons, vous devez, ils doivent.","Động từ đứng sau devoir luôn ở nguyên mẫu (\"je dois partir\", không nói \"je dois pars\").","Il faut + nguyên mẫu = cần phải, nói chung chung không chỉ ai (\"Il faut réserver\").","Phủ định ne ... pas devoir = không được làm gì (\"Vous ne devez pas fumer ici\")."],"mistakes":[{"wrong":"Je dois pars maintenant.","right":"Je dois partir maintenant.","why":"Sau devoir động từ phải để nguyên mẫu, không chia."},{"wrong":"Il faut je réserve.","right":"Je dois réserver.","why":"Il faut không đi với chủ ngữ + động từ chia; muốn nói ai phải làm gì thì dùng devoir."}],"compare":"Giống tiếng Việt \"phải + động từ\"; khác ở chỗ devoir phải chia theo chủ ngữ, còn động từ theo sau để nguyên mẫu.","tip":"Bộ ba dễ nhớ: tôi phải = je dois (đoa), chúng tôi phải = nous devons (đơ-VO~), ai cũng phải = il faut (il FÔ).","how":["Chia devoir với je thành dois rồi đặt trước partir → dois partir, thêm Je ở đầu và maintenant ở cuối → Je dois partir maintenant.","Chia devoir với nous thành devons rồi ghép với changer → devons changer, thêm Nous ở đầu và de train ở cuối → Nous devons changer de train.","Dùng Il faut (cần phải, nói chung) trước réserver → Il faut réserver, thêm à l'avance ở cuối → Il faut réserver à l'avance."],"dialog":[{"who":"A","t":"Tu restes encore un peu ?","ph":"tuy REST a~-KOR a~ PƠ","vi":"Bạn ở lại thêm chút nữa không?","hl":[]},{"who":"B","t":"Non, je dois rentrer à l'hôtel.","ph":"no~ jơ ĐOA ra~-TRÊ a lô-TEL","vi":"Không, mình phải về khách sạn.","hl":["dois"]},{"who":"A","t":"Pourquoi ?","ph":"pur-KOA","vi":"Sao vậy?","hl":[]},{"who":"B","t":"Nous devons partir tôt demain.","ph":"nu đơ-VO~ par-TIR TÔ đơ-ME~","vi":"Sáng mai bọn mình phải đi sớm.","hl":["devons"]}],"more":[{"t":"Tu dois venir.","ph":"tuy ĐOA vơ-NIR","vi":"Bạn phải đến nhé.","hl":["dois"],"tokens":["Tu","dois","venir"]},{"t":"Il doit travailler ce soir.","ph":"il ĐOA tra-va-YÊ xơ SOAR","vi":"Tối nay anh ấy phải làm việc.","hl":["doit"],"tokens":["Il","doit","travailler","ce","soir"]},{"t":"Il faut prendre le métro.","ph":"il FÔ PRA~-ĐR lơ mê-TRÔ","vi":"Phải đi tàu điện ngầm.","hl":["Il faut"],"tokens":["Il","faut","prendre","le","métro"]},{"t":"Vous devez payer à la caisse.","ph":"vu đơ-VÊ pê-YÊ a la KES","vi":"Anh chị phải trả tiền ở quầy thu ngân.","hl":["devez"],"tokens":["Vous","devez","payer","à","la","caisse"]},{"t":"Ils doivent arriver avant midi.","ph":"il ĐOAV a-ri-VÊ a-VA~ mi-ĐI","vi":"Họ phải đến trước buổi trưa.","hl":["doivent"],"tokens":["Ils","doivent","arriver","avant","midi"]},{"t":"Vous ne devez pas fumer dans la chambre.","ph":"vu nơ đơ-VÊ PA fuy-MÊ đa~ la SHA~-BR","vi":"Quý khách không được hút thuốc trong phòng.","hl":["devez"],"tokens":["Vous","ne","devez","pas","fumer","dans","la","chambre"]}]},{"id":36,"vi":"thử","note":"Essayer (thử) + danh từ (thử đồ), hoặc essayer de + động từ nguyên mẫu (thử làm gì).","pivot":{"t":"essayer","ph":"ê-xê-YÊ"},"branches":[{"steps":[{"t":"veste","ph":"VEST","vi":"áo khoác","hl":[]},{"t":"essayer cette veste","ph":"ê-xê-YÊ xét VEST","vi":"thử áo khoác này","hl":["essayer"]},{"t":"Je peux essayer cette veste ?","ph":"jơ PƠ ê-xê-YÊ xét VEST","vi":"Tôi mặc thử áo khoác này được không?","hl":["essayer"],"tokens":["Je","peux","essayer","cette","veste"]}]},{"steps":[{"t":"parler","ph":"par-LÊ","vi":"nói","hl":[]},{"t":"essaie de parler","ph":"ê-XÊ đơ par-LÊ","vi":"thử nói","hl":["essaie de"]},{"t":"J'essaie de parler français.","ph":"jê-XÊ đơ par-LÊ fra~-XÊ","vi":"Tôi thử nói tiếng Pháp.","hl":["essaie de"],"tokens":["J'essaie","de","parler","français"]}]},{"steps":[{"t":"plat","ph":"PLA","vi":"món ăn","hl":[]},{"t":"Essayez ce plat","ph":"ê-xê-YÊ xơ PLA","vi":"thử món này","hl":["Essayez"]},{"t":"Essayez ce plat typique !","ph":"ê-xê-YÊ xơ PLA ti-PIC","vi":"Hãy thử món đặc sản này!","hl":["Essayez"],"tokens":["Essayez","ce","plat","typique"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"P","t":"essayer (chia)"},{"k":"X","t":"(de)"},{"k":"O","t":"Danh từ / Động từ"}],"points":["Essayer + danh từ = thử (quần áo, món ăn): \"essayer cette veste\".","Essayer de + động từ nguyên mẫu = cố gắng / thử làm gì (\"J'essaie de parler français\"); de thành d' trước nguyên âm.","Chia: j'essaie, tu essaies, il essaie, nous essayons, vous essayez; mệnh lệnh lịch sự là \"Essayez !\".","Hỏi thử đồ ở cửa hàng dùng \"Je peux essayer ... ?\" (Tôi thử ... được không?)."],"mistakes":[{"wrong":"J'essaie parler français.","right":"J'essaie de parler français.","why":"Trước động từ phải thêm de: essayer de + nguyên mẫu."},{"wrong":"Je essaie cette veste.","right":"J'essaie cette veste.","why":"Je gặp nguyên âm phải rút thành j'."}],"compare":"Tiếng Việt \"thử\" đứng trước cả danh từ lẫn động từ; tiếng Pháp cũng vậy, nhưng trước động từ phải chèn thêm de.","tip":"Thử đồ: essayer + đồ; thử làm: essayer DE + làm. Có hành động là nhớ chèn de!","how":["Đặt essayer (nguyên mẫu vì đứng sau peux) trước cette veste → essayer cette veste, thêm Je peux ở đầu và dấu ? → Je peux essayer cette veste ?","Chia essayer với je thành essaie rồi thêm de trước động từ parler → essaie de parler, thêm J' ở đầu và français ở cuối → J'essaie de parler français.","Dùng mệnh lệnh Essayez trước ce plat → Essayez ce plat, thêm tính từ typique và dấu ! → Essayez ce plat typique !"],"dialog":[{"who":"A","t":"Je peux essayer ce pantalon ?","ph":"jơ PƠ ê-xê-YÊ xơ pa~-ta-LO~","vi":"Tôi thử cái quần này được không?","hl":["essayer"]},{"who":"B","t":"Bien sûr, la cabine est là-bas.","ph":"bie~ XUYR la ka-BIN e la-BA","vi":"Tất nhiên, phòng thử ở đằng kia.","hl":[]},{"who":"A","t":"Il est trop petit.","ph":"i-LE TRÔ pơ-TI","vi":"Nó chật quá.","hl":[]},{"who":"B","t":"Essayez cette taille, elle est plus grande.","ph":"ê-xê-YÊ xét TAI e-LE PLUY GRA~Đ","vi":"Anh thử cỡ này đi, nó rộng hơn.","hl":["Essayez"]}],"more":[{"t":"J'essaie ce chapeau.","ph":"jê-XÊ xơ sha-PÔ","vi":"Tôi thử cái mũ này.","hl":["essaie"],"tokens":["J'essaie","ce","chapeau"]},{"t":"Essayez encore une fois.","ph":"ê-xê-YÊ a~-KOR uyn FOA","vi":"Hãy thử lại lần nữa.","hl":["Essayez"],"tokens":["Essayez","encore","une","fois"]},{"t":"Nous essayons de dormir.","ph":"nu-zê-xê-YO~ đơ đor-MIR","vi":"Chúng tôi đang cố ngủ.","hl":["essayons de"],"tokens":["Nous","essayons","de","dormir"]},{"t":"Tu veux essayer la cuisine vietnamienne ?","ph":"tuy VƠ ê-xê-YÊ la kuy-ZIN viết-na-MIEN","vi":"Bạn muốn thử món ăn Việt Nam không?","hl":["essayer"],"tokens":["Tu","veux","essayer","la","cuisine","vietnamienne"]},{"t":"J'essaie d'apprendre dix mots par jour.","ph":"jê-XÊ đa-PRA~-ĐR đi MÔ par JUR","vi":"Tôi cố học mười từ mỗi ngày.","hl":["essaie d'"],"tokens":["J'essaie","d'apprendre","dix","mots","par","jour"]},{"t":"Elle essaie de trouver un hôtel pas cher.","ph":"e-lê-XÊ đơ tru-VÊ a~-nô-TEL pa SHER","vi":"Cô ấy đang cố tìm một khách sạn rẻ.","hl":["essaie de"],"tokens":["Elle","essaie","de","trouver","un","hôtel","pas","cher"]}]}];
